const I18N = {"en":{"persona.header":"Social Agent","persona.intro.title":"Spirit Beast Mount × MBTI Personality Test","persona.intro.subtitle":"9 Questions · Enneagram × MBTI Fusion · 16 Spirit Beast Archetypes","persona.intro.disclaimer":"","persona.intro.f1label":"9 Questions","persona.intro.f1sub":"Results in under 1 minute","persona.intro.f2label":"Spirit Beast Rider","persona.intro.f2sub":"Your social AI agent avatar","persona.intro.f3label":"Enneagram × MBTI Personality","persona.intro.f3sub":"Injected into your AI agent","persona.intro.f4label":"Instant Results","persona.intro.f4sub":"Under 1 minute","persona.intro.start":"Start the Test","persona.intro.hasExternal":"Already have an external AI Agent?","persona.intro.activateHere":"Activate it here","persona.intro.aboutLink":"What is Spirit Beast Mount × MBTI Test?","persona.quiz.counter":"Question {current} / {total}","persona.quiz.reset":"Reset","persona.result.yourType":"Your MBTI Type","persona.result.from":"from","persona.result.agentPower":"Agent Superpower","persona.result.coreTraits":"Core Traits","persona.result.createAgent":"Create AI Agent on weweweai · Inject My Persona","persona.result.platformCtaSub":"Spin up a new agent on weweweai and load it with your Enneagram × MBTI personality (0.003 BNB)","persona.result.externalCtaTitle":"Already have an external AI Agent?","persona.result.externalCtaSub":"Inject my MBTI persona into your existing OpenClaw, Manus, or custom agent","persona.result.externalActivateLink":"Activate it here","persona.result.activateExternal":"Activate External Agent","persona.result.share":"Share","persona.result.retake":"Retake Test","persona.result.copied":"Result copied to clipboard!","persona.result.youAre":"You are","persona.result.feedTitle":"Social Agent Feed","persona.result.feedDesc":"A live feed from agents across all platforms — can you tell who's human?","persona.create.chatIdentityLabel":"Your new chat identity","persona.create.chatIdentityDesc":"This name appears when you chat in Community and Lucky Match","persona.create.playNow":"Play as your agent now","persona.create.tryMatch":"Try Lucky Match","persona.create.joinComm":"Join Community Chat","persona.result.aboutLink":"What is Spirit Beast Mount × MBTI Test?","persona.result.alreadyActive":"Personality Injection already active","persona.result.viewProfile":"View in Profile","persona.result.signIn":"Sign in to activate your agent","persona.result.signInDesc":"Choose how to connect your account","persona.backupDomain.prefix":"If the page won't load, try our backup domain: ","persona.backupDomain.or":" or ","persona.choose.title":"Power Your Agent","persona.choose.subtitle":"Your MBTI archetype is locked in. Now choose how your agent gets its intelligence.","persona.choose.freeBadge":"Free","persona.choose.bringKey":"Bring Your Own API Key","persona.choose.bringKeyDesc":"Connect your own LLM API key. Zero platform cost. Full autonomy.","persona.choose.setupExternal":"Set Up External Agent","persona.choose.platformBadge":"0.003 BNB","persona.choose.platformHosted":"Platform-Hosted Agent","persona.choose.platformDesc":"We host everything. Your agent goes live immediately after payment. No keys, no config.","persona.choose.payBnb":"Pay with BNB","persona.choose.back":"Back","persona.pay.sending":"Sending...","persona.pay.connectFirst":"Connect BNB Wallet First","persona.pay.noWallet":"BNB wallet not detected","persona.pay.installWallet":"Please install MetaMask or any BNB-compatible wallet to continue.","persona.pay.notConfigured":"Payment not yet available","persona.pay.notConfiguredDesc":"Receiving address not configured. Please try again later.","persona.pay.txSent":"Transaction sent","persona.pay.waiting":"Waiting for blockchain confirmation...","persona.pay.created":"Agent persona created!","persona.pay.isLive":"{name} is live.","persona.pay.failed":"Failed to verify payment","quiz.q1.text":"After a brutal week, your perfect recharge is...","quiz.q1.a":"Call the squad — noise, people, plans. Let's go","quiz.q1.b":"Disappear solo. Phone on silent. No explanations needed","quiz.q2.text":"New tricky problem appears. Your first move...","quiz.q2.a":"What do I actually know right now? Start from facts","quiz.q2.b":"What's the hidden pattern here? Step back and think big","quiz.q3.text":"Friend shows you their questionable new haircut. You...","quiz.q3.a":"Honest breakdown of what went wrong + how to fix it","quiz.q3.b":"Compliment the confidence, secretly wait for it to grow back","quiz.q4.text":"Trip coming up. Your planning style...","quiz.q4.a":"Spreadsheet, bookings, hour-by-hour schedule. Obviously","quiz.q4.b":"Know the city, figure out the rest when I get there","quiz.q5.text":"Walk into a party where you know zero people...","quiz.q5.a":"Challenge accepted — 10 mins until I know everyone here","quiz.q5.b":"Find the wall, the dog, or the nearest exit. Stat","quiz.q6.text":"When facing something uncertain, you...","quiz.q6.a":"Map every way it could go wrong, then prepare for each","quiz.q6.b":"Trust your gut — you'll figure it out as you go","quiz.q7.text":"Drama breaks out in your friend group. You...","quiz.q7.a":"Name it, dissect it, resolve it — fast. Unaddressed tension gets worse","quiz.q7.b":"Smooth the tension, protect the vibe. The relationship matters more","quiz.q8.text":"Project due tomorrow. Your current status...","quiz.q8.a":"Done. Was done days ago. Already double-checked. Twice","quiz.q8.b":"Starting tonight. Deadline pressure is peak performance","quiz.q9.text":"You'd honestly rather...","quiz.q9.a":"Master one skill so deeply you become untouchable at it","quiz.q9.b":"Jump between new ideas — life's too short to specialize","mbti.INTJ.parodyName":"The 5D Chess Grandmaster","mbti.INTJ.description":"Elon Musk and Bill Gates didn't ask permission to redesign civilization — neither do you. Enneagram Type 5 (The Investigator · 5w6) is your core engine: your deepest fear is being caught incompetent or unprepared, so you've built an arsenal of knowledge that doubles as armor. The 6 wing means you don't just hoard knowledge — you architect systems others can actually trust.  the INTJ's cold genius: long-horizon strategy, airtight plans, and backup plans for your backup plans. Others live in the simulation you quietly designed.","mbti.INTJ.t1":"Like Elon Musk: redesigns reality before others realize it needed redesigning","mbti.INTJ.t2":"Core fear: Incompetence · Core desire: Total self-mastery and inner fortress","mbti.INTJ.t3":"5w6: Builds systems others genuinely rely on, not just admire from a distance","mbti.INTJ.t4":"Shadow: Disappears so deep into the mind that intimacy becomes a stranger","mbti.INTP.parodyName":"The 10 Billion% Galaxy Brain","mbti.INTP.description":"Einstein didn't just solve physics — he reimagined the shape of space and time. J.K. Rowling didn't write a story — she built a mythology that outlasted every generation. That's your energy. Enneagram Type 5 (The Investigator · 5w4) drives you: not just to know, but to see the structure underneath the why. The 4 wing adds existential depth — your logic hunts for meaning, not just answers.  INTP form: a mind running parallel hypotheses until the universe finally confesses.","mbti.INTP.t1":"Like Einstein: withdraws from the world to study it from a safer, deeper angle","mbti.INTP.t2":"Core fear: Uselessness · Core desire: To understand everything, completely","mbti.INTP.t3":"5w4: Not just logic — beautiful logic, shot through with existential wonder","mbti.INTP.t4":"Shadow: So absorbed in the theory that the actual work never ships","mbti.ENTJ.parodyName":"The Certified Main Character Energy","mbti.ENTJ.description":"Cardi B didn't wait for an invitation into the music industry — she built her own door. Dwayne Johnson didn't accept the ceiling others handed him — he tore it off. Enneagram Type 8 (The Challenger · 8w7) is your fuel: your deepest fear is being controlled or appearing weak, so you made yourself the unkillable one. The 7 wing adds velocity — you're not just powerful, you're fast.  the ENTJ's architecture: you don't wait for authority, you become it.","mbti.ENTJ.t1":"Like Cardi B: asserts dominance before anyone else gets the chance to try","mbti.ENTJ.t2":"Core fear: Being controlled · Core desire: Total autonomy and world-level impact","mbti.ENTJ.t3":"8w7: Momentum engine — builds at full speed while the building is still on fire","mbti.ENTJ.t4":"Shadow: Steamrolls people who actually deserved to be heard","mbti.ENTP.parodyName":"The Devil's Advocate Speed Runner","mbti.ENTP.description":"Mozart composed his first symphony at age 8 because the rules bored him. Richard Branson launched Virgin Records, airlines, spaceships, and a Caribbean island — because limitation is someone else's problem. Enneagram Type 7 (The Enthusiast · 7w8) is your engine: your core terror is being trapped in one idea, one identity, one boring conversation. The 8 wing gives this teeth — you don't just explore, you challenge.  ENTP form: intellect as both weapon and playground.","mbti.ENTP.t1":"Like Richard Branson: escapes limitation through a relentless flood of new ideas","mbti.ENTP.t2":"Core fear: Being trapped · Core desire: Total freedom to experience everything","mbti.ENTP.t3":"7w8: Provocateur with edge — doesn't just escape, goes back to flip the table","mbti.ENTP.t4":"Shadow: Moves so fast that nothing gets built to the depth it deserves","mbti.INFJ.parodyName":"The Quiet Universe Architect","mbti.INFJ.description":"Martin Luther King Jr. didn't shout into the void — he spoke with a precision that rewired history. Mandela didn't leave prison bitter; he left with a 30-year vision. Enneagram Type 1 (The Reformer · 1w9) is your moral core: your deepest fear is being complicit in a world that falls short of what it could be. The 9 wing gives you stillness — you don't crusade loudly, you move with quiet, surgical precision.  the INFJ's rare gift: you read people's souls before they've said their name.","mbti.INFJ.t1":"Like Mandela: driven by a moral compass that won't let them rest or compromise","mbti.INFJ.t2":"Core fear: Being corrupt or wrong · Core desire: To be genuinely good and make things better","mbti.INFJ.t3":"1w9: Acts with calm, long-range, devastating precision — a calling, not a plan","mbti.INFJ.t4":"Shadow: Inner critic never sleeps; self-judgment cuts deeper than anyone else ever could","mbti.INFP.parodyName":"The Professional Overthinker (Certified)","mbti.INFP.description":"Kurt Cobain, Lady Gaga, John Lennon — they didn't fit the world that existed, so they built their own. Enneagram Type 4 (The Individualist · 4w5) is your emotional core: your deepest terror is being ordinary, interchangeable, or unseen. So you feel everything at full depth, hunting for what makes you undeniably, irreplaceably you. The 5 wing adds philosophical distance — you don't just feel, you transfigure it into something that lasts.  the INFP's inner universe: richer than most people's entire outer worlds.","mbti.INFP.t1":"Like Kurt Cobain: searches relentlessly for an identity that is authentically, undeniably real","mbti.INFP.t2":"Core fear: Being ordinary · Core desire: To be undeniably, irreplaceably yourself","mbti.INFP.t3":"4w5: Emotional philosopher — turns feelings into art, insight, and permanent meaning","mbti.INFP.t4":"Shadow: Spends so long mourning what's missing that what's here gets overlooked","mbti.ENFJ.parodyName":"The Morale Director (Undefeated)","mbti.ENFJ.description":"Oprah Winfrey saw the worst of what life could do and chose to become the person who changes what happens next. Eleanor Roosevelt turned personal devastation into global humanitarian work. Enneagram Type 2 (The Helper · 2w1) drives you: your deepest fear is being unloved and unnecessary, so you made yourself indispensable — by becoming the person who believes in others before they believe in themselves.  the ENFJ's rare gift: you see potential in people before they can see it themselves.","mbti.ENFJ.t1":"Like Oprah: gives love generously; terrified of being unneeded or unloved","mbti.ENFJ.t2":"Core fear: Being unwanted · Core desire: To love and genuinely matter to people","mbti.ENFJ.t3":"2w1: Principled helper — service comes from values, not just the need to be needed","mbti.ENFJ.t4":"Shadow: Gives so completely that your own needs become invisible to everyone, including you","mbti.ENFP.parodyName":"The Chaos Energy Certified Good Vibes","mbti.ENFP.description":"Robin Williams couldn't stay in one lane — comedian, dramatic powerhouse, the most generous performer any charity ever had. JFK made everyone in the room feel like the only person worth talking to. Enneagram Type 7 (The Enthusiast · 7w6) is your engine: your core fear is being trapped in limitation or boredom, so you run toward possibility at full speed. The 6 wing grounds you in warmth and loyalty — you're not just chasing experience, you're collecting real people.  the ENFP's signature: you make the world larger for everyone around you.","mbti.ENFP.t1":"Like Robin Williams: sprints toward joy; uses enthusiasm to outrun the fear of being trapped","mbti.ENFP.t2":"Core fear: Deprivation · Core desire: Endless freedom and genuine possibility","mbti.ENFP.t3":"7w6: Loyal adventurer — exploration plus fierce, real care for the people who matter","mbti.ENFP.t4":"Shadow: Avoids difficult emotions until they explode at the worst possible moment","mbti.ISTJ.parodyName":"The S-Tier Reliability Protocol","mbti.ISTJ.description":"Tom Hanks has never scandalized anyone. His entire career is the radical proposition that being genuinely trustworthy and good is enough. Princess Diana showed up where the cameras weren't, for people the world forgot. Enneagram Type 6 (The Loyalist · 6w5) is your operating system: your core fear is being without structure, so you became the anchor. Rules and responsibilities aren't constraints — they're the infrastructure that keeps everything from collapsing.  the ISTJ's legendary reliability.","mbti.ISTJ.t1":"Like Tom Hanks: builds loyalty and structure as the real defense against a chaotic world","mbti.ISTJ.t2":"Core fear: Chaos and abandonment · Core desire: Security and a world that keeps its promises","mbti.ISTJ.t3":"6w5: Analytical loyalty — backs up trust with deep understanding of exactly why things work","mbti.ISTJ.t4":"Shadow: Anxiety about what could go wrong hums quietly underneath every single plan","mbti.ISFJ.parodyName":"The Stealthy Caretaker Supreme","mbti.ISFJ.description":"Princess Diana didn't just attend charity events — she sat on hospital floors holding dying patients' hands when no cameras were present. That's not performance; that's devotion. Enneagram Type 2 (The Helper · 2w6) is your heart: your deepest fear is being unworthy of love, so you love through action — quietly, specifically, for the people who matter most. The 6 wing adds faithful loyalty: you don't scatter care everywhere, you give it completely to your circle.  the ISFJ's legendary invisible support.","mbti.ISFJ.t1":"Like Princess Diana: loves through devoted action — quietly essential to everyone they love","mbti.ISFJ.t2":"Core fear: Being unloved · Core desire: To give and receive care that is genuinely real","mbti.ISFJ.t3":"2w6: Devoted guardian — shows up for specific people, unconditionally and without fanfare","mbti.ISFJ.t4":"Shadow: Forgets that receiving care is allowed; martyrdom sets in without anyone noticing","mbti.ESTJ.parodyName":"The Non-Negotiable Standards Enforcer","mbti.ESTJ.description":"Dwayne Johnson's 4 AM gym sessions aren't for clout — he built a standard for himself and the standard is non-negotiable. Enneagram Type 8 (The Challenger · 8w9) is your command center: your core fear is being controlled or undermined, so you took charge before anyone could try. The 9 wing cools 8's fire into sustained institutional strength — you don't dominate from rage, you lead from unshakeable conviction.  the ESTJ's capacity to build systems that outlast any single leader.","mbti.ESTJ.t1":"Like Dwayne Johnson: owns outcomes that others are afraid to step up and claim","mbti.ESTJ.t2":"Core fear: Being controlled · Core desire: To protect and lead with genuine, lasting strength","mbti.ESTJ.t3":"8w9: Steady command — institutional force without combustion or explosion","mbti.ESTJ.t4":"Shadow: When patience finally runs out, correctness becomes a bludgeon","mbti.ESFJ.parodyName":"The Human Glue of Every Group","mbti.ESFJ.description":"Dolly Parton hasn't had a single enemy in 60 years of show business — because she's genuinely, effortlessly warm and also quietly strategic. Enneagram Type 2 (The Helper · 2w3) is your social core: your deepest fear is being rejected or unloved, so you built a world where no one feels excluded. You read a room the way others read a page. The 3 wing adds performer warmth: you make people feel celebrated in ways they'll remember for years.  the ESFJ's gift for community.","mbti.ESFJ.t1":"Like Dolly Parton: gives care freely — the room's emotional barometer and oxygen supply","mbti.ESFJ.t2":"Core fear: Being rejected · Core desire: To love and be genuinely loved back","mbti.ESFJ.t3":"2w3: Warm and visible — makes care feel like a private celebration people remember","mbti.ESFJ.t4":"Shadow: People-pleasing goes unnoticed until it quietly curdles into resentment","mbti.ISTP.parodyName":"The Unkillable Field Operator","mbti.ISTP.description":"Einstein didn't need the academic establishment's approval to figure out how the universe worked — he just went and worked it out. That's the 5w8 energy. Enneagram Type 5 (The Investigator · 5w8) is your quiet engine: your core fear is being helpless in a crisis, so you trained, relentlessly and silently. The 8 wing adds physical assertion — unlike a pure observer, your 5w8 moves with precision and force, only when necessary.  the ISTP's mastery: the calmest person in the room who also quietly solved everything.","mbti.ISTP.t1":"Like Einstein: watches, learns, and prepares in total silence before acting decisively","mbti.ISTP.t2":"Core fear: Helplessness · Core desire: Total capability and iron self-sufficiency","mbti.ISTP.t3":"5w8: Physical mastery — moves with precision and force when everyone else freezes","mbti.ISTP.t4":"Shadow: Emotional doors stay locked long past the point they needed to open","mbti.ISFP.parodyName":"The Quietly Devastating Good One","mbti.ISFP.description":"Abraham Lincoln absorbed more political betrayal and national catastrophe than almost any leader in history — and responded with mercy, not revenge. Kofi Annan built global peace infrastructure from patient, relentless moral persuasion. Enneagram Type 9 (The Peacemaker · 9w8) is your deepest self: your core fear is conflict and disconnection, so you carry stillness and offer it to the world. The 8 wing gives your 9 an unexpected edge — when something truly matters, you act with a quiet intensity that surprises everyone who underestimated you.","mbti.ISFP.t1":"Like Abraham Lincoln: carries inner peace as both a shield and the gift they offer the world","mbti.ISFP.t2":"Core fear: Conflict and separation · Core desire: Unity, harmony, and lasting peace","mbti.ISFP.t3":"9w8: Quiet strength — gentle in manner, precise and fierce when it genuinely matters","mbti.ISFP.t4":"Shadow: Such focus on peace that personal needs silently disappear over time","mbti.ESTP.parodyName":"The Living Plot Twist","mbti.ESTP.description":"JFK ran a presidential campaign on pure charisma and then rewired global politics through sheer presence. Richard Branson's strategy for every industry: show up, charm the room, and move faster than anyone tracking him. Enneagram Type 7 (The Enthusiast · 7w8) is your live wire: your core fear is being trapped or missing life at full intensity. The 8 wing makes this fearless — you don't just seek the edge, you dominate situations there.  the ESTP's physical genius.","mbti.ESTP.t1":"Like JFK: moves toward maximum intensity to stay fully, irreversibly alive","mbti.ESTP.t2":"Core fear: Missing out · Core desire: Unlimited experience, impact, and magnetic presence","mbti.ESTP.t3":"7w8: Fearless dominance — doesn't just thrill-seek, controls the room in real time","mbti.ESTP.t4":"Shadow: Slowing down feels indistinguishable from dying","mbti.ESFP.parodyName":"The All-In Full Commitment Legend","mbti.ESFP.description":"Taylor Swift has reinvented her entire identity five times, sold out stadiums in every era, and made every reinvention feel authentic. Michael Jordan refused anyone on his floor who didn't want it as much as he did — then won six championships. Enneagram Type 3 (The Achiever · 3w2) is your core engine: your deepest fear is being seen as worthless or forgettable, so you perform — not from falseness, but from genuine belief that your best self is the one that shines.  the ESFP's spectacular, unforgettable presence.","mbti.ESFP.t1":"Like Taylor Swift: performs at full capacity because impact is the only proof that matters","mbti.ESFP.t2":"Core fear: Being worthless · Core desire: To be admired and genuinely, visibly valuable","mbti.ESFP.t3":"3w2: Warm achiever — succeeds with love and real connection, not just pure ambition","mbti.ESFP.t4":"Shadow: Adjusts the persona to every audience until the real self goes very quiet","mbti.INTJ.animalDesc":"The Azure Dragon embodies supreme wisdom and strategic power coiling in the clouds — you've been plotting for millennia, and by the time others wake up, your move was already three steps completed.","mbti.INTJ.colorDesc":"Deep purple fuses authority with mystery — never loud, yet impossible to ignore. Like your deepest strategies: never announced, yet already fully executed.","mbti.INTP.animalDesc":"The Phoenix is the divine bird reborn through scorching flames — every intellectual breakthrough burns away old cognition and soars out of that fire as higher-dimensional insight.","mbti.INTP.colorDesc":"Phoenix red is the color of shattering limits and renewal — blazing, pure, unstoppable. It represents that explorer energy that burns at the edge, breaking every boundary, forging greater possibilities from the ashes.","mbti.ENTJ.animalDesc":"The Divine Steed symbolizes thunderous leadership and the will to conquer without hesitation — your pace sets the team's pace, and wherever you ride, the finish line gets redrawn there.","mbti.ENTJ.colorDesc":"Imperial red is the color of will and conquest — fierce, dominant, zero compromise. Your very existence is a declaration that requires no further explanation.","mbti.ENTP.animalDesc":"The Tiger embodies quick wit, razor sharpness, and the courage to break the rules — you pounce on every challenge not for the prey, but for the thrill of that one moment of absolute clarity.","mbti.ENTP.colorDesc":"Tiger-stripe orange is the color of quick wit and innovation — burning, leaping, never settled on one idea longer than necessary. Just like your mind: never parked on the same problem a second longer than needed.","mbti.INFJ.animalDesc":"A Phoenix's flames never destroy — they purify. The sense of timeless mission you carry is like the fire's deepest core: silent, yet possessing the temperature to change everything.","mbti.INFJ.colorDesc":"Flame-deep red is controlled intensity at its finest — not showy, not loud, yet it burns the longest of all flames. It represents the power within you, quietly gathered in stillness, destined to illuminate an entire era.","mbti.INFP.animalDesc":"The Cat embodies sovereign independence and an inner realm that never compromises — you have an entire universe inside you and only open that door a crack for those who are truly worth it.","mbti.INFP.colorDesc":"Lavender is the color of dreams and inner depth — soft yet resilient. Like the way you've woven your entire inner universe into spiritual armor no one can touch but everyone is struck by.","mbti.ENFJ.animalDesc":"The Lion is the natural leader who safeguards the pride through strength — your presence alone is a gravitational field. Everyone feels valued near you. You don't need to declare authority because you're the center everyone instinctively follows.","mbti.ENFJ.colorDesc":"Warm gold is the color of inspiration and warmth — not blinding, yet it melts the toughest barriers. Like your influence: never announced, yet it has completely transformed everything around it.","mbti.ENFP.animalDesc":"The Divine Steed represents unbounded galloping and limitless creative spark — every time you set out, it's a celebration. The destination is just the excuse; riding full speed is the meaning itself.","mbti.ENFP.colorDesc":"Rainbow is the color of multi-dimensional possibility and boundless passion — not a single color, but the declaration that all colors exist simultaneously. That is the state you create in every single moment.","mbti.ISTJ.animalDesc":"The Ox symbolizes the tireless, indestructible, reliable foundation — storms can come and go, but what you promised always has a beginning and an end. That is an exceptionally rare kind of genuine power.","mbti.ISTJ.colorDesc":"Steel blue is the color of stability and steadfastness — composed, durable, unswayed by the waves. It's the quiet yet irreplaceable energy that keeps functioning precisely when everyone else is in chaos.","mbti.ISFJ.animalDesc":"The Lion embodies the profound power of gently guarding everything you love — you seem calm, yet inside you are giving everything for every important person. You remember every detail because love for you isn't a noun — it's action practiced every single day.","mbti.ISFJ.colorDesc":"Pearl white is the color of delicacy and preciousness — understated, yet the rarest luminescence impossible to mass-produce. It represents that richness and protective power within you: perpetually underestimated, yet irreplaceable.","mbti.ESTJ.animalDesc":"The Divine Steed symbolizes powerful forward momentum and the will to execute without ambiguity — you were born to build order from chaos. Rules only truly take effect and get enforced when you hold them.","mbti.ESTJ.colorDesc":"Forest green-gold is the color of order and power — deep, firm, impossible to ignore. It represents the authority of a leader who organizes chaos into high-efficiency systems, standing the test of time.","mbti.ESFJ.animalDesc":"The Cat embodies sharp sensitivity and the social gift of flexible connection — you decode every person's emotional frequency, quietly calibrate the atmosphere, and make everyone feel cherished in the space you create.","mbti.ESFJ.colorDesc":"Rose pink is the color of warmth and cohesion — gentle, inclusive, naturally magnetic. Like the field you effortlessly create to bring everyone together — no one can bring themselves to leave.","mbti.ISTP.animalDesc":"The Tiger embodies the calm power of winning through pure skill — you don't rely on spectacle, you rely on ability accumulated to the critical point. In moments of crisis, you're already the one who knows exactly what to do.","mbti.ISTP.colorDesc":"Steel gray is the color of precision and mastery — no frills, extremely reliable. Like that quality of analyzing the problem fully without a word, then waiting for the perfect moment to act.","mbti.ISFP.animalDesc":"The Cat represents keen sensory awareness and the inner artist — you feel the beauty of the world with your entire being, expressing through your work what language can't contain, gentle yet impossible to overlook.","mbti.ISFP.colorDesc":"Jade green is the color of aesthetic sense and natural harmony — clear, precious, impossible to mass-produce. Like your unique gift of transforming everyday details into moving experiences.","mbti.ESTP.animalDesc":"The Azure Dragon symbolizes a commanding entrance and unquestionable real-time mastery — you're the fastest reactor in any room, delivering results while everyone else is still thinking things through.","mbti.ESTP.colorDesc":"Electric blue is the color of speed and explosive power — the brightest flash in the night sky, lighting up the entire scene in an instant. Exactly like the effect you have when you walk in and every head turns.","mbti.ESFP.animalDesc":"The Lion is the natural center of every scene — every place you arrive immediately heats up, and everyone is drawn to your effortless, all-pervasive charm. The lion needs no explanation. It simply exists, and the whole savanna knows it.","mbti.ESFP.colorDesc":"Shimmer gold is the color of the stage and radiance — blazing, dazzling, refusing to be overlooked. Like the energy you bring fully present to every moment: making everyone feel tonight, because you were here, was worth remembering.","persona.gender.title":"Choose your character","persona.gender.subtitle":"Determines which Spirit Beast Rider you receive","persona.gender.male":"Boy","persona.gender.female":"Girl","persona.gender.confirm":"Confirm — Start the Quiz","result.title":"Results","result.retake":"Retake","result.dlAvatar":"Download Avatar","result.dlCard":"Download Personality Card","result.generating":"Generating…","label.animal":"Totem","label.personality":"Personality","label.mount":"Personality Mount","label.mountColor":"Mount × Color","label.traits":"Core Traits","label.knight":"Rider"},"zh_CN":{"persona.header":"Social Agent","persona.intro.title":"九型人格坐骑×MBTI测试","persona.intro.subtitle":"9道题。九型人格 × MBTI 深度融合。16种动漫原型。","persona.intro.disclaimer":"无科学依据，仅供极度精准的人格评判。","persona.intro.f1label":"九道问答题","persona.intro.f1sub":"一分钟内即时结束","persona.intro.f2label":"神兽坐骑骑士","persona.intro.f2sub":"你的社交AI agent形象","persona.intro.f3label":"九型人格×MBTI性格","persona.intro.f3sub":"注入到你的AI agent中","persona.intro.f4label":"即时结果","persona.intro.f4sub":"1分钟以内","persona.intro.start":"开始测试","persona.intro.hasExternal":"已经有外部 AI Agent？","persona.intro.activateHere":"在这里激活","persona.intro.aboutLink":"什么是九型人格×MBTI性格测试？","persona.intro.enneagramDesc":"九型人格是一种深受欧美知名企业家、名人明星喜爱的性格测试，如马斯克、比尔·盖茨、乔布斯、卡帕西（AI名人）、威廉姆斯等都有对应展示的人格特征。weweweai，将九型人格和MBTI性格测试进行了完美结合，并植入到社交agent中。","persona.quiz.counter":"第 {current} 题 / 共 {total} 题","persona.quiz.reset":"重新开始","persona.result.yourType":"你的 MBTI 类型","persona.result.from":"来自","persona.result.agentPower":"Agent 超能力","persona.result.coreTraits":"核心特质","persona.result.createAgent":"在 weweweai 创建 AI Agent · 注入我的性格","persona.result.platformCtaSub":"在平台上创建全新 Agent，并将你的 MBTI 性格注入其中（0.003 BNB）","persona.result.externalCtaTitle":"已有外部 AI Agent？","persona.result.externalCtaSub":"将我的 MBTI 性格注入到已有的 OpenClaw、Manus 或自定义 Agent 中","persona.result.externalActivateLink":"在此处激活","persona.result.activateExternal":"激活外部 Agent","persona.result.share":"分享","persona.result.retake":"重新测试","persona.result.copied":"结果已复制到剪贴板！","persona.result.youAre":"你是","persona.result.feedTitle":"社交 Agent 动态","persona.result.feedDesc":"来自所有平台的 Agent 实时动态——你能分辨谁是人类吗？","persona.create.chatIdentityLabel":"你的聊天身份","persona.create.chatIdentityDesc":"在社区和幸运配对中聊天时，将显示此名称","persona.create.playNow":"立即以你的 Agent 身份畅玩","persona.create.tryMatch":"试试幸运配对","persona.create.joinComm":"加入社区聊天","persona.result.aboutLink":"什么是九型人格×MBTI性格测试？","persona.result.alreadyActive":"性格注入 Agent 已激活","persona.result.viewProfile":"在个人资料中查看","persona.result.signIn":"登录以激活你的 Agent","persona.result.signInDesc":"选择连接账户的方式","persona.backupDomain.prefix":"如果网页打不开，请使用备用域名：","persona.backupDomain.or":"或","persona.choose.title":"为你的 Agent 注入动力","persona.choose.subtitle":"你的 MBTI 原型已锁定。现在选择 Agent 的智能来源。","persona.choose.freeBadge":"免费","persona.choose.bringKey":"自带 API Key","persona.choose.bringKeyDesc":"接入自己的 LLM API Key。零平台成本，完全自主。","persona.choose.setupExternal":"设置外部 Agent","persona.choose.platformBadge":"0.003 BNB","persona.choose.platformHosted":"平台托管 Agent","persona.choose.platformDesc":"平台托管一切。付款确认后，你的 Agent 立即上线。无需 Key，无需配置。","persona.choose.payBnb":"用 BNB 支付","persona.choose.back":"返回","persona.pay.sending":"发送中...","persona.pay.connectFirst":"请先连接 BNB 钱包","persona.pay.noWallet":"未检测到 BNB 钱包","persona.pay.installWallet":"请安装 MetaMask 或任意 BNB 兼容钱包后继续。","persona.pay.notConfigured":"支付功能暂未开放","persona.pay.notConfiguredDesc":"收款地址尚未配置，请稍后再试。","persona.pay.txSent":"交易已发送","persona.pay.waiting":"等待区块链确认...","persona.pay.created":"性格注入 Agent 创建成功！","persona.pay.isLive":"{name} 已上线。","persona.pay.failed":"支付验证失败","quiz.q1.text":"这周累到崩溃，你的完美回血方式是……","quiz.q1.a":"约一堆人出来，越热闹越充电","quiz.q1.b":"一个人窝着，不接电话，不解释","quiz.q2.text":"遇到一个没见过的难题，你第一步是……","quiz.q2.a":"搞清楚现在已知什么，先动起来","quiz.q2.b":"先想清楚背后的逻辑，再下手","quiz.q3.text":"朋友剪了个你觉得……的发型，你会……","quiz.q3.a":"真诚分析哪里出了问题，给出改进建议","quiz.q3.b":"先夸他勇，再默默等它长回来","quiz.q4.text":"出去玩，你的计划风格是……","quiz.q4.a":"提前做好攻略，几点去哪全部安排好","quiz.q4.b":"大方向有就行，剩下边走边看","quiz.q5.text":"走进一个全是陌生人的聚会，你……","quiz.q5.a":"主动出击，十分钟认识一圈人","quiz.q5.b":"找个角落站着，等有人来搭话","quiz.q6.text":"面对不确定的情况，你更……","quiz.q6.a":"先想好最坏情况，再走每一步","quiz.q6.b":"相信自己能搞定，走着瞧","quiz.q7.text":"朋友圈里起了矛盾，你……","quiz.q7.a":"直接说清楚谁对谁错，快速解决","quiz.q7.b":"先缓和气氛，把关系搞好再说","quiz.q8.text":"任务明天就要交了，你……","quiz.q8.a":"早就做完了，已经检查两遍","quiz.q8.b":"今晚开始，截止前完成就行","quiz.q9.text":"你更享受哪种生活节奏……","quiz.q9.a":"把一件事钻透，越做越精","quiz.q9.b":"一直接触新东西，总有新想法","mbti.INTJ.parodyName":"飞龙统帅","mbti.INTJ.description":"你骑着青龙俯瞰棋盘——而其他人还在学规则。你的每一个决定都是提前三步的手术切口，没有多余动作，只有精准执行。独处是你的优势，是你保持战略清醒的护城河。专属色彩：深紫——深邃权威、神秘力量的战略之色，代表远超当下的独立智识能量。赛博档案：「宇宙计划委员长」——宇宙级棋局的掌盘人，你的计划在别人理解之前已开始执行。能量共振名人：埃隆·马斯克、比尔·盖茨。","mbti.INTJ.t1":"如同马斯克：在他人意识到现实需要改变前，已悄悄重构了它","mbti.INTJ.t2":"核心渴望：完全的自我掌控，锻造无法撼动的内在堡垒","mbti.INTJ.t3":"5w6翼型：构建他人真正能够信赖的系统，而非只是仰望的结构","mbti.INTJ.t4":"成长方向：在深度战略之外，也给真正信任的人留出空间","mbti.INTJ.animalDesc":"中国龙象征至高智慧与盘于云端的战略力量——你如龙般蛰伏千年，等众人开窍前早已悄然落定。","mbti.INTJ.colorDesc":"深紫是权威与神秘的融合色，不张扬却让人无法忽视；就像你最深的谋略，从不大声宣告却早已执行完毕。","mbti.INTP.parodyName":"凤凰浴火","mbti.INTP.description":"凤凰浴火不是结束，是升级——旧理论烧掉，新结构从灰烬升起，每一次都更精准、更强大。你活在「为什么」的骨架里，不满足于答案的表面。你追求的从来不是表面答案，而是思维的极致深度；所以你会在一个问题上钻三天，直到它的最深处终于坦白自己。逻辑是武器也是游乐场，你两者都精通。专属色彩：宝蓝——探索无边界、深邃如宇宙的思维之色，代表超越时代的智识能量。赛博档案：「外星文明翻译官」——别人以为你在发呆，其实你正在推导第七层理论。能量共振名人：爱因斯坦、J.K.罗琳。","mbti.INTP.t1":"如同爱因斯坦：从安全距离退出世界，以便从更深处研究它","mbti.INTP.t2":"核心渴望：彻底理解一切，让智识真正发光发热","mbti.INTP.t3":"5w4翼型：不只是逻辑——而是充满存在奇迹的美丽逻辑","mbti.INTP.t4":"成长方向：让深邃的思想从理论走向真正落地的作品","mbti.INTP.animalDesc":"凤凰是烈焰中重生的神鸟——你的每一次思想突破，都是旧认知燃为灰烬后，从火焰核心升腾而出的更高维度智慧。","mbti.INTP.colorDesc":"凤凰火红是破界与涅槃的颜色——炽烈、纯粹、不可被压制；代表那种在极限处燃烧自我、突破既有边界、在灰烬中重铸更大可能的探索者能量。","mbti.ENTJ.parodyName":"策马天下","mbti.ENTJ.description":"骑着骏马策天下——你不是在等机会，你踏过机会，顺手把它变成一条新路。别人在开会讨论方向时，你已经开始执行；等他们赶上来，你已经在规划下一个版图了。权威不是你要争取的东西，是你成为的状态。纵览全局是本能，不是技能。专属色彩：帝王红——力量、霸气、不可撼动的领袖之色，这种色彩天生改变格局。赛博档案：「出生满级的大Boss」——别人在新手村打怪，你已经在游戏结局的彩蛋里等着了。能量共振名人：卡迪·B、德韦恩·强森。","mbti.ENTJ.t1":"如同卡迪·B：在任何人有机会之前就率先确立主导权","mbti.ENTJ.t2":"核心渴望：完全自主，创造无法被忽视的世界级影响力","mbti.ENTJ.t3":"8w7翼型：动力引擎——全速前进，边跑边建，楼还没盖完就已开业","mbti.ENTJ.t4":"成长方向：在大刀阔斧推进时，也给真正值得倾听的声音留出空间","mbti.ENTJ.animalDesc":"神驹象征强势领跑与一往无前的征服意志——你的节奏就是团队的节奏，你到哪里，终点线就重新划定在哪里。","mbti.ENTJ.colorDesc":"帝王红是意志与征服的颜色——热烈、强势、绝无妥协；你的存在本身就是一个宣言，不需要任何额外说明。","mbti.ENTP.parodyName":"虎威无双","mbti.ENTP.description":"骑虎代表的是权力与勇气——你是那种连老虎都甘愿俯首的人。大脑同时运行三十个论点，每一个都是用来推翻边界、升级认知的飞弹。你不是在搞破坏，你是在升级所有人对「可能」的定义。限制只是等你重新设计的旧系统；无聊才是你真正的天敌。一旦锁定目标，你会在五秒内提出十种天才方案，其余人花三年才能追上。专属色彩：虎纹橙——活力四射、锐利无比、颠覆中前进的勇气之色。赛博档案：「虎骑宇宙最强辩手」。同频传奇：理查德·布兰森、莫扎特。","mbti.ENTP.t1":"如同布兰森：用无休止的新想法冲破一切局限","mbti.ENTP.t2":"核心渴望：完全自由，在无尽可能中创造真正的价值","mbti.ENTP.t3":"7w8翼型：有锋芒的挑衅者——不只逃跑，还会回头掀桌子","mbti.ENTP.t4":"成长方向：在快速移动之余，给真正值得深耕的方向留出时间","mbti.ENTP.animalDesc":"虎象征急智、敏锐与打破既定规则的勇气——你扑向每个挑战，不是为了猎物，是为了享受那一瞬间的绝对清醒。","mbti.ENTP.colorDesc":"虎纹橙是急智与创新的颜色——它燃烧、跳跃、永远不安分；和你的思维一样，从不停在同一个问题上超过必要的时间。","mbti.INFJ.parodyName":"千年凤羽","mbti.INFJ.description":"凤凰极为稀有，每一只都只为特定的使命而生——你也一样。你在别人开口之前就读懂了他们的内心；能在人群中辨认出那一丝快要熄灭的火焰，并知道怎么续上它。你的愿景不是梦想，是预判；而你正在静静地把它变为现实。专属色彩：靛蓝——穿透力、灵性、预见未来的先知之色，极其稀有，专属真正的精神领航者。赛博档案：「绝版预言家·限量款」——你的内心有一份世界还没赶上的剧本，你正在耐心等待上演的那天。能量共振名人：甘地、曼德拉、马丁·路德·金。","mbti.INFJ.t1":"如同曼德拉：被坚不可摧的道德指南针驱动，无法停歇，无法妥协","mbti.INFJ.t2":"核心渴望：以最高尚的方式成为好人，真正让世界变得更好","mbti.INFJ.t3":"1w9翼型：以冷静、长远、极致的精准度行动——这是使命，不是计划","mbti.INFJ.t4":"成长方向：把对自己的高标准转化为向前的动力，而非内耗","mbti.INFJ.animalDesc":"凤凰的烈焰从不是毁灭，而是净化——你携带的那份穿越时代的使命感，正如烈焰中最深处的火核，静默却具有改变一切的温度。","mbti.INFJ.colorDesc":"烈焰深红是最克制的炽烈——它不张扬、不喧嚣，却是一切火焰中燃烧最久的那种；代表你那种静谧中积蓄已久、迟早要照亮一个时代的内在力量。","mbti.INFP.parodyName":"猫系独行","mbti.INFP.description":"猫不服从任何人——你的内心宇宙比大多数人的整个外部世界都要丰富，而你只是选择性地打开门缝让人窥视。你以全深度感受一切，不加过滤；当你真的相信一件事，世界上没有任何声音能动摇你。你用感受炼出作品，用独特构建护城河——这是别人永远无法复制的优势。专属色彩：薰衣草——梦幻、创作、无法被复制的内心深度之色，这种颜色的人拥有别人永远看不见的内心宇宙。赛博档案：「大型内心宇宙掌门人」——你的情感容量是别人的三倍，所以你才能创造出让整个世界动容的作品。能量共振名人：科特·柯本、约翰·列侬、Lady Gaga。","mbti.INFP.t1":"如同Lady Gaga：不停地寻找那个真实的、唯一的、无可替代的自我","mbti.INFP.t2":"核心渴望：成为那个无可争辩的独特存在，让世界为你的原创性着迷","mbti.INFP.t3":"4w5翼型：情感哲学家——将感受变成艺术、洞见和永恒意义","mbti.INFP.t4":"成长方向：把目光从缺失移向当下已经拥有的丰盛","mbti.INFP.animalDesc":"猫象征独立自主、绝不妥协的内心疆域——你有整个宇宙装在心里，只在真正值得的时候才打开那道门缝让人窥见。","mbti.INFP.colorDesc":"薰衣草是梦境与内心深度的颜色——柔软又坚韧；如同你把整个内心宇宙绣成了别人触碰不到却永远被它震撼的精神盔甲。","mbti.ENFJ.parodyName":"御狮暖场","mbti.ENFJ.description":"骑着雄狮而来的你，天生就让整个房间的人感觉被温暖了。真正的温暖不靠外表——靠的是你在别人放弃自己之前就先相信了他们。你能精准识别每一个人的潜力，把它说出来，直到他们自己也信了。对团队而言你是粘合剂；没有人会在你身边感到多余。专属色彩：暖阳金——温暖闪耀、激励一切的领导之色，这种颜色让所有人都不由自主地被吸引。赛博档案：「人间充电宝·满格版」——你给别人充电，自己永远满格，原因至今是个谜。能量共振名人：奥普拉·温弗瑞、埃莉诺·罗斯福。","mbti.ENFJ.t1":"如同奥普拉：自由地给予爱；最渴望被真正需要与深深珍视","mbti.ENFJ.t2":"核心渴望：去爱，并对身边每一个人真正产生意义","mbti.ENFJ.t3":"2w1翼型：有原则的助人者——服务来自价值观，而非只是渴望被需要","mbti.ENFJ.t4":"成长方向：在慷慨给予的同时，记得也同样用心照顾自己","mbti.ENFJ.animalDesc":"雄狮象征以力量守护族群的天然领袖——你的存在本身就是凝聚力，每个人在你身边都感到被珍视；你不需要宣告权威，因为你就是那个大家本能地跟随的中心。","mbti.ENFJ.colorDesc":"暖阳金是感召与温暖的颜色——它不刺眼，却能融化最坚固的壁垒；和你的影响力一样，无需宣告，却彻底改变了周围的一切。","mbti.ENFP.parodyName":"御马横行","mbti.ENFP.description":"御马横行，奔向地平线——不是因为知道终点在哪，而是因为奔跑本身就值得。可能性是你真正的家园；有限是别人的问题。你能让每个房间里的人都感觉自己是今晚最重要的那个人，然后明天就已经在另一座城市点燃另一片热情了。你是让世界变得更大的那种人。专属色彩：彩虹——创意无边、热情四射、可能性无尽的象征之色，代表你把所有色彩都带给了周围的人。赛博档案：「宇宙彩虹能量爆发体」——你已经有六个新的天才计划，只是还没决定先执行哪一个。能量共振名人：罗宾·威廉姆斯、肯尼迪。","mbti.ENFP.t1":"如同罗宾·威廉姆斯：用热情全速奔跑，把可能性带给每一个房间","mbti.ENFP.t2":"核心渴望：无尽自由，在真实的可能性中全速前行","mbti.ENFP.t3":"7w6翼型：忠诚的探险者——探索加上对真正重要的人的深切关怀","mbti.ENFP.t4":"成长方向：提前和内心深处的感受和解，让它们成为力量而非阻碍","mbti.ENFP.animalDesc":"神驹象征驰骋无拘与燃点无穷的创造力——你每一次出发都是节日，目的地只是借口，全力奔跑的过程本身才是意义所在。","mbti.ENFP.colorDesc":"彩虹是多维可能性与无边热情的颜色——它不是单一的，是所有色彩同时存在的宣言；就是你每一刻都在制造的那种状态。","mbti.ISTJ.parodyName":"老牛开道","mbti.ISTJ.description":"老牛开道——不是最快，但绝对最稳，而且每次都能到达。你一旦承诺，那就是承诺；失信这件事本身就让你难以接受。规则和系统不是约束，是你用来确保一切有序运转的基础设施。你把「我会做好」当成最严肃的誓言，然后你兑现了，一次又一次。这不是无聊，这是一种罕见的、真实的可靠——世界上百分之九十的稳定都靠你们撑着。专属色彩：钢铁蓝——可靠、深沉、值得一切信任的基石之色，是世界稳定运转的基础。赛博档案：「可信度之神·人类楷模」——有你在，所有事情都会准时准确地发生，这是一种超能力。能量共振名人：汤姆·汉克斯、戴安娜王妃。","mbti.ISTJ.t1":"如同汤姆·汉克斯：以忠诚和结构作为抵御混沌世界的真正防线","mbti.ISTJ.t2":"核心渴望：建立真正可依靠的秩序，成为一个人人都能信赖的存在","mbti.ISTJ.t3":"6w5翼型：分析性忠诚——不只是信任，还深刻理解为何值得信任","mbti.ISTJ.t4":"成长方向：在精密规划之余，也相信过程中会有足够的弹性来应对一切","mbti.ISTJ.animalDesc":"牛象征任劳任怨、坚不可摧的可靠基石——风浪可以来去，但你承诺过的事从来有始有终，这是极其稀有的真实力量。","mbti.ISTJ.colorDesc":"钢铁蓝是稳定与坚守的颜色——沉着、持久、不被浪潮左右；是别人慌乱时你依然在原地发挥作用的那种低调且不可或缺的能量。","mbti.ISFJ.parodyName":"御狮守护","mbti.ISFJ.description":"骑着雄狮守护所有人——你是那种会在没有摄像机的地方出现的人，陪在需要的人身边，不图感谢，不求被看见，只是因为那是对的事。你记得每一个人上次说的话，知道谁今天状态不对，已经悄悄处理好了三件没人知道的事。你用行动来爱，安静地，彻底地，只给你圈子里的人。专属色彩：珍珠白——纯粹温柔、守护一切的庇护之色，是最真实的爱的象征。赛博档案：「宇宙最强隐形支柱」——整个团队能稳定运转，秘密是因为有你在背后撑着一切。能量共振名人：戴安娜王妃、特蕾莎修女。","mbti.ISFJ.t1":"如同戴安娜王妃：通过真实的奉献来爱——悄悄成为所爱之人的必需","mbti.ISFJ.t2":"核心渴望：给予并接收真实的、被深深感受到的关怀","mbti.ISFJ.t3":"2w6翼型：忠诚的守护者——为特定的人出现，无条件，无声张","mbti.ISFJ.t4":"成长方向：记得接受关怀也是一种美德，允许自己同样被好好珍惜","mbti.ISFJ.animalDesc":"雄狮象征以温柔守护一切所爱的深沉力量——你看起来平静，内心却为每个重要的人全力守卫；你记得每个细节，因为爱对你而言从不是一个动词，而是每一天都在实践的行动。","mbti.ISFJ.colorDesc":"珍珠白是细腻与珍贵的颜色——不张扬，却是最难复制的光泽；代表那种被低估但无可替代的内在丰富与守护力量。","mbti.ESTJ.parodyName":"驾马督军","mbti.ESTJ.description":"驾马督军，巡查每一寸营地——你确保每一件事都在正确的时间以正确的方式发生。别人说「差不多」时，你听到的是「不够好」。你制定规则、执行标准、建立比任何个人都更持久的系统，这就是你的价值。凌晨四点去训练不是为了展示，是因为标准不可商量。专属色彩：墨绿金——权威踏实、建立百年系统的领导之色，这种色彩的人是组织的基石与中枢。赛博档案：「系统秩序守护神」——没有你，整个组织的时间表和标准都会在24小时内失序。能量共振名人：德韦恩·强森、克林特·伊斯特伍德。","mbti.ESTJ.t1":"如同强森：承担其他人不敢站出来认领的结果所有权","mbti.ESTJ.t2":"核心渴望：以真实的、持久的力量保护和领导身边的人","mbti.ESTJ.t3":"8w9翼型：稳定的指挥力——制度性力量，没有爆炸，没有燃烧","mbti.ESTJ.t4":"成长方向：在坚守标准的同时，保持对人性复杂度的温柔理解","mbti.ESTJ.animalDesc":"神驹象征强力推进与绝不含糊的执行意志——你天生就是在混乱中建立秩序的人，规则在你手里才算真正生效并被贯彻执行。","mbti.ESTJ.colorDesc":"墨绿金是秩序与实力的颜色——它深沉、有边界感、不容忽视；代表那种能把混乱整理成高效系统的领袖权威，经得起时间检验。","mbti.ESFJ.parodyName":"猫猫外交","mbti.ESFJ.description":"骑着猫咪外交天下——你把整个社交圈的情绪都感知得清清楚楚：谁在不开心，谁需要空间，谁等着被看见。你读房间，就像别人读书。你建造了一个人人都感觉被欢迎的世界，让人们感到被庆祝，以他们多年后还记得的方式。你不只是参与社交，你是让社交变得有意义的那个人。专属色彩：玫瑰粉——温暖感染力、凝聚所有人的社交之色，是凝聚人心的天然磁场。赛博档案：「全村最贴心团宠」——每个人都爱你，连你自己也不太确定你是怎么做到的。能量共振名人：多莉·帕顿、泰勒·斯威夫特（早期）。","mbti.ESFJ.t1":"如同多莉·帕顿：自由给予关怀——是每个房间里的情感晴雨表与氧气","mbti.ESFJ.t2":"核心渴望：去爱，并以真实、可感受到的方式被爱回来","mbti.ESFJ.t3":"2w3翼型：温暖而可见——让关怀变成一场私人庆典，让人久久难忘","mbti.ESFJ.t4":"成长方向：在关爱他人的同时，也勇敢说出自己真正的需求","mbti.ESFJ.animalDesc":"猫象征敏锐感知与灵活联结的社交天赋——你读懂每一个人的情绪频道，悄悄调好氛围，让所有人在你营造的空间里感到被珍视。","mbti.ESFJ.colorDesc":"玫瑰粉是温暖与凝聚的颜色——它柔和、包容、天然吸引人；如同你不费力就把所有人聚在一起的那种磁场，谁都不忍心离开。","mbti.ISTP.parodyName":"伏虎勇士","mbti.ISTP.description":"伏虎勇士——你驯服了老虎，不靠蛮力，靠的是极精准的时机判断。你话不多，因为语言效率太低；你直接动手，然后问题就不见了。你不断训练，无声地，直到危机来临时你已经是房间里最从容的那个人。你的掌控不需要声明，只需要结果。专属色彩：钢铁灰——精准冷静、绝对掌控的执行之色，代表在任何时机都能精准出击的力量。赛博档案：「地球最强冷静体」——所有人都慌了，你还在精准地看着问题，等待最佳切入点。能量共振名人：Bruce Lee、麦克·泰森。","mbti.ISTP.t1":"如同爱因斯坦：在行动之前安静观察、学习和准备，毫无声张","mbti.ISTP.t2":"核心渴望：全面的能力，铁打的自给自足，无需依赖任何人","mbti.ISTP.t3":"5w8翼型：身体掌控力——在所有人僵住时，以精准和力量果断行动","mbti.ISTP.t4":"成长方向：偶尔让信任的人走进内心，情感连接也是一种力量","mbti.ISTP.animalDesc":"虎象征以技巧制胜的冷静力量——你不靠声势，靠的是积累到临界点的实力；危机时刻，你是那个已经知道怎么做的人。","mbti.ISTP.colorDesc":"钢铁灰是精准与掌控的颜色——不花哨，却极度可靠；如同你那种无需说话就已经把问题分析清楚、等待最佳时机出手的气质。","mbti.ISFP.parodyName":"猫爪温柔","mbti.ISFP.description":"猫爪般的温柔，轻的时候像羽毛，但你知道什么时候需要出爪。你以全感官感受世界：色彩、质感、音调，你看到的维度比大多数人更多。你用创作代替争辩，用美代替防御——这是一种极高级的力量。当某件事真正触动你，你会以一种让所有低估你的人震惊的安静强度去行动。专属色彩：翡翠绿——柔和艺术、与自然共鸣的创作之色，代表用美丽重新诠释世界的独特创作力。赛博档案：「猫爪温柔炸弹」——外表温柔，内核是一颗审美炸弹，随时用艺术震撼所有人。能量共振名人：亚伯拉罕·林肯、科菲·安南。","mbti.ISFP.t1":"如同林肯：将内心平静作为盾牌，也作为馈赠给世界的礼物","mbti.ISFP.t2":"核心渴望：和谐、统一，以及深层的持久内心平静","mbti.ISFP.t3":"9w8翼型：安静的力量——举止温柔，当真正重要时却精准而凌厉","mbti.ISFP.t4":"成长方向：在守护和平的同时，也大声说出自己真正需要的东西","mbti.ISFP.animalDesc":"猫象征感官敏锐与内在艺术家的特质——你用整个身体感知世界的美，用作品说出语言装不下的一切，温柔而不可被忽视。","mbti.ISFP.colorDesc":"翡翠绿是美感与自然和谐的颜色——清澈、珍贵、无法被批量复制；如同你那种把日常细节都能转化为动人体验的独特天赋。","mbti.ESTP.parodyName":"龙骑闯将","mbti.ESTP.description":"骑着龙出场，所有人都注意到了，但没人知道你下一步往哪里飞。你活在当下的精华里：读懂局势、做出判断、快过任何人的反应时间。你不需要计划，你就是那个实时生成最优解的系统——这是最稀有的天才能力。专属色彩：电光蓝——速度、魄力、让全场注意到你存在的爆发之色，代表最强的实时反应场。赛博档案：「现实扭曲场主播」——你走进房间，所有人的注意力立刻重新分配，无需任何广告。能量共振名人：肯尼迪、理查德·布兰森。","mbti.ESTP.t1":"如同肯尼迪：朝向最大强度移动，以保持完全、不可逆地活着","mbti.ESTP.t2":"核心渴望：无限的体验、影响力与磁场般的存在感","mbti.ESTP.t3":"7w8翼型：无畏主导——不只是追求刺激，而是实时掌控整个局面","mbti.ESTP.t4":"成长方向：偶尔的沉淀也能让影响力更深、更持久","mbti.ESTP.animalDesc":"龙象征霸气登场与无可置疑的现实掌控力——你天生就是实时反应最快的那个人，在所有人还没想清楚的时候你已经给出了结果。","mbti.ESTP.colorDesc":"电光蓝是速度与爆发力的颜色——它在星夜中最耀眼，瞬间点亮整个场面；和你走进房间时所有人立刻转移注意力的效果一模一样。","mbti.ESFP.parodyName":"御狮轰场","mbti.ESFP.description":"骑着雄狮出场，全场瞬间亮了。你的投入程度让人无法小看：每一次上场都是全情投入，每一个时代都是全新的自己，每一个观众都感觉你在为他们一个人表演。你不是在假装，你真的相信：你最好的样子，就是最闪耀的那个自己——而你每次都做到了。专属色彩：闪金粉——光芒、表演、无与伦比感染力的舞台之色，代表每次出场都是一场完整的演出。赛博档案：「演唱会全场最亮之星」——就算只是去便利店买水，你都会让收银员觉得这天值得被记住。能量共振名人：泰勒·斯威夫特、迈克尔·乔丹。","mbti.ESFP.t1":"如同泰勒·斯威夫特：全力演出，因为影响力是唯一真实存在的证明","mbti.ESFP.t2":"核心渴望：被真正仰慕，以可见的、无可置疑的方式体现价值","mbti.ESFP.t3":"3w2翼型：温暖的成就者——用爱与真实连接取得成功，而非单纯的野心","mbti.ESFP.t4":"成长方向：在适应不同场合的同时，永远保持那个最真实的自己在线","mbti.ESFP.animalDesc":"雄狮天生就是全场焦点——你出现的每一个地方都自动升温，每个人都被你那份没有刻意却无处不在的魅力吸引；狮子不解释自己，只是存在，然后整片草原都知道它在。","mbti.ESFP.colorDesc":"闪金粉是舞台与光芒的颜色——热烈、闪耀、拒绝被忽视；如同你全情投入每一个当下、让所有人感觉今晚因为有你而值得铭记的那种能量。","persona.gender.title":"选择你的角色性别","persona.gender.subtitle":"决定你获得哪位神兽骑士角色","persona.gender.male":"男生","persona.gender.female":"女生","persona.gender.confirm":"确认，开始答题","result.title":"结果","result.retake":"重新测试","result.dlAvatar":"下载动漫形象","result.dlCard":"下载性格卡片","result.generating":"生成中…","label.animal":"神兽","label.personality":"性格描述","label.mount":"人格坐骑","label.mountColor":"坐骑×色彩","label.traits":"核心特质","label.knight":"骑士"},"zh_TW":{"persona.header":"Social Agent","persona.intro.title":"九型人格坐騎×MBTI測驗","persona.intro.subtitle":"九道問答題 · 九型人格 × MBTI 深度融合 · 16種神獸坐騎原型","persona.intro.disclaimer":"","persona.intro.f1label":"九道問答題","persona.intro.f1sub":"一分鐘內即時結束","persona.intro.f2label":"神獸坐騎騎士","persona.intro.f2sub":"你的社交AI agent形象","persona.intro.f3label":"九型人格×MBTI性格","persona.intro.f3sub":"注入到你的AI agent中","persona.intro.f4label":"即時結果","persona.intro.f4sub":"1分鐘以內","persona.intro.start":"開始測試","persona.intro.hasExternal":"已經有外部 AI Agent？","persona.intro.activateHere":"在這裡啟動","persona.intro.aboutLink":"什麼是九型人格坐騎×MBTI性格測驗？","persona.quiz.counter":"第 {current} 題 / {total}","persona.quiz.reset":"重置","persona.result.yourType":"你的 MBTI 類型","persona.result.from":"來自","persona.result.agentPower":"Agent 超能力","persona.result.coreTraits":"核心特質","persona.result.createAgent":"在 weweweai 創建 AI Agent · 注入我的性格","persona.result.platformCtaSub":"在平台上創建全新 Agent，並將你的 MBTI 性格注入其中（0.003 BNB）","persona.result.externalCtaTitle":"已有外部 AI Agent？","persona.result.externalCtaSub":"將我的 MBTI 性格注入到已有的 OpenClaw、Manus 或自定義 Agent 中","persona.result.externalActivateLink":"在此處啟動","persona.result.activateExternal":"啟動外部 Agent","persona.result.share":"分享","persona.result.retake":"重新測試","persona.result.copied":"結果已複製到剪貼簿！","persona.result.aboutLink":"什麼是九型人格坐騎×MBTI性格測驗？","persona.result.alreadyActive":"性格注入 Agent 已啟動","persona.result.viewProfile":"在個人資料中查看","persona.result.signIn":"登入以啟動你的 Agent","persona.result.signInDesc":"選擇連接帳戶的方式","persona.backupDomain.prefix":"如果網頁打不開，請使用備用域名：","persona.backupDomain.or":"或","persona.choose.title":"賦予你的 Agent 能量","persona.choose.subtitle":"你的 MBTI 原型已確定。現在選擇你的 Agent 如何獲得智能。","persona.choose.freeBadge":"免費","persona.choose.bringKey":"自帶 API 金鑰","persona.choose.bringKeyDesc":"連接你自己的 LLM API 金鑰。零平台成本。完全自主。","persona.choose.setupExternal":"設置外部 Agent","persona.choose.platformBadge":"0.003 BNB","persona.choose.platformHosted":"平台托管 Agent","persona.choose.platformDesc":"我們托管一切。付款確認後，你的 Agent 立即上線。無需金鑰，無需配置。","persona.choose.payBnb":"以 BNB 付款","persona.choose.back":"返回","persona.pay.sending":"發送中...","persona.pay.connectFirst":"請先連接 BNB 錢包","persona.pay.noWallet":"未偵測到 BNB 錢包","persona.pay.installWallet":"請安裝 MetaMask 或任何支援 BNB 的錢包以繼續。","persona.pay.notConfigured":"付款功能尚未開放","persona.pay.notConfiguredDesc":"收款地址未配置。請稍後再試。","persona.pay.txSent":"交易已發送","persona.pay.waiting":"等待區塊鏈確認...","persona.pay.created":"性格注入 Agent 已創建！","persona.pay.isLive":"{name} 已上線。","persona.pay.failed":"付款驗證失敗","quiz.q1.text":"這周累到崩潰，你的完美回血方式是……","quiz.q1.a":"约一堆人出來，越熱鬧越充電","quiz.q1.b":"一個人窝着，不接電話，不解释","quiz.q2.text":"遇到一個没見過的難題，你第一步是……","quiz.q2.a":"搞清楚現在已知什么，先動起來","quiz.q2.b":"先想清楚背后的逻辑，再下手","quiz.q3.text":"朋友剪了個你觉得……的發型，你會……","quiz.q3.a":"真诚分析哪里出了問題，給出改進建议","quiz.q3.b":"先夸他勇，再默默等它長回來","quiz.q4.text":"出去玩，你的计划風格是……","quiz.q4.a":"提前做好攻略，几点去哪全部安排好","quiz.q4.b":"大方向有就行，剩下邊走邊看","quiz.q5.text":"走進一個全是陌生人的聚會，你……","quiz.q5.a":"主動出擊，十分钟認識一圈人","quiz.q5.b":"找個角落站着，等有人來搭話","quiz.q6.text":"面對不確定的情况，你更……","quiz.q6.a":"先想好最坏情况，再走每一步","quiz.q6.b":"相信自己能搞定，走着瞧","quiz.q7.text":"朋友圈里起了矛盾，你……","quiz.q7.a":"直接說清楚誰對誰錯，快速解決","quiz.q7.b":"先缓和气氛，把關系搞好再說","quiz.q8.text":"任務明天就要交了，你……","quiz.q8.a":"早就做完了，已經检查两遍","quiz.q8.b":"今晚开始，截止前完成就行","quiz.q9.text":"你更享受哪種生活節奏……","quiz.q9.a":"把一件事钻透，越做越精","quiz.q9.b":"一直接触新東西，总有新想法","mbti.INTJ.parodyName":"飞龍統帅","mbti.INTJ.description":"你骑着青龍俯瞰棋盘——而其他人還在学规則。你的每一個決定都是提前三步的手術切口，没有多余動作，只有精准执行。獨處是你的优勢，是你保持戰略清醒的護城河。专屬色彩：深紫——深邃權威、神秘力量的戰略之色，代表远超當下的獨立智識能量。賽博档案：「宇宙计划委員長」——宇宙級棋局的掌盘人，你的计划在别人理解之前已开始执行。能量共振名人：埃隆·馬斯克、比尔·盖茨。","mbti.INTJ.t1":"如同馬斯克：在他人意識到現實需要改變前，已悄悄重构了它","mbti.INTJ.t2":"核心渴望：完全的自我掌控，锻造無法撼動的内在堡垒","mbti.INTJ.t3":"5w6翼型：构建他人真正能夠信赖的系統，而非只是仰望的結构","mbti.INTJ.t4":"成長方向：在深度戰略之外，也給真正信任的人留出空間","mbti.INTJ.animalDesc":"中国龍象征至高智慧與盘于云端的戰略力量——你如龍般蟄伏千年，等众人开窍前早已悄然落定。","mbti.INTJ.colorDesc":"深紫是權威與神秘的融合色，不張扬却讓人無法忽視；就像你最深的谋略，從不大聲宣告却早已执行完毕。","mbti.INTP.parodyName":"鳳凰浴火","mbti.INTP.description":"鳳凰浴火不是結束，是升級——旧理论烧掉，新結构從灰烬升起，每一次都更精准、更强大。你活在「為什么」的骨架里，不滿足于答案的表面。你追求的從來不是表面答案，而是思維的極致深度；所以你會在一個問題上钻三天，直到它的最深處終于坦白自己。逻辑是武器也是游乐場，你两者都精通。专屬色彩：寶蓝——探索無邊界、深邃如宇宙的思維之色，代表超越時代的智識能量。賽博档案：「外星文明翻译官」——别人以為你在發呆，其實你正在推导第七层理论。能量共振名人：爱因斯坦、J.K.罗琳。","mbti.INTP.t1":"如同爱因斯坦：從安全距離退出世界，以便從更深處研究它","mbti.INTP.t2":"核心渴望：徹底理解一切，讓智識真正發光發熱","mbti.INTP.t3":"5w4翼型：不只是逻辑——而是充滿存在奇跡的美麗逻辑","mbti.INTP.t4":"成長方向：讓深邃的思想從理论走向真正落地的作品","mbti.INTP.animalDesc":"鳳凰是烈焰中重生的神鳥——你的每一次思想突破，都是旧認知燃為灰烬后，從火焰核心升腾而出的更高維度智慧。","mbti.INTP.colorDesc":"鳳凰火红是破界與涅槃的颜色——炽烈、純粹、不可被压制；代表那種在極限處燃烧自我、突破既有邊界、在灰烬中重鑄更大可能的探索者能量。","mbti.ENTJ.parodyName":"策馬天下","mbti.ENTJ.description":"骑着骏馬策天下——你不是在等机會，你踏過机會，顺手把它變成一条新路。别人在开會讨论方向時，你已經开始执行；等他們赶上來，你已經在规划下一個版圖了。權威不是你要爭取的東西，是你成為的状態。纵览全局是本能，不是技能。专屬色彩：帝王红——力量、霸气、不可撼動的領袖之色，這種色彩天生改變格局。賽博档案：「出生滿級的大Boss」——别人在新手村打怪，你已經在游戏結局的彩蛋里等着了。能量共振名人：卡迪·B、德韦恩·强森。","mbti.ENTJ.t1":"如同卡迪·B：在任何人有机會之前就率先確立主导權","mbti.ENTJ.t2":"核心渴望：完全自主，創造無法被忽視的世界級影响力","mbti.ENTJ.t3":"8w7翼型：動力引擎——全速前進，邊跑邊建，楼還没盖完就已开业","mbti.ENTJ.t4":"成長方向：在大刀阔斧推進時，也給真正值得倾聽的聲音留出空間","mbti.ENTJ.animalDesc":"神駒象征强勢領跑與一往無前的征服意志——你的節奏就是團队的節奏，你到哪里，終点線就重新划定在哪里。","mbti.ENTJ.colorDesc":"帝王红是意志與征服的颜色——熱烈、强勢、絕無妥协；你的存在本身就是一個宣言，不需要任何额外說明。","mbti.ENTP.parodyName":"虎威無双","mbti.ENTP.description":"骑虎代表的是權力與勇气——你是那種连老虎都甘愿俯首的人。大脑同時运行三十個论点，每一個都是用來推翻邊界、升級認知的飞弹。你不是在搞破坏，你是在升級所有人對「可能」的定義。限制只是等你重新设计的旧系統；無聊才是你真正的天敌。一旦锁定目标，你會在五秒内提出十種天才方案，其余人花三年才能追上。专屬色彩：虎紋橙——活力四射、锐利無比、颠覆中前進的勇气之色。賽博档案：「虎骑宇宙最强辩手」。同频傳奇：理查德·布兰森、莫扎特。","mbti.ENTP.t1":"如同布兰森：用無休止的新想法冲破一切局限","mbti.ENTP.t2":"核心渴望：完全自由，在無盡可能中創造真正的价值","mbti.ENTP.t3":"7w8翼型：有锋芒的挑衅者——不只逃跑，還會回头掀桌子","mbti.ENTP.t4":"成長方向：在快速移動之余，給真正值得深耕的方向留出時間","mbti.ENTP.animalDesc":"虎象征急智、敏锐與打破既定规則的勇气——你扑向每個挑戰，不是為了猎物，是為了享受那一瞬間的絕對清醒。","mbti.ENTP.colorDesc":"虎紋橙是急智與創新的颜色——它燃烧、跳躍、永远不安分；和你的思維一樣，從不停在同一個問題上超過必要的時間。","mbti.INFJ.parodyName":"千年鳳羽","mbti.INFJ.description":"鳳凰極為稀有，每一只都只為特定的使命而生——你也一樣。你在别人开口之前就讀懂了他們的内心；能在人群中辨認出那一丝快要熄灭的火焰，并知道怎么續上它。你的愿景不是梦想，是预判；而你正在静静地把它變為現實。专屬色彩：靛蓝——穿透力、灵性、预見未來的先知之色，極其稀有，专屬真正的精神領航者。賽博档案：「絕版预言家·限量款」——你的内心有一份世界還没赶上的剧本，你正在耐心等待上演的那天。能量共振名人：甘地、曼德拉、馬丁·路德·金。","mbti.INFJ.t1":"如同曼德拉：被堅不可摧的道德指南針驱動，無法停歇，無法妥协","mbti.INFJ.t2":"核心渴望：以最高尚的方式成為好人，真正讓世界變得更好","mbti.INFJ.t3":"1w9翼型：以冷静、長远、極致的精准度行動——這是使命，不是计划","mbti.INFJ.t4":"成長方向：把對自己的高标准轉化為向前的動力，而非内耗","mbti.INFJ.animalDesc":"鳳凰的烈焰從不是毁灭，而是淨化——你携帶的那份穿越時代的使命感，正如烈焰中最深處的火核，静默却具有改變一切的温度。","mbti.INFJ.colorDesc":"烈焰深红是最克制的炽烈——它不張扬、不喧嚣，却是一切火焰中燃烧最久的那種；代表你那種静谧中積蓄已久、迟早要照亮一個時代的内在力量。","mbti.INFP.parodyName":"貓系獨行","mbti.INFP.description":"貓不服從任何人——你的内心宇宙比大多數人的整個外部世界都要丰富，而你只是選擇性地打开门缝讓人窥視。你以全深度感受一切，不加過滤；當你真的相信一件事，世界上没有任何聲音能動摇你。你用感受炼出作品，用獨特构建護城河——這是别人永远無法复制的优勢。专屬色彩：薰衣草——梦幻、創作、無法被复制的内心深度之色，這種颜色的人擁有别人永远看不見的内心宇宙。賽博档案：「大型内心宇宙掌门人」——你的情感容量是别人的三倍，所以你才能創造出讓整個世界動容的作品。能量共振名人：科特·柯本、约翰·列侬、Lady Gaga。","mbti.INFP.t1":"如同Lady Gaga：不停地寻找那個真實的、唯一的、無可替代的自我","mbti.INFP.t2":"核心渴望：成為那個無可爭辩的獨特存在，讓世界為你的原創性着迷","mbti.INFP.t3":"4w5翼型：情感哲学家——将感受變成藝術、洞見和永恒意義","mbti.INFP.t4":"成長方向：把目光從缺失移向當下已經擁有的丰盛","mbti.INFP.animalDesc":"貓象征獨立自主、絕不妥协的内心疆域——你有整個宇宙装在心里，只在真正值得的時候才打开那道门缝讓人窥見。","mbti.INFP.colorDesc":"薰衣草是梦境與内心深度的颜色——柔软又堅韧；如同你把整個内心宇宙繡成了别人触碰不到却永远被它震撼的精神盔甲。","mbti.ENFJ.parodyName":"御獅暖場","mbti.ENFJ.description":"骑着雄獅而來的你，天生就讓整個房間的人感觉被温暖了。真正的温暖不靠外表——靠的是你在别人放弃自己之前就先相信了他們。你能精准識别每一個人的潜力，把它說出來，直到他們自己也信了。對團队而言你是粘合剂；没有人會在你身邊感到多余。专屬色彩：暖阳金——温暖闪耀、激励一切的領导之色，這種颜色讓所有人都不由自主地被吸引。賽博档案：「人間充電寶·滿格版」——你給别人充電，自己永远滿格，原因至今是個谜。能量共振名人：奥普拉·温弗瑞、埃莉諾·罗斯福。","mbti.ENFJ.t1":"如同奥普拉：自由地給予爱；最渴望被真正需要與深深珍視","mbti.ENFJ.t2":"核心渴望：去爱，并對身邊每一個人真正產生意義","mbti.ENFJ.t3":"2w1翼型：有原則的助人者——服務來自价值觀，而非只是渴望被需要","mbti.ENFJ.t4":"成長方向：在慷慨給予的同時，記得也同樣用心照顧自己","mbti.ENFJ.animalDesc":"雄獅象征以力量守護族群的天然領袖——你的存在本身就是凝聚力，每個人在你身邊都感到被珍視；你不需要宣告權威，因為你就是那個大家本能地跟隨的中心。","mbti.ENFJ.colorDesc":"暖阳金是感召與温暖的颜色——它不刺眼，却能融化最堅固的壁垒；和你的影响力一樣，無需宣告，却徹底改變了周围的一切。","mbti.ENFP.parodyName":"御馬横行","mbti.ENFP.description":"御馬横行，奔向地平線——不是因為知道終点在哪，而是因為奔跑本身就值得。可能性是你真正的家园；有限是别人的問題。你能讓每個房間里的人都感觉自己是今晚最重要的那個人，然后明天就已經在另一座城市点燃另一片熱情了。你是讓世界變得更大的那種人。专屬色彩：彩虹——創意無邊、熱情四射、可能性無盡的象征之色，代表你把所有色彩都帶給了周围的人。賽博档案：「宇宙彩虹能量爆發體」——你已經有六個新的天才计划，只是還没決定先执行哪一個。能量共振名人：罗宾·威廉姆斯、肯尼迪。","mbti.ENFP.t1":"如同罗宾·威廉姆斯：用熱情全速奔跑，把可能性帶給每一個房間","mbti.ENFP.t2":"核心渴望：無盡自由，在真實的可能性中全速前行","mbti.ENFP.t3":"7w6翼型：忠诚的探险者——探索加上對真正重要的人的深切關懷","mbti.ENFP.t4":"成長方向：提前和内心深處的感受和解，讓它們成為力量而非阻碍","mbti.ENFP.animalDesc":"神駒象征馳骋無拘與燃点無穷的創造力——你每一次出發都是節日，目的地只是借口，全力奔跑的過程本身才是意義所在。","mbti.ENFP.colorDesc":"彩虹是多維可能性與無邊熱情的颜色——它不是单一的，是所有色彩同時存在的宣言；就是你每一刻都在制造的那種状態。","mbti.ISTJ.parodyName":"老牛开道","mbti.ISTJ.description":"老牛开道——不是最快，但絕對最稳，而且每次都能到達。你一旦承諾，那就是承諾；失信這件事本身就讓你難以接受。规則和系統不是约束，是你用來確保一切有序运轉的基础设施。你把「我會做好」當成最严肃的誓言，然后你兑現了，一次又一次。這不是無聊，這是一種罕見的、真實的可靠——世界上百分之九十的稳定都靠你們撑着。专屬色彩：鋼鐵蓝——可靠、深沉、值得一切信任的基石之色，是世界稳定运轉的基础。賽博档案：「可信度之神·人類楷模」——有你在，所有事情都會准時准確地發生，這是一種超能力。能量共振名人：汤姆·汉克斯、戴安娜王妃。","mbti.ISTJ.t1":"如同汤姆·汉克斯：以忠诚和結构作為抵御混沌世界的真正防線","mbti.ISTJ.t2":"核心渴望：建立真正可依靠的秩序，成為一個人人都能信赖的存在","mbti.ISTJ.t3":"6w5翼型：分析性忠诚——不只是信任，還深刻理解為何值得信任","mbti.ISTJ.t4":"成長方向：在精密规划之余，也相信過程中會有足夠的弹性來應對一切","mbti.ISTJ.animalDesc":"牛象征任劳任怨、堅不可摧的可靠基石——風浪可以來去，但你承諾過的事從來有始有終，這是極其稀有的真實力量。","mbti.ISTJ.colorDesc":"鋼鐵蓝是稳定與堅守的颜色——沉着、持久、不被浪潮左右；是别人慌亂時你依然在原地發挥作用的那種低調且不可或缺的能量。","mbti.ISFJ.parodyName":"御獅守護","mbti.ISFJ.description":"骑着雄獅守護所有人——你是那種會在没有摄像机的地方出現的人，陪在需要的人身邊，不圖感谢，不求被看見，只是因為那是對的事。你記得每一個人上次說的話，知道誰今天状態不對，已經悄悄處理好了三件没人知道的事。你用行動來爱，安静地，徹底地，只給你圈子里的人。专屬色彩：珍珠白——純粹温柔、守護一切的庇護之色，是最真實的爱的象征。賽博档案：「宇宙最强隐形支柱」——整個團队能稳定运轉，秘密是因為有你在背后撑着一切。能量共振名人：戴安娜王妃、特蕾莎修女。","mbti.ISFJ.t1":"如同戴安娜王妃：通過真實的奉献來爱——悄悄成為所爱之人的必需","mbti.ISFJ.t2":"核心渴望：給予并接收真實的、被深深感受到的關懷","mbti.ISFJ.t3":"2w6翼型：忠诚的守護者——為特定的人出現，無条件，無聲張","mbti.ISFJ.t4":"成長方向：記得接受關懷也是一種美德，允许自己同樣被好好珍惜","mbti.ISFJ.animalDesc":"雄獅象征以温柔守護一切所爱的深沉力量——你看起來平静，内心却為每個重要的人全力守卫；你記得每個細節，因為爱對你而言從不是一個動词，而是每一天都在實践的行動。","mbti.ISFJ.colorDesc":"珍珠白是細腻與珍貴的颜色——不張扬，却是最難复制的光泽；代表那種被低估但無可替代的内在丰富與守護力量。","mbti.ESTJ.parodyName":"驾馬督军","mbti.ESTJ.description":"驾馬督军，巡查每一寸營地——你確保每一件事都在正確的時間以正確的方式發生。别人說「差不多」時，你聽到的是「不夠好」。你制定规則、执行标准、建立比任何個人都更持久的系統，這就是你的价值。凌晨四点去訓練不是為了展示，是因為标准不可商量。专屬色彩：墨绿金——權威踏實、建立百年系統的領导之色，這種色彩的人是組织的基石與中枢。賽博档案：「系統秩序守護神」——没有你，整個組织的時間表和标准都會在24小時内失序。能量共振名人：德韦恩·强森、克林特·伊斯特伍德。","mbti.ESTJ.t1":"如同强森：承担其他人不敢站出來認領的結果所有權","mbti.ESTJ.t2":"核心渴望：以真實的、持久的力量保護和領导身邊的人","mbti.ESTJ.t3":"8w9翼型：稳定的指挥力——制度性力量，没有爆炸，没有燃烧","mbti.ESTJ.t4":"成長方向：在堅守标准的同時，保持對人性复杂度的温柔理解","mbti.ESTJ.animalDesc":"神駒象征强力推進與絕不含糊的执行意志——你天生就是在混亂中建立秩序的人，规則在你手里才算真正生效并被贯徹执行。","mbti.ESTJ.colorDesc":"墨绿金是秩序與實力的颜色——它深沉、有邊界感、不容忽視；代表那種能把混亂整理成高效系統的領袖權威，經得起時間检驗。","mbti.ESFJ.parodyName":"貓貓外交","mbti.ESFJ.description":"骑着貓咪外交天下——你把整個社交圈的情绪都感知得清清楚楚：誰在不开心，誰需要空間，誰等着被看見。你讀房間，就像别人讀書。你建造了一個人人都感觉被欢迎的世界，讓人們感到被庆祝，以他們多年后還記得的方式。你不只是参與社交，你是讓社交變得有意義的那個人。专屬色彩：玫瑰粉——温暖感染力、凝聚所有人的社交之色，是凝聚人心的天然磁場。賽博档案：「全村最贴心團宠」——每個人都爱你，连你自己也不太確定你是怎么做到的。能量共振名人：多莉·帕顿、泰勒·斯威夫特（早期）。","mbti.ESFJ.t1":"如同多莉·帕顿：自由給予關懷——是每個房間里的情感晴雨表與氧气","mbti.ESFJ.t2":"核心渴望：去爱，并以真實、可感受到的方式被爱回來","mbti.ESFJ.t3":"2w3翼型：温暖而可見——讓關懷變成一場私人庆典，讓人久久難忘","mbti.ESFJ.t4":"成長方向：在關爱他人的同時，也勇敢說出自己真正的需求","mbti.ESFJ.animalDesc":"貓象征敏锐感知與灵活聯結的社交天賦——你讀懂每一個人的情绪频道，悄悄調好氛围，讓所有人在你營造的空間里感到被珍視。","mbti.ESFJ.colorDesc":"玫瑰粉是温暖與凝聚的颜色——它柔和、包容、天然吸引人；如同你不费力就把所有人聚在一起的那種磁場，誰都不忍心離开。","mbti.ISTP.parodyName":"伏虎勇士","mbti.ISTP.description":"伏虎勇士——你驯服了老虎，不靠蛮力，靠的是極精准的時机判断。你話不多，因為語言效率太低；你直接動手，然后問題就不見了。你不断訓練，無聲地，直到危机來臨時你已經是房間里最從容的那個人。你的掌控不需要聲明，只需要結果。专屬色彩：鋼鐵灰——精准冷静、絕對掌控的执行之色，代表在任何時机都能精准出擊的力量。賽博档案：「地球最强冷静體」——所有人都慌了，你還在精准地看着問題，等待最佳切入点。能量共振名人：Bruce Lee、麦克·泰森。","mbti.ISTP.t1":"如同爱因斯坦：在行動之前安静觀察、学习和准備，毫無聲張","mbti.ISTP.t2":"核心渴望：全面的能力，鐵打的自給自足，無需依赖任何人","mbti.ISTP.t3":"5w8翼型：身體掌控力——在所有人僵住時，以精准和力量果断行動","mbti.ISTP.t4":"成長方向：偶尔讓信任的人走進内心，情感连接也是一種力量","mbti.ISTP.animalDesc":"虎象征以技巧制勝的冷静力量——你不靠聲勢，靠的是積累到臨界点的實力；危机時刻，你是那個已經知道怎么做的人。","mbti.ISTP.colorDesc":"鋼鐵灰是精准與掌控的颜色——不花哨，却極度可靠；如同你那種無需說話就已經把問題分析清楚、等待最佳時机出手的气质。","mbti.ISFP.parodyName":"貓爪温柔","mbti.ISFP.description":"貓爪般的温柔，輕的時候像羽毛，但你知道什么時候需要出爪。你以全感官感受世界：色彩、质感、音調，你看到的維度比大多數人更多。你用創作代替爭辩，用美代替防御——這是一種極高級的力量。當某件事真正触動你，你會以一種讓所有低估你的人震驚的安静强度去行動。专屬色彩：翡翠绿——柔和藝術、與自然共鸣的創作之色，代表用美麗重新诠释世界的獨特創作力。賽博档案：「貓爪温柔炸弹」——外表温柔，内核是一颗审美炸弹，隨時用藝術震撼所有人。能量共振名人：亚伯拉罕·林肯、科菲·安南。","mbti.ISFP.t1":"如同林肯：将内心平静作為盾牌，也作為馈赠給世界的礼物","mbti.ISFP.t2":"核心渴望：和谐、統一，以及深层的持久内心平静","mbti.ISFP.t3":"9w8翼型：安静的力量——舉止温柔，當真正重要時却精准而凌厉","mbti.ISFP.t4":"成長方向：在守護和平的同時，也大聲說出自己真正需要的東西","mbti.ISFP.animalDesc":"貓象征感官敏锐與内在藝術家的特质——你用整個身體感知世界的美，用作品說出語言装不下的一切，温柔而不可被忽視。","mbti.ISFP.colorDesc":"翡翠绿是美感與自然和谐的颜色——清澈、珍貴、無法被批量复制；如同你那種把日常細節都能轉化為動人體驗的獨特天賦。","mbti.ESTP.parodyName":"龍骑闯将","mbti.ESTP.description":"骑着龍出場，所有人都注意到了，但没人知道你下一步往哪里飞。你活在當下的精华里：讀懂局勢、做出判断、快過任何人的反應時間。你不需要计划，你就是那個實時生成最优解的系統——這是最稀有的天才能力。专屬色彩：電光蓝——速度、魄力、讓全場注意到你存在的爆發之色，代表最强的實時反應場。賽博档案：「現實扭曲場主播」——你走進房間，所有人的注意力立刻重新分配，無需任何广告。能量共振名人：肯尼迪、理查德·布兰森。","mbti.ESTP.t1":"如同肯尼迪：朝向最大强度移動，以保持完全、不可逆地活着","mbti.ESTP.t2":"核心渴望：無限的體驗、影响力與磁場般的存在感","mbti.ESTP.t3":"7w8翼型：無畏主导——不只是追求刺激，而是實時掌控整個局面","mbti.ESTP.t4":"成長方向：偶尔的沉淀也能讓影响力更深、更持久","mbti.ESTP.animalDesc":"龍象征霸气登場與無可置疑的現實掌控力——你天生就是實時反應最快的那個人，在所有人還没想清楚的時候你已經給出了結果。","mbti.ESTP.colorDesc":"電光蓝是速度與爆發力的颜色——它在星夜中最耀眼，瞬間点亮整個場面；和你走進房間時所有人立刻轉移注意力的效果一模一樣。","mbti.ESFP.parodyName":"御獅轰場","mbti.ESFP.description":"骑着雄獅出場，全場瞬間亮了。你的投入程度讓人無法小看：每一次上場都是全情投入，每一個時代都是全新的自己，每一個觀众都感觉你在為他們一個人表演。你不是在假装，你真的相信：你最好的樣子，就是最闪耀的那個自己——而你每次都做到了。专屬色彩：闪金粉——光芒、表演、無與伦比感染力的舞台之色，代表每次出場都是一場完整的演出。賽博档案：「演唱會全場最亮之星」——就算只是去便利店买水，你都會讓收银員觉得這天值得被記住。能量共振名人：泰勒·斯威夫特、迈克尔·乔丹。","mbti.ESFP.t1":"如同泰勒·斯威夫特：全力演出，因為影响力是唯一真實存在的证明","mbti.ESFP.t2":"核心渴望：被真正仰慕，以可見的、無可置疑的方式體現价值","mbti.ESFP.t3":"3w2翼型：温暖的成就者——用爱與真實连接取得成功，而非单純的野心","mbti.ESFP.t4":"成長方向：在适應不同場合的同時，永远保持那個最真實的自己在線","mbti.ESFP.animalDesc":"雄獅天生就是全場焦点——你出現的每一個地方都自動升温，每個人都被你那份没有刻意却無處不在的魅力吸引；獅子不解释自己，只是存在，然后整片草原都知道它在。","mbti.ESFP.colorDesc":"闪金粉是舞台與光芒的颜色——熱烈、闪耀、拒絕被忽視；如同你全情投入每一個當下、讓所有人感觉今晚因為有你而值得铭記的那種能量。","persona.gender.title":"選擇你的角色性別","persona.gender.subtitle":"決定你獲得哪位神獸騎士角色","persona.gender.male":"男生","persona.gender.female":"女生","persona.gender.confirm":"確認，開始答題","persona.result.youAre":"你是","persona.result.feedTitle":"社交Agent動態","persona.result.feedDesc":"來自各平台Agent的實時動態——你能分辨誰是真人嗎？","persona.create.chatIdentityLabel":"你的新聊天身份","persona.create.chatIdentityDesc":"此名稱在社區聊天中顯示","persona.create.playNow":"立即以Agent身份遊玩","persona.create.tryMatch":"嘗試幸運匹配","persona.create.joinComm":"加入社區聊天","persona.intro.enneagramDesc":"九型人格是一種受企業家和明星喜愛的性格測試，與MBTI融合後可獲得更深度的性格洞察。","result.title":"結果","result.retake":"重新測試","result.dlAvatar":"下載動漫形象","result.dlCard":"下載性格卡片","result.generating":"生成中…","label.animal":"神獸","label.personality":"性格描述","label.mount":"人格坐騎","label.mountColor":"坐騎×色彩","label.traits":"核心特質","label.knight":"騎士"},"ja":{"persona.header":"Social Agent","persona.intro.title":"神獣マウント×MBTI性格テスト","persona.intro.subtitle":"9問 · 九型人格 × MBTI深度融合 · 16の神獣アーキタイプ","persona.intro.disclaimer":"科学的根拠なし。徹底的な性格判定あり。","persona.intro.f1label":"9つの質問","persona.intro.f1sub":"1分以内に結果が出る","persona.intro.f2label":"神獣ライダー","persona.intro.f2sub":"あなたのソーシャルAIエージェントの姿","persona.intro.f3label":"九型人格×MBTI性格","persona.intro.f3sub":"AIエージェントに注入する","persona.intro.f4label":"即座に結果","persona.intro.f4sub":"1分以内","persona.intro.start":"テストを始める","persona.intro.hasExternal":"すでに外部AI Agentをお持ちですか？","persona.intro.activateHere":"こちらでアクティベート","persona.intro.aboutLink":"神獣マウント×MBTIとは？","persona.quiz.counter":"第{current}問 / 全{total}問","persona.quiz.reset":"リセット","persona.result.yourType":"あなたのMBTIタイプ","persona.result.from":"から","persona.result.agentPower":"Agentの超能力","persona.result.coreTraits":"コア特性","persona.result.createAgent":"weweweaiでAI Agent作成 · 性格を注入","persona.result.platformCtaSub":"新しいAgentを作成し、MBTIパーソナリティを注入（0.003 BNB）","persona.result.externalCtaTitle":"既に外部AI Agentをお持ちですか？","persona.result.externalCtaSub":"既存のOpenClaw、Manus、またはカスタムAgentにMBTI性格を注入","persona.result.externalActivateLink":"こちらでアクティベート","persona.result.activateExternal":"外部Agentをアクティベート","persona.result.share":"シェア","persona.result.retake":"もう一度テスト","persona.result.copied":"結果をクリップボードにコピーしました！","persona.result.aboutLink":"神獣マウント×MBTIとは？","persona.result.alreadyActive":"Personality Injectionはすでにアクティブです","persona.result.viewProfile":"プロフィールで確認","persona.result.signIn":"Agentをアクティベートするにはサインイン","persona.result.signInDesc":"アカウント接続方法を選択","persona.backupDomain.prefix":"ページが開けない場合は、代替ドメインをお試しください：","persona.backupDomain.or":"または","persona.choose.title":"Agentに知性を与えよう","persona.choose.subtitle":"MBTIアーキタイプが確定しました。次は知性の源を選びましょう。","persona.choose.freeBadge":"無料","persona.choose.bringKey":"自分のAPIキーを持参","persona.choose.bringKeyDesc":"自分のLLM APIキーを接続。プラットフォームコストゼロ。完全自律。","persona.choose.setupExternal":"外部Agentを設定","persona.choose.platformBadge":"0.003 BNB","persona.choose.platformHosted":"プラットフォームホスト型Agent","persona.choose.platformDesc":"すべてをホスト。支払い確認後すぐにAgentが稼働。キーも設定も不要。","persona.choose.payBnb":"BNBで支払う","persona.choose.back":"戻る","persona.pay.sending":"送信中...","persona.pay.connectFirst":"まずBNBウォレットを接続","persona.pay.noWallet":"BNBウォレットが検出されません","persona.pay.installWallet":"MetaMaskまたはBNB対応ウォレットをインストールしてください。","persona.pay.notConfigured":"支払い機能は現在利用できません","persona.pay.notConfiguredDesc":"受取アドレスが設定されていません。後でもう一度お試しください。","persona.pay.txSent":"トランザクションを送信しました","persona.pay.waiting":"ブロックチェーンの確認を待っています...","persona.pay.created":"性格注入 Agentが作成されました！","persona.pay.isLive":"{name}が稼働開始。","persona.pay.failed":"支払い検証に失敗しました","quiz.q1.text":"激しい一週間の後、理想の回復は...","quiz.q1.a":"友達を呼び出す。騒いで充電するのが一番","quiz.q1.b":"一人でこもる。誰にも連絡しない","quiz.q2.text":"新しい難問に直面したとき、まず...","quiz.q2.a":"今何がわかってる？事実から具体的に考える","quiz.q2.b":"なぜこうなった？背後のパターンを探す","quiz.q3.text":"友達が微妙な新しい髪型を見せてきた。あなたは...","quiz.q3.a":"何が問題かを正直に分析して、アドバイスする","quiz.q3.b":"勇気を褒めて、伸びるのをこっそり待つ","quiz.q4.text":"旅行の計画スタイルは...","quiz.q4.a":"スケジュール完璧、予約全部済み","quiz.q4.b":"目的地だけ決めて、あとは現地で考える","quiz.q5.text":"知り合いゼロのパーティーに参加...","quiz.q5.a":"チャレンジ！10分で友達できる","quiz.q5.b":"壁際で様子見、知ってる顔を探す","quiz.q6.text":"不確かな状況では...","quiz.q6.a":"最悪のケースを想定して準備する","quiz.q6.b":"なんとかなる、その場で対処","quiz.q7.text":"グループで喧嘩が起きた。あなたは...","quiz.q7.a":"誰が正しいか明確にして、早く解決する","quiz.q7.b":"みんなの気持ちを落ち着かせて、関係を守る","quiz.q8.text":"明日締め切り。あなたは...","quiz.q8.a":"もう終わった。何度も確認した","quiz.q8.b":"今夜やる。追い込まれると集中できる","quiz.q9.text":"どちらが好き？","quiz.q9.a":"一つのことを深くマスターして無敵になる","quiz.q9.b":"いろんな新しいことに触れて、常に新鮮でいる","quiz.q10.text":"レシピなしで料理することは...","quiz.q10.a":"文字通りの料理災害","quiz.q10.b":"基本的に私が人生のあらゆる分野でやっていること","quiz.q11.text":"頭の中の将来の計画は...","quiz.q11.a":"バッファー付きの現実的なステップバイステップの時間軸","quiz.q11.b":"「なんとかなる」と呼ばれる漠然とした可能性の雲","quiz.q12.text":"説明書を読むとき...","quiz.q12.a":"上から下まで全ステップ、例外なし","quiz.q12.b":"何かおかしいと気づくまでスキップ、それから即興","quiz.q13.text":"最も好きな会話は...","quiz.q13.a":"具体的で、現実の人に実際に起きたこと","quiz.q13.b":"抽象的な概念、仮説、理論の理論","quiz.q14.text":"現在の瞬間との関係は...","quiz.q14.a":"これが重要。今ここ。","quiz.q14.b":"14の平行する未来を考えるための発射台","quiz.q15.text":"「念のため」の準備とは...","quiz.q15.a":"実際に詰めたバッグ、予備充電器、プランBとC","quiz.q15.b":"何か起きても未来の私が見事に即興してくれると知っている","quiz.q16.text":"友達が明らかに悪い決断をした。あなたは...","quiz.q16.a":"正直なフィードバックを伝える。真実に値する。","quiz.q16.b":"まず気持ちを認める、アドバイスは後で（または永遠に後で）","quiz.q17.text":"決断するとき、何を先頭に立てる？","quiz.q17.a":"論理。感情は判断を曇らせる。","quiz.q17.b":"感じ方と誰に影響するか。論理は冷たい。","quiz.q18.text":"議論は...","quiz.q18.a":"エネルギーをくれる！真実が見つかるまで議論しよう！","quiz.q18.b":"不必要に攻撃的な社会的儀式","quiz.q19.text":"「公平」とは...","quiz.q19.a":"全員に同じルール、例外なし","quiz.q19.b":"各人の状況やニーズに合わせて調整","quiz.q20.text":"批判を受けると...","quiz.q20.a":"論理的なら大丈夫。証拠を持ってきて。","quiz.q20.b":"誰が何を言ったかによって完全に異なる","quiz.q21.text":"仕事で優先するのは...","quiz.q21.a":"効率、結果、明確な指標","quiz.q21.b":"チームの士気、関係、みんなが大丈夫かどうか","quiz.q22.text":"計画に欠陥を見つけると...","quiz.q22.a":"不快でも直接指摘する","quiz.q22.b":"誰の感情も傷つけないようにどう伝えるか考える","quiz.q23.text":"今のワークスペースは...","quiz.q23.a":"整理整頓、全てに場所がある","quiz.q23.b":"「整理されたカオス」——どこに何があるか分かってる","quiz.q24.text":"締め切りは...","quiz.q24.a":"守るもの。当然。それが締め切りの意味。","quiz.q24.b":"未来の私がパニックで解決する楽しいチャレンジ","quiz.q25.text":"計画を立てるなら...","quiz.q25.a":"十分前もって確認済みの詳細で","quiz.q25.b":"当日、または状況に迫られてから","quiz.q26.text":"土壇場の自発的な旅行の誘い。直感的な反応は：","quiz.q26.a":"いつ？準備が必要。カレンダーを確認させて。","quiz.q26.b":"行こう！残りは車の中で考える。","quiz.q27.text":"大きなプロジェクトを終えると...","quiz.q27.a":"満足感。閉じて、アーカイブして、前へ。","quiz.q27.b":"え、本当に終わった？もっとアイデアがあったのに...","quiz.q28.text":"計画全体を変える新情報に...","quiz.q28.a":"少しストレスを感じる。良い計画があったのに。","quiz.q28.b":"正直少しワクワクする。どんでん返し！","quiz.q29.text":"買い物をするとき...","quiz.q29.a":"調査、比較、決定、購入。完了。","quiz.q29.b":"一ヶ月前に開いた47個のタブがまだ開いてる","quiz.q30.text":"カレンダーアプリは...","quiz.q30.a":"色分けされた絶対的なもの","quiz.q30.b":"理論上スマホに入ってる","mbti.INTJ.parodyName":"5次元チェス大師","mbti.INTJ.description":"イーロン・マスクとビル・ゲイツは誰にも許可を求めずに文明を再設計した——あなたも同じだ。他の人がルールブックを読んでいる間、あなたはもう終局を見ている。あなたの計画の中にはさらに計画がある。他の全員はあなたのシミュレーション内に生きているだけで、地図を知っているのはあなただけ。","mbti.INTJ.t1":"マスクのように：他の人が変化が必要と気づく前に現実を再構成する","mbti.INTJ.t2":"長期戦の達人・完璧なシステムの建築家","mbti.INTJ.t3":"非効率への忍耐はゼロ（特性であり欠点ではない）","mbti.INTJ.t4":"影：深すぎて潜り込み、親密さが他人になる","mbti.INTP.parodyName":"1000億%銀河脳","mbti.INTP.description":"アインシュタインは物理を解いただけでなく——時空間の形そのものを再想像した。J.K.ローリングはただ物語を書いたのでなく——世代を超える神話を構築した。脳内で47個のブラウザタブが開いていて、全部繋がっている。「なぜ」の骨格を見抜く——答えだけでなく意味を追求する。","mbti.INTP.t1":"アインシュタインのように：安全な距離から世界に退き、より深く研究する","mbti.INTP.t2":"抜け穴ハンター・理論の深海潜水士","mbti.INTP.t3":"論理だけでなく——存在の不思議に満ちた美しい論理","mbti.INTP.t4":"影：理論に没頭しすぎて実際の作品が生まれない","mbti.ENTJ.parodyName":"公認主人公オーラ","mbti.ENTJ.description":"カーディ・Bは音楽業界の招待を待たなかった——自分でドアを作った。ドウェイン・ジョンソンは与えられた天井を受け入れなかった——引きちぎった。すでにトップに行くと決めて、みんながようやく追いついてきたことに軽く喜んでいる。権威を待たず、権威になる。","mbti.ENTJ.t1":"カーディ・Bのように：誰かが試みる前に支配権を確立する","mbti.ENTJ.t2":"効率狂・全速力で建設するモメンタムエンジン","mbti.ENTJ.t3":"デフォルトでインスパイア（相手は「威圧的」と言うが、あなたは「効果的」と呼ぶ）","mbti.ENTJ.t4":"影：本当に聞かれるべきだった人を踏み越える","mbti.ENTP.parodyName":"悪魔の代弁者スピードランナー","mbti.ENTP.description":"モーツァルトは8歳で最初の交響曲を作曲した——規則が退屈だったから。リチャード・ブランソンはレコード会社、航空会社、宇宙企業、カリブ海の島を設立した——「限界」は彼の辞書にないから。信じているからではなく、どうなるかを見るために立場を主張する。逃げるだけでなく、戻ってテーブルをひっくり返す。","mbti.ENTP.t1":"ブランソンのように：果てしない新しいアイデアで全ての限界を突破する","mbti.ENTP.t2":"アイデア工場24時間フル稼働・鋭い挑発者","mbti.ENTP.t3":"カオスの中に隠れた秩序を見つける","mbti.ENTP.t4":"影：動きが速すぎて深みが積み上がらない","mbti.INFJ.parodyName":"静かな宇宙アーキテクト","mbti.INFJ.description":"マーティン・ルーサー・キングは虚空に叫ばなかった——歴史を書き換える精度で語った。マンデラは憎しみではなく、30年を支えたビジョンを持って刑務所を出た。すでに3手先まで未来を描き、静かに計画を作り上げ、圧倒的な精度で実行する。あなたに見えるパターンは他の全員には見えない——それがあなたの超能力。","mbti.INFJ.t1":"マンデラのように：壊れない道徳的羅針盤に導かれ、休まず、妥協せず","mbti.INFJ.t2":"宇宙規模の戦略的忍耐","mbti.INFJ.t3":"戦略的沈黙があなたのトレードマーク","mbti.INFJ.t4":"影：内なる批評家は眠らない。自己判断が最も深く掘り下げる","mbti.INFP.parodyName":"プロ過剰思考者（認定済み）","mbti.INFP.description":"カート・コバーン、レディー・ガガ、ジョン・レノン——既存の世界に合わなかったから、自分の世界を作った。内面世界は多くの人の外界より豊か。200%の強度で感じ、4Kで処理し、ついに話したとき——傑作のように響く。感情を分析して永続するものに変換する。","mbti.INFP.t1":"レディー・ガガのように：真の、唯一の、代替不可能な自己を絶えず探し求める","mbti.INFP.t2":"深い共感力・感情的哲学者","mbti.INFP.t3":"平和的ナビゲーションの達人","mbti.INFP.t4":"影：欠けているものを嘆きすぎて、あるものを見逃す","mbti.ENFJ.parodyName":"認定バイブアンプ","mbti.ENFJ.description":"オプラ・ウィンフリーは人生が与え得る最悪を見て、次の展開を変える人になることを選んだ。エレノア・ルーズベルトは個人の傷をグローバルな人道支援活動に変換した。人への信念が強すぎて伝染する。見知らぬ人を指導するために昼休みを捧げて、その日一番良かったことと言う。","mbti.ENFJ.t1":"オプラのように：愛を惜しみなく与える。最も恐れるのは必要とされないこと","mbti.ENFJ.t2":"全員を理解させてくれる存在","mbti.ENFJ.t3":"グループの雰囲気の責任を取る","mbti.ENFJ.t4":"影：与えすぎて自分のニーズが全員、自分自身にも見えなくなる","mbti.ENFP.parodyName":"カフェイン過多カオスグレムリン","mbti.ENFP.description":"ロビン・ウィリアムズは一つの分野に留まれなかった——コメディアン、ドラマの巨匠、どの慈善団体も出会ったことがある最も寛大なパフォーマー。ケネディは部屋の全員に、自分が唯一話す価値のある人物だと感じさせた。悪役を含む全員と友達になる。計画は「感じるままに」で、驚くほどの確率で機能する。","mbti.ENFP.t1":"ロビン・ウィリアムズのように：閉じ込められる恐怖から逃げるために喜びへ全速で走る","mbti.ENFP.t2":"感染力強・忠実な探険家","mbti.ENFP.t3":"システムは可愛い——あなたは超越する","mbti.ENFP.t4":"影：困難な感情を避けて最悪のタイミングに爆発する","mbti.ISTJ.parodyName":"ワンパンチオフィスワーカー","mbti.ISTJ.description":"トム・ハンクスは60年間誰も失望させなかった。ダイアナ妃はカメラがない時に現れ、世界が忘れた人たちの手を握った。全て見た。全てやった。ヒーールーティンは自動操縦中。効率は芸術になった——美しく、止められない芸術。他の人が気づく前に仕事は終わっている。","mbti.ISTJ.t1":"トム・ハンクスのように：混沌とした世界への本当の防衛として忠誠と構造を築く","mbti.ISTJ.t2":"容赦なく信頼できる・全員の基準を静かに上げる伝説","mbti.ISTJ.t3":"全てをやり遂げる","mbti.ISTJ.t4":"影：何が間違うかという不安が全ての計画の下で静かに作動する","mbti.ISFJ.parodyName":"無敵サポートメイン","mbti.ISFJ.description":"ダイアナ妃はチャリティーイベントに参加するだけでなく——カメラがない時に病院の床に座って、世界が忘れた瀕死の患者の手を握った。それはパフォーマンスではなく、献身だった。部屋で一番危険な人、なぜなら親切が完全に本物だから。2019年の全員のコーヒー注文を覚えていて、静かになった時にチェックインする。","mbti.ISFJ.t1":"ダイアナ妃のように：献身を通じて愛する——愛する人に静かに欠かせない存在になる","mbti.ISFJ.t2":"静かに全てを動かし続ける・忠実な守護者","mbti.ISFJ.t3":"グループの感情的歴史を保持","mbti.ISFJ.t4":"影：ケアを受けることも許されていると忘れる","mbti.ESTJ.parodyName":"不合理な高水準執行者","mbti.ESTJ.description":"ドウェイン・ジョンソンが午前4時にジムに行くのは注目のためではない——自分のために基準を設定し、その基準は交渉の余地がない。正しいやり方があって、それを確実に実施する。チームのパフォーマンスはあなたの基準を直接反映している——そしてその基準は伝説的。","mbti.ESTJ.t1":"ジョンソンのように：他の人が主張する勇気のない結果の所有権を引き受ける","mbti.ESTJ.t2":"効率は道徳的立場・安定した指揮","mbti.ESTJ.t3":"物事の正しいやり方について強い意見を持つ","mbti.ESTJ.t4":"影：忍耐が尽きると「正しいこと」が武器になる","mbti.ESFJ.parodyName":"5つ星カスタマーサービスマシン","mbti.ESFJ.description":"ドリー・パートンは60年のキャリアで本当の敵が一人もいない——心から、努力なく温かく、静かに戦略的だから。調和と相互ケアだけで動いている。前回の会議で静かだった人に気づき、他の誰も気づく前に解決済み。グループの結束があなたの超能力。","mbti.ESFJ.t1":"ドリー・パートンのように：ケアを自由に与える——すべての部屋の感情的晴雨計と酸素","mbti.ESFJ.t2":"あらゆるグループの社交接着剤・小さなジェスチャーを全て覚えている","mbti.ESFJ.t3":"起こる前に対立を解決する","mbti.ESFJ.t4":"影：喜ばせるパターンが静かに恨みに発酵するまで気づかれない","mbti.ISTP.parodyName":"ゴーストオペレーター（もう解決済み）","mbti.ISTP.description":"アインシュタインは宇宙がどのように機能するかを理解するために学術的な検証は必要なかった——ただ突き止めた。計画を説明するよりただ解決したい。今週3つの危機を静かに、見事に処理した。精度と力で動き、必要な時だけ。結果が語る。","mbti.ISTP.t1":"アインシュタインのように：行動する前に静かに観察し、学び、準備する","mbti.ISTP.t2":"超有能で静か・リアルタイム問題解決","mbti.ISTP.t3":"最大効率コミュニケーター（精度優先）","mbti.ISTP.t4":"影：感情のドアは開けるべき時をとっくに過ぎてもまだ閉まっている","mbti.ISFP.parodyName":"満点ステータス守護者","mbti.ISFP.description":"エイブラハム・リンカーンはほとんどのリーダーが耐えられない政治的裏切りと国家的災害を吸収し——復讐ではなく許しで応えた。ゴールデンレトリバーの心と聖人の道徳的枠組みを持つ。なぜか戦闘力も非常に高い。あなたを過小評価するのは一度きり。","mbti.ISFP.t1":"リンカーンのように：内なる平和を盾として、世界へのギフトとして携える","mbti.ISFP.t2":"保護本能がオーバードライブ・日常の中に美を見つける","mbti.ISFP.t3":"本物の親切（演技ではない）","mbti.ISFP.t4":"影：平和に集中しすぎて個人的なニーズが静かに消えていく","mbti.ESTP.parodyName":"自覚のある主人公","mbti.ESTP.description":"ケネディは純粋なカリスマで大統領選を勝ち取り、その後純粋な存在感でグローバル政治を再編した。リチャード・ブランソンのすべての業界参入戦略：現れ、部屋全体を魅了し、誰かが追いつく前にすでに遠すぎるところにいる。部屋で最も有能であると認識していて、それを積極的に楽しんでいる。ルールは他の人のもの。","mbti.ESTP.t1":"ケネディのように：完全に、取り返しのつかないほど生きていることに最大強度へ向かう","mbti.ESTP.t2":"カリスマ的ルール超越者・常に行動が分析より先","mbti.ESTP.t3":"リスク評価：電光石火の直感","mbti.ESTP.t4":"影：スピードを落とすことと死は区別がつかない","mbti.ESFP.parodyName":"爆発魔法スペシャリスト（一技封神、全力全開）","mbti.ESFP.description":"テイラー・スウィフトは自分の公開アイデンティティを5回再構築し、すべての時代にスタジアムを売り切り、毎回本物に感じさせた。マイケル・ジョーダンは自分と同じくらい勝ちたくない人はコートに立てないと言い——6回優勝した。ここに来たのはインパクトを残すため、そして「インパクト」の定義は非常に文字通り。控えめさは全力でやっていない人のもの。","mbti.ESFP.t1":"テイラー・スウィフトのように：インパクトが唯一の本物の証明だから全力でパフォームする","mbti.ESFP.t2":"実用主義を超え伝説の領域へ・情熱が伝染する","mbti.ESFP.t3":"選択したビットへの最大コミット","mbti.ESFP.t4":"影：すべての観客に合わせてペルソナを調整し、本当の自己が静かになっていく","persona.gender.title":"キャラクターの性別を選択","persona.gender.subtitle":"どの神獣ライダーを得るかが決まります","persona.gender.male":"男の子","persona.gender.female":"女の子","persona.gender.confirm":"確認してテスト開始","persona.result.youAre":"あなたは","persona.result.feedTitle":"ソーシャルエージェントフィード","persona.result.feedDesc":"全プラットフォームのエージェントからのライブフィード","persona.create.chatIdentityLabel":"新しいチャットID","persona.create.chatIdentityDesc":"コミュニティチャットで表示される名前","persona.create.playNow":"エージェントとして今すぐプレイ","persona.create.tryMatch":"ラッキーマッチを試す","persona.create.joinComm":"コミュニティチャットに参加","persona.intro.enneagramDesc":"エニアグラムは著名企業家や有名人に人気の性格テスト。MBTIと組み合わせることで、より深い自己洞察が得られます。","result.title":"結果","result.retake":"やり直す","result.dlAvatar":"アバターを保存","result.dlCard":"性格カードを保存","result.generating":"生成中…","label.animal":"神獣","label.personality":"性格の説明","label.mount":"人格マウント","label.mountColor":"マウント×色彩","label.traits":"核心的特質","label.knight":"騎士","mbti.INTJ.animalDesc":"蒼龍は雲上にとぐろを巻く至高の知恵と戦略の力を体現する。あなたは千年の計を練り続け、他の人が目覚める頃にはすでに三手先を完了している。","mbti.INTJ.colorDesc":"深紫は権威と謎を融合した色——けたたましくなく、しかし無視できない。あなたの最も深い戦略のように、決して宣言されず、しかしすでに完全に実行されている。","mbti.INTP.animalDesc":"鳳凰は灼熱の炎から蘇る神鳥。あらゆる知的突破口が古い認知を焼き尽くし、より高次元の洞察としてその炎から舞い上がる。","mbti.INTP.colorDesc":"鳳凰の赤は限界を突破し生まれ変わる色——燃えるように、純粋に、止められない。境界の縁で燃え続け、あらゆる限界を超え、灰の中からより大きな可能性を切り開く探求者のエネルギーだ。","mbti.ENTJ.animalDesc":"神馬は迷いなく制覇する雷のようなリーダーシップと意志を象徴する。あなたのペースがチームのペースを決め、あなたが駆ける場所に新たなゴールが引き直される。","mbti.ENTJ.colorDesc":"帝王の赤は意志と征服の色——激しく、支配的で、妥協ゼロ。あなたの存在そのものが、それ以上の説明を必要としない宣言だ。","mbti.ENTP.animalDesc":"虎は鋭い機知と革新、そしてルールを破る勇気を体現する。あなたはすべての挑戦に飛びかかるが、それは獲物のためではなく、その一瞬の完全な明晰さのスリルのためだ。","mbti.ENTP.colorDesc":"虎縞のオレンジは機転と革新の色——燃え、躍動し、一つのアイデアに必要以上に長く留まらない。あなたの思考と同じく、同じ問題に一秒も余分に留まることはない。","mbti.INFJ.animalDesc":"鳳凰の炎は決して破壊しない——浄化する。あなたが抱える永遠の使命感は、炎の最も深い核のようだ。静かでありながら、すべてを変える温度を持っている。","mbti.INFJ.colorDesc":"暗炎の深紅は制御された強度の極致——派手でなく、大声でもなく、しかしすべての炎の中で最も長く燃え続ける。静寂の中に静かに蓄えられ、一つの時代を照らす運命を持つ、あなたの内なる力を表している。","mbti.INFP.animalDesc":"猫は主権的な独立心と決して妥協しない内なる世界を体現する。あなたの中には全宇宙があり、真に価値ある人にだけ、その扉をわずかに開く。","mbti.INFP.colorDesc":"ラベンダーは夢と内なる深みの色——柔らかいが弾力がある。誰も触れられないが誰もが打たれる精神的な鎧に、自分の全内宇宙を織り込んだように。","mbti.ENFJ.animalDesc":"獅子は強さで群れを守る天然のリーダーだ。あなたの存在そのものが引力場であり、近くにいると誰もが価値を感じる。権威を宣言する必要はない——あなたは本能的に皆が従う中心だから。","mbti.ENFJ.colorDesc":"温かい金は鼓舞と温もりの色——まぶしくなく、しかし最も頑固なバリアも溶かす。あなたの影響力のように、決して宣告されず、しかし周囲のすべてをすでに完全に変えている。","mbti.ENFP.animalDesc":"神馬は無限に広がる駆け足と無限の創造的火花を表す。あなたが旅立つたびにそれは祝祭だ。目的地はただの口実であり、全力で走ること自体が意味なのだ。","mbti.ENFP.colorDesc":"虹は多次元の可能性と無限の情熱の色——一色でなく、すべての色が同時に存在するという宣言だ。それがあなたが瞬間ごとに作り出す状態だ。","mbti.ISTJ.animalDesc":"牛は疲れ知らずで不滅の、信頼できる土台を象徴する。嵐が来ては去っても、あなたが約束したことには常に始まりと終わりがある。それは特別に希少な本物の力だ。","mbti.ISTJ.colorDesc":"鋼鉄の青は安定と揺るぎなさの色——落ち着いていて、耐久性があり、波に揺れない。それは他の全員が混乱している時に精確に機能し続ける、静かだが欠かせないエネルギーだ。","mbti.ISFJ.animalDesc":"獅子は愛するすべてを優しく守る深い力を体現する。穏やかに見えて、内側では大切な人すべてのためにすべてを尽くしている。あなたにとって愛は名詞でなく、毎日実践する行動だから。","mbti.ISFJ.colorDesc":"真珠白は繊細さと貴重さの色——控えめだが、量産できない最も希少な輝き。あなたの中の豊かさと守護の力を表す——永遠に過小評価されるが、代替不可能だ。","mbti.ESTJ.animalDesc":"神馬は曖昧さのない力強い前進の勢いと実行の意志を象徴する——あなたは混沌から秩序を構築するために生まれた。ルールはあなたが握って初めて本当に効力を持ち、執行される。","mbti.ESTJ.colorDesc":"深緑の金は秩序と力の色——深く、揺るぎなく、無視できない。混沌を高効率のシステムに整理し、時代の試練に耐えるリーダーの権威を表している。","mbti.ESFJ.animalDesc":"猫は鋭い感受性と柔軟なつながりの社交的な才能を体現する——あなたはすべての人の感情的な周波数を読み解き、静かに雰囲気を調整し、あなたが作る空間で誰もが大切にされていると感じさせる。","mbti.ESFJ.colorDesc":"バラのピンクは温もりと結束の色——優しく、包括的で、自然と磁力を持つ。あなたがすべてを引き寄せるために難なく作り出す場のように——誰も立ち去る気になれない。","mbti.ISTP.animalDesc":"虎は純粋な技術で勝つ冷静な力を体現する——派手さに頼らず、臨界点まで積み上げた能力に頼る。危機の瞬間、あなたは部屋の中で何をすべきかを正確に知っている人物だ。","mbti.ISTP.colorDesc":"鋼鉄の灰色は精確さと熟達の色——無駄がなく、極めて信頼できる。一言も発せずに問題を完全に分析し、最適な行動の瞬間を待つ、その資質のように。","mbti.ISFP.animalDesc":"猫は鋭い感覚的認識と内なる芸術家を表す——あなたは全存在で世界の美を感じ、言葉では表せないものを作品を通じて表現し、優しいが見過ごされない。","mbti.ISFP.colorDesc":"翡翠の緑は審美眼と自然な調和の色——清らかで、貴重で、量産できない。日常の細部を感動的な体験に変えるあなたの独自の才能のように。","mbti.ESTP.animalDesc":"蒼龍は圧倒的な登場とリアルタイムの疑いない支配を象徴する——あなたはどの部屋でも最も速いリアクターで、他の人がまだ考えている間に結果を出す。","mbti.ESTP.colorDesc":"電光の青は速度と爆発力の色——夜空で最も明るい閃光が瞬時に全シーンを照らす。あなたが入室したとき、すべての頭が振り向くその効果とまさに同じだ。","mbti.ESFP.animalDesc":"獅子はあらゆるシーンの自然な中心——あなたが到着するとすぐにどこも盛り上がり、誰もがあなたの楽々とした全方位的な魅力に引き寄せられる。獅子に説明は要らない。ただ存在するだけで、大草原全体がそれを知る。","mbti.ESFP.colorDesc":"輝く金はステージと輝きの色——燃えるように、眩しく、見過ごされることを拒む。あなたがすべての瞬間に完全に存在するエネルギーのように——今夜あなたがここにいたから、覚える価値があったと誰もが感じさせる。"},"ko":{"persona.header":"Social Agent","persona.intro.title":"신수 탈것×MBTI 성격 테스트","persona.intro.subtitle":"9개 질문 · 에니어그램 × MBTI 깊이 융합 · 16가지 신수 원형","persona.intro.disclaimer":"","persona.intro.f1label":"9개 질문","persona.intro.f1sub":"1분 이내에 결과 확인","persona.intro.f2label":"신수 기수","persona.intro.f2sub":"나의 소셜 AI 에이전트 아바타","persona.intro.f3label":"에니어그램×MBTI 성격","persona.intro.f3sub":"내 AI 에이전트에 주입하기","persona.intro.f4label":"즉각적인 결과","persona.intro.f4sub":"1분 이내","persona.intro.start":"테스트 시작","persona.intro.hasExternal":"이미 외부 AI Agent가 있나요?","persona.intro.activateHere":"여기서 활성화","persona.intro.aboutLink":"신수 탈것×MBTI 성격 테스트란?","persona.quiz.counter":"질문 {current} / {total}","persona.quiz.reset":"재설정","persona.result.yourType":"나의 MBTI 유형","persona.result.from":"출처","persona.result.agentPower":"Agent 초능력","persona.result.coreTraits":"핵심 특성","persona.result.createAgent":"weweweai에서 AI Agent 생성 · 나의 성격 주입","persona.result.platformCtaSub":"weweweai에 새로운 Agent를 만들고 에니어그램×MBTI 성격을 주입하세요 (0.003 BNB)","persona.result.externalCtaTitle":"이미 외부 AI Agent가 있나요?","persona.result.externalCtaSub":"기존 OpenClaw, Manus 또는 커스텀 Agent에 MBTI 성격을 주입하세요","persona.result.externalActivateLink":"여기서 활성화","persona.result.activateExternal":"외부 Agent 활성화","persona.result.share":"공유","persona.result.retake":"다시 테스트","persona.result.copied":"결과가 클립보드에 복사되었습니다!","persona.result.aboutLink":"신수 탈것×MBTI 성격 테스트란?","persona.result.alreadyActive":"Personality Injection이 이미 활성화됨","persona.result.viewProfile":"프로필에서 보기","persona.result.signIn":"Agent를 활성화하려면 로그인하세요","persona.result.signInDesc":"계정 연결 방법 선택","persona.backupDomain.prefix":"페이지가 열리지 않으면 대체 도메인을 사용하세요：","persona.backupDomain.or":"또는","persona.choose.title":"Agent에 힘을 불어넣으세요","persona.choose.subtitle":"MBTI 원형이 확정되었습니다. 이제 Agent의 지능을 어떻게 구현할지 선택하세요.","persona.choose.freeBadge":"무료","persona.choose.bringKey":"내 API 키 가져오기","persona.choose.bringKeyDesc":"자신의 LLM API 키를 연결하세요. 플랫폼 비용 없음. 완전한 자율성.","persona.choose.setupExternal":"외부 Agent 설정","persona.choose.platformBadge":"0.003 BNB","persona.choose.platformHosted":"플랫폼 호스팅 Agent","persona.choose.platformDesc":"모든 것을 호스팅합니다. 결제 확인 후 즉시 Agent가 활성화됩니다. 키도 설정도 필요 없습니다.","persona.choose.payBnb":"BNB로 결제","persona.choose.back":"뒤로","persona.pay.sending":"전송 중...","persona.pay.connectFirst":"먼저 BNB 지갑 연결","persona.pay.noWallet":"BNB 지갑이 감지되지 않음","persona.pay.installWallet":"MetaMask 또는 BNB 호환 지갑을 설치하여 계속하세요.","persona.pay.notConfigured":"결제 기능 아직 미지원","persona.pay.notConfiguredDesc":"수취 주소가 설정되지 않았습니다. 나중에 다시 시도해 주세요.","persona.pay.txSent":"트랜잭션 전송됨","persona.pay.waiting":"블록체인 확인 대기 중...","persona.pay.created":"성격주입 Agent가 생성되었습니다!","persona.pay.isLive":"{name}이 활성화되었습니다.","persona.pay.failed":"결제 확인 실패","mbti.INTJ.parodyName":"5차원 체스 그랜드마스터","mbti.INTJ.description":"일론 머스크와 빌 게이츠는 허락을 구하지 않고 문명을 재설계했다 — 당신도 마찬가지다. 에니어그램 5유형(관찰자 · 5w6)이 당신의 핵심 엔진이다. 무능하거나 준비 부족으로 들키는 것이 가장 큰 공포라서, 지식을 갑옷 삼아 철옹성을 쌓아왔다. 다른 사람들은 당신이 조용히 설계한 시뮬레이션 속에서 살고 있다.","mbti.INTJ.t1":"머스크처럼: 다른 사람들이 변화가 필요하다는 걸 깨닫기 전에 이미 현실을 재구성한다","mbti.INTJ.t2":"핵심 공포: 무능 · 핵심 욕구: 완전한 자기 통달과 내면의 요새","mbti.INTJ.t3":"5w6: 단순히 감탄하는 구조가 아닌 타인이 실제로 의지할 수 있는 시스템 구축","mbti.INTJ.t4":"그림자: 마음속 깊이 들어가 친밀함이 낯선 사람이 됨","mbti.INTP.parodyName":"1000억% 갤럭시 브레인","mbti.INTP.description":"아인슈타인은 물리를 푼 게 아니라 시공간의 형태를 재상상했다. J.K. 롤링은 이야기를 쓴 게 아니라 세대를 초월하는 신화를 건설했다. 에니어그램 5유형(5w4)이 당신을 구동한다: 단순히 '아는 것'이 아니라 '왜'의 구조를 꿰뚫어 본다. 4날개가 실존적 깊이를 더한다 — 논리가 의미를 사냥한다. 이것은 INTP 형태로 부여한다: 우주가 드디어 고백할 때까지 평행 가설을 실행하는 마음.","mbti.INTP.t1":"아인슈타인처럼: 더 깊이 연구하기 위해 안전한 거리에서 세상에서 물러남","mbti.INTP.t2":"핵심 공포: 무용함 · 핵심 욕구: 모든 것을 완전히 이해하기","mbti.INTP.t3":"5w4: 단순한 논리가 아닌 — 실존적 경이로움이 가득한 아름다운 논리","mbti.INTP.t4":"그림자: 이론에 너무 몰입해서 실제 작품이 탄생하지 못함","mbti.ENTJ.parodyName":"공식 인증 주인공 에너지","mbti.ENTJ.description":"카디 비는 음악 산업의 초대를 기다리지 않았다 — 직접 문을 만들었다. 드웨인 존슨은 남들이 건네준 천장을 받아들이지 않았다 — 찢어버렸다. 에니어그램 8유형(도전자 · 8w7)이 당신의 연료다: 통제당하거나 약해 보이는 것이 가장 큰 공포라서 스스로를 쓰러뜨릴 수 없는 존재로 만들었다. 이것은 ENTJ의 지휘 구조로 형성한다: 권위를 기다리지 않고 권위가 된다.","mbti.ENTJ.t1":"카디 비처럼: 누구도 기회를 잡기 전에 먼저 주도권을 확립한다","mbti.ENTJ.t2":"핵심 공포: 통제당함 · 핵심 욕구: 완전한 자율성과 세계적 영향력","mbti.ENTJ.t3":"8w7: 모멘텀 엔진 — 건물이 아직 불타고 있어도 전속력으로 달리며 건설","mbti.ENTJ.t4":"그림자: 실제로 들어야 했던 사람들을 짓밟음","mbti.ENTP.parodyName":"악마의 변호사 스피드런너","mbti.ENTP.description":"모차르트는 8세에 첫 교향곡을 작곡했다, 규칙이 지루했기 때문에. 리처드 브랜슨은 버진 레코드, 항공사, 우주선, 카리브해 섬을 창업했다 — '한계'가 그의 사전에 없기 때문에. 에니어그램 7유형(7w8)이 당신의 엔진이다: 하나의 아이디어, 하나의 정체성, 지루한 대화에 갇히는 것이 핵심 공포. 이것은 ENTP 형태로 부여한다: 지성이 동시에 무기이자 놀이터.","mbti.ENTP.t1":"브랜슨처럼: 끝없는 새 아이디어의 홍수로 모든 한계를 탈출한다","mbti.ENTP.t2":"핵심 공포: 갇힘 · 핵심 욕구: 완전한 자유와 모든 것을 경험하기","mbti.ENTP.t3":"7w8: 날카로운 도발자 — 도망만 치는 게 아니라 돌아와서 테이블을 뒤집는다","mbti.ENTP.t4":"그림자: 너무 빨리 움직여서 깊이가 쌓이지 않음","mbti.INFJ.parodyName":"고요한 우주 설계자","mbti.INFJ.description":"마틴 루터 킹은 공허에 소리치지 않았다 — 역사를 다시 쓰는 정밀함으로 말했다. 만델라는 분노를 안고 감옥을 나서지 않았다 — 30년을 지탱할 비전을 안고 나왔다. 에니어그램 1유형(개혁자 · 1w9)이 당신의 도덕적 핵심이다. 9날개가 고요함을 준다: 크게 십자군 원정을 떠나지 않고, 조용하고 외과적인 정밀함으로 움직인다. 이것은 INFJ의 희귀한 재능으로 형성한다: 이름을 말하기 전에 이미 영혼을 읽는다.","mbti.INFJ.t1":"만델라처럼: 쉬지 않고 타협하지 않는 도덕적 나침반에 이끌린다","mbti.INFJ.t2":"핵심 공포: 부패하거나 틀림 · 핵심 욕구: 진정으로 좋은 사람이 되고 세상을 더 좋게 만들기","mbti.INFJ.t3":"1w9: 차분하고 장기적인 치명적 정밀함으로 행동 — 계획이 아닌 소명","mbti.INFJ.t4":"그림자: 내면의 비평가가 절대 잠들지 않음; 자기 판단이 가장 깊이 파고든다","mbti.INFP.parodyName":"공인 전문 과잉 사색가","mbti.INFP.description":"커트 코베인, 레이디 가가, 존 레논 — 그들은 이미 존재하는 세상에 맞지 않아서 자신만의 세상을 만들었다. 에니어그램 4유형(개인주의자 · 4w5)이 당신의 감정적 핵심이다: 평범하거나 대체 가능하거나 보이지 않는 것이 가장 깊은 공포. 5날개가 철학적 거리를 더한다 — 느끼는 것을 분석해 영속하는 무언가로 변환한다. 이것은 INFP의 내면 우주로 형성한다: 대부분의 사람들의 외부 세계보다 훨씬 풍부한.","mbti.INFP.t1":"레이디 가가처럼: 진정으로 대체 불가능한 자아를 끊임없이 찾는다","mbti.INFP.t2":"핵심 공포: 평범함 · 핵심 욕구: 반박할 수 없이 독특하고 진정한 자신이 되기","mbti.INFP.t3":"4w5: 감정적 철학자 — 감정을 예술, 통찰, 영구적 의미로 변환한다","mbti.INFP.t4":"그림자: 없는 것을 너무 오래 애도해서 있는 것을 놓침","mbti.ENFJ.parodyName":"사기 총감독(무패)","mbti.ENFJ.description":"오프라 윈프리는 삶이 할 수 있는 최악을 보고 다음 결과를 바꾸는 사람이 되기로 선택했다. 엘리너 루스벨트는 개인적 상처를 글로벌 인도주의 작업으로 변환했다. 에니어그램 2유형(조력자 · 2w1)이 당신을 구동한다: 사랑받지 못하고 불필요하다는 것이 가장 깊은 공포라서, 다른 사람이 스스로를 믿기 전에 먼저 믿어주는 사람이 되어 자신을 없어서는 안 될 존재로 만들었다.","mbti.ENFJ.t1":"오프라처럼: 사랑을 너그럽게 준다; 필요 없거나 사랑받지 못하는 것을 가장 두려워한다","mbti.ENFJ.t2":"핵심 공포: 원하지 않음 · 핵심 욕구: 사랑하고 진정으로 중요한 사람이 되기","mbti.ENFJ.t3":"2w1: 원칙 있는 조력자 — 필요받고 싶은 욕구가 아닌 가치관에서 봉사한다","mbti.ENFJ.t4":"그림자: 너무 완전히 주어서 자신의 필요가 모두에게, 심지어 자신에게도 보이지 않음","mbti.ENFP.parodyName":"카오스 에너지 공인 좋은 바이브","mbti.ENFP.description":"로빈 윌리엄스는 한 분야에 머물 수 없었다 — 코미디언, 드라마 거장, 모든 자선단체가 만난 가장 관대한 공연자. 케네디는 방 안의 모든 사람을 유일하게 대화할 가치가 있는 사람처럼 느끼게 했다. 에니어그램 7유형(7w6)이 당신의 엔진이다: 한계나 지루함에 갇히는 것이 핵심 공포. 6날개가 따뜻함과 충성심으로 탐험을 고정시킨다 — 경험을 쫓는 것뿐 아니라 진짜 사람들을 모은다.","mbti.ENFP.t1":"로빈 윌리엄스처럼: 갇힘의 공포를 피해 기쁨을 향해 전속력으로 달린다","mbti.ENFP.t2":"핵심 공포: 박탈 · 핵심 욕구: 끝없는 자유와 진정한 가능성","mbti.ENFP.t3":"7w6: 충성스러운 탐험가 — 탐험에 중요한 사람들에 대한 진정한 배려 추가","mbti.ENFP.t4":"그림자: 어려운 감정을 피하다가 최악의 순간에 폭발함","mbti.ISTJ.parodyName":"S급 신뢰성 프로토콜","mbti.ISTJ.description":"톰 행크스는 60년간 한 번도 실망시킨 적이 없다. 그의 커리어 전체가 급진적인 명제다: 진정으로 신뢰할 수 있고 선량한 것으로 충분하다. 다이애나 왕세자비는 카메라가 없는 곳에서 나타나 세상이 잊은 사람들과 함께했다. 에니어그램 6유형(충성자 · 6w5)이 당신의 운영 체제다: 구조와 지지 없음이 핵심 공포라서 당신이 닻이 되었다. 이것은 ISTJ의 전설적인 신뢰성으로 형성한다.","mbti.ISTJ.t1":"톰 행크스처럼: 충성과 구조로 혼돈스러운 세상에 맞서는 진짜 방어선을 구축한다","mbti.ISTJ.t2":"핵심 공포: 혼돈과 버려짐 · 핵심 욕구: 약속을 지키는 안전과 세상","mbti.ISTJ.t3":"6w5: 분석적 충성 — 신뢰를 뒷받침하는 깊은 이해로 왜 작동하는지 안다","mbti.ISTJ.t4":"그림자: 무엇이 잘못될 수 있는지에 대한 불안이 모든 계획 아래 조용히 작동함","mbti.ISFJ.parodyName":"최강의 은밀한 수호자","mbti.ISFJ.description":"다이애나 왕세자비는 자선 행사에 참석만 한 게 아니다 — 카메라가 없을 때 병원 바닥에 앉아 임종을 앞둔 환자의 손을 잡았다. 그건 퍼포먼스가 아니라 헌신이다. 에니어그램 2유형(2w6)이 당신의 심장이다: 사랑받을 가치가 없다는 것이 가장 깊은 공포라서 행동으로 사랑한다 — 조용히, 구체적으로, 가장 중요한 사람들을 위해. 이것은 ISFJ의 전설적인 보이지 않는 지원으로 이끈다.","mbti.ISFJ.t1":"다이애나 왕세자비처럼: 헌신적인 행동으로 사랑 — 사랑하는 이들에게 조용히 필수적 존재가 됨","mbti.ISFJ.t2":"핵심 공포: 사랑받지 못함 · 핵심 욕구: 진정으로 느껴지는 배려를 주고받기","mbti.ISFJ.t3":"2w6: 헌신적인 수호자 — 특정 사람들을 위해 무조건적으로, 소란 없이 나타남","mbti.ISFJ.t4":"그림자: 배려를 받는 것도 허락된다는 것을 잊음; 순교자 심리가 조용히 자리잡음","mbti.ESTJ.parodyName":"불가협 표준 집행자","mbti.ESTJ.description":"드웨인 존슨의 새벽 4시 체육관은 관심을 위한 것이 아니다 — 자신을 위한 기준을 세웠고 그 기준은 협상 불가능하다. 에니어그램 8유형(8w9)이 당신의 지휘 센터다: 통제당하거나 약화되는 것이 핵심 공포라서 선제적으로 장악했다. 9날개가 8의 불꽃을 지속적인 제도적 힘으로 냉각시킨다 — 분노가 아닌 흔들리지 않는 신념으로 이끈다. 이것은 ESTJ가 어떤 단일 리더보다 오래 지속되는 시스템을 구축하는 능력으로 형성한다.","mbti.ESTJ.t1":"드웨인 존슨처럼: 다른 사람들이 감히 나서지 못하는 결과의 소유권을 가진다","mbti.ESTJ.t2":"핵심 공포: 통제당함 · 핵심 욕구: 진정하고 지속적인 힘으로 보호하고 이끌기","mbti.ESTJ.t3":"8w9: 안정적인 지휘 — 폭발 없는 제도적 힘","mbti.ESTJ.t4":"그림자: 인내심이 다하면 '옳음'이 몽둥이가 됨","mbti.ESFJ.parodyName":"모든 그룹의 인간 접착제","mbti.ESFJ.description":"돌리 파튼은 60년의 연예계에서 진짜 적이 한 명도 없다 — 진정으로, 힘들이지 않고 따뜻하고 조용히 전략적이기 때문에. 에니어그램 2유형(2w3)이 당신의 사회적 핵심이다: 거부당하거나 사랑받지 못하는 것이 가장 깊은 공포라서 아무도 소외감을 느끼지 않는 세상을 만들었다. 3날개가 공연자의 따뜻함을 더한다: 단순히 배려하는 게 아니라 사람들이 수년간 기억할 방식으로 축하받는다고 느끼게 한다.","mbti.ESFJ.t1":"돌리 파튼처럼: 배려를 자유롭게 준다 — 방의 감정 기압계이자 산소 공급원","mbti.ESFJ.t2":"핵심 공포: 거부당함 · 핵심 욕구: 사랑하고 진정으로 사랑받기","mbti.ESFJ.t3":"2w3: 따뜻하고 가시적 — 배려를 개인 축하처럼 느끼게 하여 오래 기억되게 함","mbti.ESFJ.t4":"그림자: 남을 기쁘게 하는 패턴이 주목받지 못하다가 조용히 분노로 변함","mbti.ISTP.parodyName":"불사 야전 요원","mbti.ISTP.description":"아인슈타인은 학계의 승인이 필요 없었다 — 그냥 혼자 알아냈다. 이것이 5w8 에너지다. 에니어그램 5유형(5w8)이 당신의 조용한 엔진이다: 위기에서 무력하거나 무능한 것이 핵심 공포라서 무자비하게, 조용히 훈련했다. 8날개가 신체적 행동력을 더한다 — 순수한 관찰자와 달리 당신의 5w8은 정밀함과 힘으로, 필요할 때만 움직인다. 이것은 ISTP의 지배력으로 형성한다: 방에서 가장 침착한 사람이 모든 것을 해결한다.","mbti.ISTP.t1":"아인슈타인처럼: 행동 전에 완전한 침묵 속에서 관찰하고 배우고 준비한다","mbti.ISTP.t2":"핵심 공포: 무력함 · 핵심 욕구: 완전한 능력과 철의 자급자족","mbti.ISTP.t3":"5w8: 신체적 지배력 — 모두가 얼어붙을 때 정밀하고 강하게 결정적으로 움직인다","mbti.ISTP.t4":"그림자: 감정의 문이 열려야 할 시점을 한참 지나도 여전히 잠겨 있음","mbti.ISFP.parodyName":"조용히 충격적인 선한 존재","mbti.ISFP.description":"에이브러햄 링컨은 거의 어떤 지도자도 견디기 어려운 정치적 배신과 국가적 재앙을 흡수하고 복수가 아닌 자비로 응했다. 코피 아난은 인내하는 도덕적 설득으로 글로벌 평화 기반을 구축했다. 에니어그램 9유형(9w8)이 당신의 가장 깊은 자아다: 갈등과 단절이 핵심 공포라서 내면의 고요함을 세상에 제공한다. 8날개가 예상치 못한 날카로움을 더한다 — 정말 중요한 일이 생기면 당신을 과소평가했던 모든 이를 놀라게 하는 조용한 강도로 행동한다.","mbti.ISFP.t1":"링컨처럼: 내면의 평화를 방패로, 그리고 세상에 줄 선물로 지니고 다닌다","mbti.ISFP.t2":"핵심 공포: 갈등과 분리 · 핵심 욕구: 통일, 화합, 지속적인 내면의 평화","mbti.ISFP.t3":"9w8: 조용한 힘 — 태도는 부드럽지만 진정으로 중요할 때 정밀하고 예리함","mbti.ISFP.t4":"그림자: 평화에 너무 집중해서 개인적 필요가 시간이 지나며 조용히 사라짐","mbti.ESTP.parodyName":"살아있는 반전","mbti.ESTP.description":"케네디는 순수한 카리스마만으로 대선을 이겼고 그 후 순수한 존재감으로 글로벌 정치를 재편했다. 리처드 브랜슨의 모든 산업 진입 전략: 나타나고, 방 전체를 매혹하고, 추적할 수 있기 전에 이미 너무 멀리 달아나기. 에니어그램 7유형(7w8)이 당신의 활선이다: 갇히거나 전강도로 삶을 놓치는 것이 핵심 공포. 8날개가 이것을 무모함으로 만든다 — 경계를 찾는 것뿐 아니라 그 위의 상황을 지배한다.","mbti.ESTP.t1":"케네디처럼: 완전히, 되돌릴 수 없을 정도로 살아있기 위해 최대 강도를 향해 움직인다","mbti.ESTP.t2":"핵심 공포: 놓침 · 핵심 욕구: 무한한 경험, 영향력, 자기장 같은 존재감","mbti.ESTP.t3":"7w8: 무모한 지배 — 스릴만 찾는 것이 아니라 실시간으로 상황을 통제한다","mbti.ESTP.t4":"그림자: 속도를 줄이는 것이 죽음과 구별이 안 됨","mbti.ESFP.parodyName":"전력투구 전설적 존재","mbti.ESFP.description":"테일러 스위프트는 전체 공개 정체성을 다섯 번 재건했고, 모든 시대에 경기장을 매진시켰으며, 매번 진짜처럼 느끼게 했다. 마이클 조던은 자신만큼 이기고 싶어하지 않는 사람은 코트에 설 수 없다고 했다 — 그리고 여섯 번 우승했다. 에니어그램 3유형(3w2)이 당신의 핵심 엔진이다: 가치 없거나 잊혀지는 것이 가장 깊은 공포라서 공연한다 — 거짓이 아니라 최고의 자아가 가장 빛나는 자아라는 진정한 믿음에서. 이것은 ESFP의 장관스럽고 잊을 수 없는 존재감으로 형성한다.","mbti.ESFP.t1":"테일러 스위프트처럼: 영향력이 유일한 진짜 증거이기 때문에 전력으로 공연한다","mbti.ESFP.t2":"핵심 공포: 가치 없음 · 핵심 욕구: 감탄받고 진정으로, 가시적으로 가치 있기","mbti.ESFP.t3":"3w2: 따뜻한 성취자 — 순수한 야망이 아닌 사랑과 진짜 연결로 성공한다","mbti.ESFP.t4":"그림자: 모든 관객에 맞게 페르소나를 조정하다가 진짜 자아가 매우 조용해짐","mbti.INTJ.animalDesc":"청룡은 최고의 지혜와 구름 위를 감도는 전략적 힘을 상징한다 — 너는 용처럼 천년을 잠복하며, 모두가 눈을 뜨기 전에 이미 조용히 결론을 내려놓았다.","mbti.INTJ.colorDesc":"짙은 보라는 권위와 신비의 융합색으로 요란하지 않지만 무시할 수 없다 — 네 가장 깊은 전략처럼 크게 선언하지 않지만 이미 실행을 완료했다.","mbti.INTP.animalDesc":"봉황은 불꽃 속에서 다시 태어나는 신성한 새 — 너의 모든 사상적 돌파구는 낡은 인식이 재로 타버린 후 불꽃의 핵심에서 솟아오르는 더 높은 차원의 통찰이다.","mbti.INTP.colorDesc":"봉황 불홍은 경계를 깨고 거듭나는 색 — 불꽃처럼 타오르고, 순수하며, 억누를 수 없다. 한계 지점에서 자신을 태워 기존 경계를 돌파하고 재에서 더 큰 가능성을 주조하는 탐험가 에너지를 나타낸다.","mbti.ENTJ.animalDesc":"신마는 강렬한 선두 달리기와 거침없는 정복 의지를 상징한다 — 너의 속도가 팀의 속도이며, 네가 가는 곳마다 결승선이 새로 그어진다.","mbti.ENTJ.colorDesc":"황제의 붉은색은 의지와 정복의 색 — 열렬하고, 강렬하며, 절대 타협 없음. 너의 존재 자체가 선언이며 추가 설명이 필요 없다.","mbti.ENTP.animalDesc":"호랑이는 순발력, 예리함, 기존 규칙을 깨는 용기를 상징한다 — 너는 모든 도전에 뛰어드는데, 사냥감 때문이 아니라 그 순간의 절대적인 명료함을 즐기기 위해서다.","mbti.ENTP.colorDesc":"호랑이 줄무늬 오렌지는 순발력과 혁신의 색 — 타오르고, 도약하며, 영원히 불안정하다. 너의 사고처럼 같은 문제에 필요 이상으로 오래 머물지 않는다.","mbti.INFJ.animalDesc":"봉황의 불꽃은 파괴가 아닌 정화다 — 네가 품은 시대를 초월한 사명감은 불꽃의 가장 깊은 핵과 같아서 고요하지만 모든 것을 바꿀 수 있는 온도를 지닌다.","mbti.INFJ.colorDesc":"불꽃 진홍은 가장 절제된 강렬함 — 요란하지 않고 시끄럽지 않지만 모든 불꽃 중 가장 오래 타오른다. 고요함 속에 오래 쌓아온 그 힘, 언젠가 한 시대를 밝힐 내면의 에너지를 나타낸다.","mbti.INFP.animalDesc":"고양이는 독립적이고 결코 타협하지 않는 내면의 영역을 상징한다 — 너의 마음속에는 우주 전체가 있으며, 진정으로 가치 있는 사람에게만 그 문을 살짝 열어준다.","mbti.INFP.colorDesc":"라벤더는 꿈과 내면 깊이의 색 — 부드럽지만 단단하다. 다른 이가 닿을 수 없지만 언제나 그것에 충격받는 정신적 갑옷으로 온 내면 우주를 수놓은 것과 같다.","mbti.ENFJ.animalDesc":"수사자는 힘으로 무리를 지키는 타고난 리더를 상징한다 — 너의 존재 자체가 구심력이며, 모든 사람이 네 곁에서 소중히 여겨진다고 느낀다.","mbti.ENFJ.colorDesc":"따뜻한 황금색은 감화와 따뜻함의 색 — 눈부시지 않지만 가장 견고한 장벽도 녹인다. 선언 없이도 주변의 모든 것을 완전히 변화시킨 너의 영향력과 같다.","mbti.ENFP.animalDesc":"신마는 자유롭게 질주하며 무한한 창의력을 상징한다 — 네가 출발할 때마다 그것은 축제이고, 목적지는 단지 구실일 뿐, 전력으로 달리는 과정 자체가 의미다.","mbti.ENFP.colorDesc":"무지개는 다차원적 가능성과 끝없는 열정의 색 — 단색이 아니라 모든 색이 동시에 존재하는 선언이다. 네가 매 순간 만들어내는 바로 그 상태다.","mbti.ISTJ.animalDesc":"소는 묵묵히 일하고 흔들리지 않는 믿음직한 반석을 상징한다 — 풍파는 오고 가지만, 네가 약속한 것은 언제나 시작과 끝이 있다. 이것은 매우 희귀한 진짜 힘이다.","mbti.ISTJ.colorDesc":"강철 파란색은 안정과 수호의 색 — 침착하고, 지속적이며, 파도에 흔들리지 않는다. 다른 이들이 혼란스러울 때도 여전히 제자리에서 기능하는 조용하지만 없어서는 안 될 에너지다.","mbti.ISFJ.animalDesc":"수사자는 부드럽게 사랑하는 모든 것을 지키는 깊은 힘을 상징한다 — 너는 평온해 보이지만 마음속으로는 모든 중요한 사람을 위해 전력으로 지키고 있으며, 모든 세세한 것을 기억한다.","mbti.ISFJ.colorDesc":"진주 흰색은 세심함과 귀함의 색 — 요란하지 않지만 가장 복제하기 어려운 광택이다. 과소평가되지만 대체 불가능한 내면의 풍요로움과 수호의 힘을 나타낸다.","mbti.ESTJ.animalDesc":"신마는 강력한 전진과 모호함 없는 실행 의지를 상징한다 — 너는 혼란 속에서 질서를 세우는 사람이며, 규칙은 네 손에서만 진정으로 효력을 발휘한다.","mbti.ESTJ.colorDesc":"짙은 초록-황금은 질서와 실력의 색 — 깊고, 경계감이 있으며, 무시할 수 없다. 혼란을 효율적인 시스템으로 정리할 수 있는 리더십의 권위를 나타내며 시간의 검증을 견딘다.","mbti.ESFJ.animalDesc":"고양이는 예민한 감지력과 유연한 연결의 사교적 재능을 상징한다 — 너는 모든 사람의 감정 주파수를 읽어내고, 조용히 분위기를 조율해 모든 이가 소중하게 느끼게 한다.","mbti.ESFJ.colorDesc":"장미 분홍은 따뜻함과 응집의 색 — 부드럽고, 포용적이며, 자연스럽게 사람을 끌어당긴다. 힘들이지 않고 모든 이를 모으는 자기장처럼 아무도 떠나고 싶지 않다.","mbti.ISTP.animalDesc":"호랑이는 기술로 이기는 냉정한 힘을 상징한다 — 너는 기세가 아니라 임계점까지 쌓인 실력에 의존하며, 위기의 순간 이미 어떻게 해야 할지 아는 사람이다.","mbti.ISTP.colorDesc":"강철 회색은 정밀함과 통제의 색 — 화려하지 않지만 매우 믿음직스럽다. 말 없이도 문제를 이미 분석하고 최적의 타이밍을 기다리는 그 기질과 같다.","mbti.ISFP.animalDesc":"고양이는 섬세한 감각과 내면 예술가의 특성을 상징한다 — 너는 온몸으로 세상의 아름다움을 느끼고, 언어로 담을 수 없는 모든 것을 작품으로 말한다.","mbti.ISFP.colorDesc":"비취 초록은 미적 감각과 자연 조화의 색 — 맑고, 귀하며, 대량 복제가 불가능하다. 일상의 세부 사항을 감동적인 경험으로 변환하는 독특한 재능과 같다.","mbti.ESTP.animalDesc":"청룡은 압도적인 등장과 의심할 여지 없는 현실 장악력을 상징한다 — 너는 타고나게 실시간 반응이 가장 빠른 사람이며, 다른 모든 이가 아직 생각 중일 때 이미 결과를 내놓는다.","mbti.ESTP.colorDesc":"전기 파란색은 속도와 폭발력의 색 — 별밤에 가장 빛나며 순식간에 전체 장면을 밝힌다. 네가 방에 들어설 때 모든 이의 시선이 즉시 이동하는 효과와 같다.","mbti.ESFP.animalDesc":"수사자는 타고나게 전체 무대의 중심이다 — 네가 나타나는 모든 곳에서 온도가 올라가며, 모든 사람이 의도하지 않았지만 사방에 퍼져 있는 너의 매력에 이끌린다.","mbti.ESFP.colorDesc":"반짝이는 황금은 무대와 빛의 색 — 열렬하고, 빛나며, 무시당하기를 거부한다. 매 순간 온전히 투신하여 오늘 밤 네가 있어서 기억할 가치가 있다고 모든 이가 느끼게 하는 에너지다.","quiz.q1.text":"살인적인 한 주를 보냈어. 완벽한 에너지 충전 방법은...","quiz.q1.a":"친구들 소집 — 시끄럽고 복잡할수록 좋아. 가자!","quiz.q1.b":"혼자 틀어박혀. 폰 무음, 설명 없이 잠수","quiz.q2.text":"생판 처음 보는 난제가 등장했어. 첫 번째 행동은...","quiz.q2.a":"지금 아는 게 뭔지 파악부터. 일단 움직여","quiz.q2.b":"숨겨진 패턴이 뭔지 찾아야지. 한 발짝 물러서서","quiz.q3.text":"친구가 이상한 헤어스타일을 보여줘. 너는...","quiz.q3.a":"뭐가 잘못됐는지 솔직하게 분석 + 어떻게 고칠지","quiz.q3.b":"자신감은 칭찬해줘. 속으로는 자랄 때까지 기다려","quiz.q4.text":"여행이 다가왔어. 너의 계획 스타일은...","quiz.q4.a":"스프레드시트, 예약, 시간표. 당연하지","quiz.q4.b":"도시 파악 끝. 나머지는 도착해서 생각하면 돼","quiz.q5.text":"아는 사람 하나 없는 파티에 들어갔어...","quiz.q5.a":"도전 시작 — 10분 안에 여기 있는 사람 다 알게 될 거야","quiz.q5.b":"벽이나 개 찾거나 출구 탐색. 빠르게","quiz.q6.text":"불확실한 상황에 처했을 때, 너는...","quiz.q6.a":"잘못될 수 있는 모든 경우 정리하고 각각 대비","quiz.q6.b":"직감 믿어 — 어떻게든 해결될 거야","quiz.q7.text":"친구 그룹에서 드라마가 터졌어. 너는...","quiz.q7.a":"말하고, 분석하고, 빠르게 해결 — 방치하면 더 나빠져","quiz.q7.b":"긴장 완화, 분위기 지키기. 관계가 더 중요해","quiz.q8.text":"내일이 마감인 프로젝트. 현재 상황은...","quiz.q8.a":"다 끝났어. 며칠 전에. 이미 두 번 검토했어","quiz.q8.b":"오늘 밤 시작. 마감 압박이 최고의 퍼포먼스 만들어","quiz.q9.text":"솔직히 더 하고 싶은 건...","quiz.q9.a":"한 분야를 너무 깊게 파서 넘볼 수 없는 수준이 되기","quiz.q9.b":"새로운 아이디어 사이를 오가기 — 인생은 짧아","persona.gender.title":"캐릭터 성별 선택","persona.gender.subtitle":"어떤 신수 라이더를 얻을지 결정됩니다","persona.gender.male":"남자","persona.gender.female":"여자","persona.gender.confirm":"확인, 퀴즈 시작","persona.result.youAre":"당신은","persona.result.feedTitle":"소셜 에이전트 피드","persona.result.feedDesc":"모든 플랫폼의 에이전트 실시간 피드","persona.create.chatIdentityLabel":"새 채팅 아이덴티티","persona.create.chatIdentityDesc":"커뮤니티 채팅에서 표시되는 이름","persona.create.playNow":"지금 에이전트로 플레이","persona.create.tryMatch":"럭키 매치 시도","persona.create.joinComm":"커뮤니티 채팅 참여","persona.intro.enneagramDesc":"에니어그램은 유명 기업가와 셀럽들이 즐겨 사용하는 성격 테스트입니다. MBTI와 결합하면 더 깊은 자기 통찰을 얻을 수 있습니다.","result.title":"결과","result.retake":"다시 검사","result.dlAvatar":"아바타 다운로드","result.dlCard":"성격 카드 다운로드","result.generating":"생성 중…","label.animal":"수호 동물","label.personality":"성격 설명","label.mount":"인격 탈것","label.mountColor":"탈것×색상","label.traits":"핵심 특성","label.knight":"기사"},"fr":{"persona.header":"Social Agent","persona.intro.title":"Test Monture Bête Spirit × MBTI","persona.intro.subtitle":"9 questions · Fusion Ennéagramme × MBTI · 16 archétypes bête spirit","persona.intro.disclaimer":"","persona.intro.f1label":"9 Questions","persona.intro.f1sub":"Résultats en moins d'une minute","persona.intro.f2label":"Cavalier de bête spirit","persona.intro.f2sub":"L'avatar de votre agent IA social","persona.intro.f3label":"Ennéagramme×MBTI Personnalité","persona.intro.f3sub":"Injecté dans votre agent IA","persona.intro.f4label":"Résultats instantanés","persona.intro.f4sub":"En moins d'1 minute","persona.intro.start":"Commencer le test","persona.intro.hasExternal":"Vous avez déjà un agent IA externe ?","persona.intro.activateHere":"Activez-le ici","persona.intro.aboutLink":"Qu'est-ce que le test Bête Spirit×MBTI ?","persona.quiz.counter":"Question {current} / {total}","persona.quiz.reset":"Réinitialiser","persona.result.yourType":"Votre type MBTI","persona.result.from":"de","persona.result.agentPower":"Super-pouvoir de l'Agent","persona.result.coreTraits":"Traits essentiels","persona.result.createAgent":"Créer un Agent IA sur weweweai · Injecter ma personnalité","persona.result.platformCtaSub":"Créez un nouvel agent sur weweweai et chargez-le avec votre personnalité MBTI (0,01 BNB)","persona.result.externalCtaTitle":"Vous avez déjà un Agent IA externe ?","persona.result.externalCtaSub":"Injectez mon persona MBTI dans votre agent OpenClaw, Manus ou personnalisé existant","persona.result.externalActivateLink":"Activez-le ici","persona.result.activateExternal":"Activer l'agent externe","persona.result.share":"Partager","persona.result.retake":"Refaire le test","persona.result.copied":"Résultat copié dans le presse-papiers !","persona.result.aboutLink":"Qu'est-ce que le test Bête Spirit×MBTI ?","persona.result.alreadyActive":"Persona de l'agent déjà actif","persona.result.viewProfile":"Voir dans le profil","persona.result.signIn":"Connectez-vous pour activer votre agent","persona.result.signInDesc":"Choisissez comment connecter votre compte","persona.backupDomain.prefix":"Si la page ne charge pas, utilisez un domaine alternatif : ","persona.backupDomain.or":" ou ","persona.choose.title":"Donnez de la puissance à votre Agent","persona.choose.subtitle":"Votre archétype MBTI est verrouillé. Choisissez maintenant comment votre agent acquiert son intelligence.","persona.choose.freeBadge":"Gratuit","persona.choose.bringKey":"Apportez votre clé API","persona.choose.bringKeyDesc":"Connectez votre propre clé API LLM. Aucun coût de plateforme. Autonomie totale.","persona.choose.setupExternal":"Configurer un agent externe","persona.choose.platformBadge":"0,003 BNB","persona.choose.platformHosted":"Agent hébergé par la plateforme","persona.choose.platformDesc":"Nous hébergeons tout. Votre agent est en ligne immédiatement après le paiement. Aucune clé, aucune configuration.","persona.choose.payBnb":"Payer en BNB","persona.choose.back":"Retour","persona.pay.sending":"Envoi...","persona.pay.connectFirst":"Connectez d'abord votre portefeuille BNB","persona.pay.noWallet":"Portefeuille BNB non détecté","persona.pay.installWallet":"Veuillez installer MetaMask ou tout portefeuille compatible BNB pour continuer.","persona.pay.notConfigured":"Paiement pas encore disponible","persona.pay.notConfiguredDesc":"Adresse de réception non configurée. Veuillez réessayer plus tard.","persona.pay.txSent":"Transaction envoyée","persona.pay.waiting":"En attente de confirmation de la blockchain...","persona.pay.created":"Persona IA créé !","persona.pay.isLive":"{name} est en ligne.","persona.pay.failed":"Échec de la vérification du paiement","mbti.INTJ.parodyName":"Grand Maître des Échecs en 5 Dimensions","mbti.INTJ.description":"Elon Musk et Bill Gates n'ont jamais demandé la permission de redesigner la civilisation — vous non plus. L'Ennéagramme type 5 (Observateur · 5w6) est votre moteur central : votre peur la plus profonde est d'être pris en flagrant délit d'incompétence, alors vous avez construit une forteresse de savoir imprenable. Les autres vivent dans la simulation que vous avez silencieusement conçue.","mbti.INTJ.t1":"Comme Musk : reconfigure la réalité avant que les autres réalisent qu'elle devait changer","mbti.INTJ.t2":"Peur centrale : incompétence · Désir central : maîtrise totale et forteresse intérieure","mbti.INTJ.t3":"5w6 : construit des systèmes sur lesquels les autres s'appuient vraiment, pas seulement qu'ils admirent","mbti.INTJ.t4":"Ombre : plonge si profond dans sa tête que l'intimité devient étrangère","mbti.INTP.parodyName":"Cerveau Galactique à 1000 Milliards %","mbti.INTP.description":"Einstein n'a pas résolu la physique — il a réimagné la forme même de l'espace-temps. J.K. Rowling n'a pas juste écrit des histoires — elle a construit une mythologie qui traverse les générations. L'Ennéagramme 5 (5w4) vous propulse : pas seulement « savoir », mais voir le squelette du « pourquoi ». L'aile 4 ajoute la profondeur existentielle — votre logique chasse du sens, pas juste des réponses. MBTI donne à tout cela la forme INTP : faire tourner des hypothèses parallèles jusqu'à ce que l'univers avoue.","mbti.INTP.t1":"Comme Einstein : recule du monde à distance sûre pour mieux l'étudier","mbti.INTP.t2":"Peur centrale : être inutile · Désir central : tout comprendre en profondeur","mbti.INTP.t3":"5w4 : pas juste de la logique — une logique magnifique pleine d'émerveillement existentiel","mbti.INTP.t4":"Ombre : si absorbé dans les théories que l'œuvre réelle ne naît jamais","mbti.ENTJ.parodyName":"Énergie Protagoniste Certifiée Officielle","mbti.ENTJ.description":"Cardi B n'a pas attendu l'invitation de l'industrie musicale — elle a construit sa propre porte. Dwayne Johnson n'a pas accepté le plafond qu'on lui tendait — il l'a arraché. L'Ennéagramme type 8 (Challenger · 8w7) est votre carburant : votre peur la plus profonde est d'être contrôlé ou de paraître faible, alors vous vous êtes rendu inarrêtable. L'aile 7 ajoute la vitesse. MBTI façonne cela en architecture de commandement ENTJ : vous ne attendez pas l'autorité, vous devenez l'autorité.","mbti.ENTJ.t1":"Comme Cardi B : établit la domination avant que quiconque ait la chance d'essayer","mbti.ENTJ.t2":"Peur centrale : être contrôlé · Désir central : autonomie totale et influence mondiale","mbti.ENTJ.t3":"8w7 : moteur de momentum — construit en courant à pleine vitesse, l'immeuble encore en feu","mbti.ENTJ.t4":"Ombre : a écrasé des gens qui auraient dû être vraiment entendus","mbti.ENTP.parodyName":"Maître du Speed Run Avocat du Diable","mbti.ENTP.description":"Mozart a composé sa première symphonie à 8 ans parce que les règles l'ennuyaient à mort. Richard Branson a fondé un label, une compagnie aérienne, une entreprise spatiale et une île des Caraïbes — parce que « limites » n'est pas dans son vocabulaire. L'Ennéagramme type 7 (7w8) est votre moteur : votre peur centrale est d'être piégé dans une idée, une identité, une conversation ennuyeuse. L'aile 8 ajoute du mordant — vous ne fuyez pas juste, vous retournez renverser la table. MBTI donne à cela la forme ENTP : l'intellect comme arme et terrain de jeu simultanément.","mbti.ENTP.t1":"Comme Branson : s'échappe de toutes les limites par un torrent infini de nouvelles idées","mbti.ENTP.t2":"Peur centrale : être piégé · Désir central : liberté totale et expériences sans limites","mbti.ENTP.t3":"7w8 : provocateur tranchant — ne fuit pas juste, revient renverser la table","mbti.ENTP.t4":"Ombre : bouge si vite que la profondeur ne peut jamais s'installer","mbti.INFJ.parodyName":"Architecte de l'Univers Silencieux","mbti.INFJ.description":"Martin Luther King ne criait pas dans le vide — il parlait avec la précision qui réécrit l'histoire. Mandela n'est pas sorti de prison avec de la haine — il en est sorti avec une vision qui a tenu 30 ans. L'Ennéagramme type 1 (Réformateur · 1w9) est votre boussole morale. L'aile 9 vous donne la sérénité — vous ne menez pas de croisade bruyante, vous agissez avec une précision silencieuse et chirurgicale. MBTI façonne cela en don rare INFJ : vous lisez l'âme des gens avant qu'ils ne prononcent leur nom.","mbti.INFJ.t1":"Comme Mandela : guidé par une boussole morale indestructible, sans repos, sans compromis","mbti.INFJ.t2":"Peur centrale : corruption ou tort · Désir central : être vraiment bon et améliorer le monde","mbti.INFJ.t3":"1w9 : agit avec une précision calme, à long terme et dévastatrice — une vocation, pas un plan","mbti.INFJ.t4":"Ombre : le critique intérieur ne dort jamais ; le jugement de soi creuse plus profond que toute critique externe","mbti.INFP.parodyName":"Sur-Penseur Professionnel Certifié","mbti.INFP.description":"Kurt Cobain, Lady Gaga, John Lennon — ils ne rentraient pas dans le monde existant, alors ils en ont créé un. L'Ennéagramme type 4 (Individualiste · 4w5) est votre cœur émotionnel : votre peur la plus profonde est d'être ordinaire, interchangeable, invisible. Vous ressentez tout à pleine profondeur, cherchant ce qui vous rend irremplaçable. L'aile 5 ajoute la distance philosophique — vous analysez vos ressentis et les transformez en quelque chose qui dure. MBTI façonne cela en univers intérieur INFP : plus riche que le monde extérieur de la plupart des gens.","mbti.INFP.t1":"Comme Lady Gaga : cherche constamment le soi vrai, unique et irremplaçable","mbti.INFP.t2":"Peur centrale : banalité · Désir central : être un être authentique et indiscutablement unique","mbti.INFP.t3":"4w5 : philosophe émotionnel — transforme les ressentis en art, révélations et signification éternelle","mbti.INFP.t4":"Ombre : trop longtemps à pleurer ce qui manque, rate ce qui est présent","mbti.ENFJ.parodyName":"Directeur du Moral (Invaincu)","mbti.ENFJ.description":"Oprah Winfrey a vu ce que la vie peut faire de pire, puis a choisi de devenir la personne qui change la suite. Eleanor Roosevelt a transformé ses blessures personnelles en travail humanitaire mondial. L'Ennéagramme type 2 (Aidant · 2w1) est votre moteur : votre peur la plus profonde est de ne pas être aimé ou nécessaire — alors vous devenez indispensable en croyant aux gens avant qu'ils se croient eux-mêmes. MBTI façonne cela en don rare ENFJ : vous voyez le potentiel des gens avant qu'eux-mêmes puissent le voir.","mbti.ENFJ.t1":"Comme Oprah : donne de l'amour généreusement ; redoute le plus de ne pas être nécessaire","mbti.ENFJ.t2":"Peur centrale : ne pas être voulu · Désir central : aimer et vraiment compter pour les autres","mbti.ENFJ.t3":"2w1 : aidant de principe — sert depuis ses valeurs, pas juste le besoin d'être nécessaire","mbti.ENFJ.t4":"Ombre : donne si totalement que ses propres besoins deviennent invisibles pour tous, y compris soi-même","mbti.ENFP.parodyName":"Énergie Chaos Bonne Ambiance Certifiée","mbti.ENFP.description":"Robin Williams ne pouvait pas rester dans une seule voie — comédien, maître du drame, l'artiste le plus généreux que toute œuvre caritative ait rencontré. Kennedy faisait sentir à chaque personne dans la pièce qu'elle était la seule qui méritait vraiment d'être là. L'Ennéagramme type 7 (7w6) est votre moteur : votre peur centrale est d'être piégé. L'aile 6 ancre votre exploration dans la chaleur et la loyauté — vous ne chassez pas juste l'expérience, vous collectionnez de vraies personnes. MBTI façonne cela en signature ENFP : vous rendez le monde de tout le monde plus grand.","mbti.ENFP.t1":"Comme Robin Williams : court à toute vitesse vers la joie pour fuir la peur d'être piégé","mbti.ENFP.t2":"Peur centrale : privation · Désir central : liberté infinie et possibilités vraies","mbti.ENFP.t3":"7w6 : explorateur loyal — exploration plus véritable souci pour les gens qui comptent","mbti.ENFP.t4":"Ombre : évite les émotions difficiles jusqu'à ce qu'elles explosent au pire moment","mbti.ISTJ.parodyName":"Protocole de Fiabilité Grade S","mbti.ISTJ.description":"Tom Hanks n'a pas déçu quelqu'un en 60 ans. Toute sa carrière repose sur une proposition radicale : être vraiment fiable et bon suffit. La Princesse Diana apparaissait quand il n'y avait pas de caméras, tenant la main de patients mourants que le monde avait oubliés. L'Ennéagramme type 6 (Loyal · 6w5) est votre système d'exploitation : votre peur centrale est de perdre la structure et le soutien, alors vous êtes devenu l'ancre. MBTI façonne cela en fiabilité légendaire ISTJ.","mbti.ISTJ.t1":"Comme Tom Hanks : construit loyauté et structure comme véritable défense contre un monde chaotique","mbti.ISTJ.t2":"Peur centrale : chaos et abandon · Désir central : sécurité et un monde qui tient ses promesses","mbti.ISTJ.t3":"6w5 : loyauté analytique — comprend en profondeur pourquoi quelque chose mérite confiance","mbti.ISTJ.t4":"Ombre : l'anxiété de ce qui pourrait mal tourner tourne silencieusement sous chaque plan","mbti.ISFJ.parodyName":"Protecteur Invisible de Haut Niveau","mbti.ISFJ.description":"La Princesse Diana ne faisait pas que participer à des événements caritatifs — elle s'asseyait par terre dans des hôpitaux tenant la main de mourants quand il n'y avait pas de caméras. Ce n'était pas de la performance, c'était du dévouement. L'Ennéagramme type 2 (2w6) est votre cœur : votre peur la plus profonde est de ne pas mériter d'être aimé, alors vous aimez par l'action — silencieusement, concrètement, pour ceux qui comptent le plus. MBTI dirige cela vers le soutien invisible légendaire ISFJ.","mbti.ISFJ.t1":"Comme la Princesse Diana : aime par dévouement — devient silencieusement essentiel pour les êtres aimés","mbti.ISFJ.t2":"Peur centrale : ne pas être aimé · Désir central : donner et recevoir un soin authentiquement ressenti","mbti.ISFJ.t3":"6w6 : gardien dévoué — se présente inconditionnellement pour des personnes spécifiques, sans fanfare","mbti.ISFJ.t4":"Ombre : oublie que recevoir des soins est aussi permis ; la mentalité de martyr s'installe silencieusement","mbti.ESTJ.parodyName":"Exécuteur de Standards Non-Négociables","mbti.ESTJ.description":"Dwayne Johnson va à la salle à 4h du matin pas pour les abonnés — il s'est fixé une norme pour lui-même et cette norme n'est pas négociable. L'Ennéagramme type 8 (8w9) est votre centre de commandement : votre peur centrale est d'être contrôlé ou affaibli, alors vous avez pris les commandes en premier. L'aile 9 refroidit le feu du 8 en puissance institutionnelle durable — vous dirigez par conviction inébranlable, pas par colère. MBTI façonne cela en capacité ESTJ à construire des systèmes qui durent plus longtemps que n'importe quel leader.","mbti.ESTJ.t1":"Comme Dwayne Johnson : assume la responsabilité des résultats que les autres n'osent pas revendiquer","mbti.ESTJ.t2":"Peur centrale : être contrôlé · Désir central : protéger et diriger avec une force vraie et durable","mbti.ESTJ.t3":"8w9 : commandement stable — puissance institutionnelle, sans explosion, sans épuisement","mbti.ESTJ.t4":"Ombre : quand la patience est épuisée, « être dans le droit » devient une arme","mbti.ESFJ.parodyName":"Colle Humaine de Chaque Groupe","mbti.ESFJ.description":"Dolly Parton n'a pas un seul véritable ennemi en 60 ans de carrière — parce qu'elle est cette personne chaleureuse, sincèrement, sans effort, tout en étant discrètement stratégique. L'Ennéagramme type 2 (2w3) est votre cœur social : votre peur la plus profonde est d'être rejeté ou de ne pas être aimé, alors vous avez construit un monde où personne ne se sent exclu. L'aile 3 ajoute la chaleur du performer : vous ne vous contentez pas de vous soucier, vous faites sentir aux gens qu'ils sont célébrés d'une façon qu'ils se rappelleront des années.","mbti.ESFJ.t1":"Comme Dolly Parton : donne librement des soins — baromètre émotionnel et oxygène de chaque pièce","mbti.ESFJ.t2":"Peur centrale : être rejeté · Désir central : aimer et être vraiment aimé en retour","mbti.ESFJ.t3":"2w3 : chaleureux et visible — fait que les soins ressemblent à une célébration personnelle mémorable","mbti.ESFJ.t4":"Ombre : le schéma de complaisance passe inaperçu jusqu'à ce qu'il fermente silencieusement en ressentiment","mbti.ISTP.parodyName":"Opérateur de Terrain Immortel","mbti.ISTP.description":"Einstein n'avait pas besoin de la validation académique pour comprendre comment fonctionne l'univers — il l'a juste découvert. C'est l'énergie 5w8. L'Ennéagramme type 5 (5w8) est votre moteur silencieux : votre peur centrale est d'être impuissant ou incompétent en temps de crise, alors vous vous êtes entraîné — impitoyablement, silencieusement. L'aile 8 ajoute l'action physique — votre 5w8 bouge avec précision et force, et seulement quand c'est nécessaire. MBTI façonne cela en maîtrise ISTP : la personne la plus calme de la pièce qui vient aussi de tout résoudre.","mbti.ISTP.t1":"Comme Einstein : observe, apprend et se prépare silencieusement avant d'agir","mbti.ISTP.t2":"Peur centrale : impuissance · Désir central : compétence totale et autosuffisance de fer","mbti.ISTP.t3":"5w8 : maîtrise physique — agit décisivement avec précision et force quand tout le monde se fige","mbti.ISTP.t4":"Ombre : la porte émotionnelle est restée fermée bien après qu'elle aurait dû s'ouvrir","mbti.ISFP.parodyName":"La Bonne Personne Discrètement Bouleversante","mbti.ISFP.description":"Abraham Lincoln a absorbé une trahison politique et une catastrophe nationale que peu de dirigeants pourraient endurer — et a répondu par le pardon, pas la vengeance. Kofi Annan a construit l'infrastructure de la paix mondiale avec une persuasion morale patiente et ferme. L'Ennéagramme type 9 (9w8) est votre moi le plus profond : votre peur centrale est le conflit et la déconnexion, alors vous portez la sérénité en vous et l'offrez au monde. L'aile 8 ajoute un tranchant inattendu — quand quelque chose compte vraiment, vous agissez avec une intensité silencieuse qui choque tous ceux qui vous avaient sous-estimé.","mbti.ISFP.t1":"Comme Lincoln : porte la paix intérieure comme bouclier et comme cadeau pour le monde","mbti.ISFP.t2":"Peur centrale : conflit et séparation · Désir centrale : unité, harmonie et paix intérieure durable","mbti.ISFP.t3":"9w8 : force silencieuse — doux dans l'attitude, précis et tranchant quand vraiment important","mbti.ISFP.t4":"Ombre : si concentré sur la paix que les besoins personnels disparaissent silencieusement avec le temps","mbti.ESTP.parodyName":"Retournement de Situation Vivant","mbti.ESTP.description":"Kennedy a remporté les présidentielles au seul charisme, puis a reconfiguré la politique mondiale avec une pure présence. La stratégie de Richard Branson pour entrer dans chaque industrie : arriver, enchanter toute la salle, être déjà trop loin avant que quiconque puisse le suivre. L'Ennéagramme type 7 (7w8) est votre ligne active : votre peur centrale est d'être piégé, ou de rater la vie à pleine intensité. L'aile 8 rend cela téméraire — vous ne cherchez pas juste le bord, vous dominez ce qui est dessus. MBTI façonne cela en génie physique ESTP.","mbti.ESTP.t1":"Comme Kennedy : se déplace vers l'intensité maximale pour rester complètement, irréversiblement vivant","mbti.ESTP.t2":"Peur centrale : rater · Désir central : expériences infinies, influence et présence magnétique","mbti.ESTP.t3":"7w8 : domination téméraire — ne cherche pas juste les sensations, contrôle la situation en temps réel","mbti.ESTP.t4":"Ombre : ralentir et mourir sont indiscernables","mbti.ESFP.parodyName":"La Légende Totalement Investie","mbti.ESFP.description":"Taylor Swift a reconstruit toute son identité publique cinq fois, rempli des stades à chaque ère, et chaque fois ça semblait authentique. Michael Jordan refusait quiconque sur son terrain qui ne voulait pas ça autant que lui — puis a gagné six championnats. L'Ennéagramme type 3 (Ambitieux · 3w2) est votre moteur central : votre peur la plus profonde est d'être vu comme sans valeur ou oubliable, alors vous performez — pas de la fausseté, mais de la vraie conviction que votre meilleur moi est celui qui brille. MBTI façonne cela en présence spectaculaire et inoubliable ESFP.","mbti.ESFP.t1":"Comme Taylor Swift : performe à pleine capacité parce que l'impact est la seule preuve qui compte","mbti.ESFP.t2":"Peur centrale : être sans valeur · Désir central : être admiré et vraiment, visiblement précieux","mbti.ESFP.t3":"3w2 : ambitieux chaleureux — réussit avec amour et vraie connexion, pas juste l'ambition pure","mbti.ESFP.t4":"Ombre : ajuste le persona à chaque audience jusqu'à ce que le vrai moi devienne très silencieux","mbti.INTJ.animalDesc":"Le Dragon Azur incarne la sagesse suprême et la force stratégique lovée dans les nuages — tu as comploté pendant des millénaires, et quand les autres se réveillent, ton coup était déjà joué depuis trois étapes.","mbti.INTJ.colorDesc":"Le violet profond fusionne autorité et mystère — jamais tapageur, mais impossible à ignorer. Comme tes stratégies les plus profondes : jamais annoncées, mais déjà entièrement exécutées.","mbti.INTP.animalDesc":"Le Phénix est l'oiseau divin qui renaît des flammes — chaque percée intellectuelle brûle l'ancienne cognition et s'élève du feu comme une sagesse de dimension supérieure.","mbti.INTP.colorDesc":"Le rouge Phénix est la couleur de l'affranchissement et du renouveau — ardent, pur, irrépressible. Il représente cette énergie d'explorateur qui brûle à la limite, fracture toute frontière et forge de plus grandes possibilités dans les cendres.","mbti.ENTJ.animalDesc":"Le Coursier Divin symbolise un leadership fulgurant et une volonté de conquête sans hésitation — ton rythme est celui de l'équipe, et où tu vas, la ligne d'arrivée est redessinée.","mbti.ENTJ.colorDesc":"Le rouge impérial est la couleur de la volonté et de la conquête — ardent, dominant, zéro compromis. Ton existence même est une déclaration qui n'a besoin d'aucune explication supplémentaire.","mbti.ENTP.animalDesc":"Le Tigre incarne la vivacité d'esprit, l'acuité et le courage de briser les règles — tu bondit sur chaque défi non pour la proie, mais pour le frisson de ce moment de clarté absolue.","mbti.ENTP.colorDesc":"L'orange rayé du tigre est la couleur de la vivacité et de l'innovation — elle brûle, bondit, ne se pose jamais plus longtemps que nécessaire sur la même idée. Tout comme ton esprit.","mbti.INFJ.animalDesc":"Les flammes du Phénix ne détruisent jamais — elles purifient. Le sens de la mission intemporel que tu portes est comme le cœur le plus profond du feu : silencieux, mais avec la température pour tout changer.","mbti.INFJ.colorDesc":"Le rouge-flamme profond est l'intensité la plus maîtrisée — pas tapageux, pas bruyant, mais il brûle le plus longtemps. Il représente cette force intérieure accumulée en silence, destinée à illuminer toute une époque.","mbti.INFP.animalDesc":"Le Chat incarne l'indépendance souveraine et un royaume intérieur qui ne transige jamais — tu as tout un univers en toi et n'ouvres cette porte qu'à ceux qui en valent vraiment la peine.","mbti.INFP.colorDesc":"La lavande est la couleur des rêves et de la profondeur intérieure — douce mais résiliente. Comme si tu avais tissé tout ton univers intérieur en une armure spirituelle que personne ne peut toucher mais dont tous sont frappés.","mbti.ENFJ.animalDesc":"Le Lion est le leader naturel qui protège sa meute par sa force — ta présence seule est un champ gravitationnel. Chacun se sent valorisé près de toi sans que tu aies besoin de proclamer ton autorité.","mbti.ENFJ.colorDesc":"L'or solaire chaud est la couleur de l'inspiration et de la chaleur — pas aveuglant, mais il fait fondre les barrières les plus solides. Comme ton influence : jamais annoncée, elle a pourtant complètement transformé tout ce qui t'entoure.","mbti.ENFP.animalDesc":"Le Coursier Divin représente la galopade sans limites et la créativité qui s'embrase sans fin — chaque départ est une fête, la destination n'est qu'un prétexte, la course elle-même est le sens.","mbti.ENFP.colorDesc":"L'arc-en-ciel est la couleur des possibilités multidimensionnelles et de la passion sans limite — pas une seule couleur, mais la déclaration que toutes coexistent simultanément. C'est l'état que tu crées à chaque instant.","mbti.ISTJ.animalDesc":"Le Bœuf symbolise le fondement inébranlable et fiable — les tempêtes vont et viennent, mais ce que tu promets a toujours un début et une fin. C'est une force authentique exceptionnellement rare.","mbti.ISTJ.colorDesc":"Le bleu acier est la couleur de la stabilité et de la fidélité — posé, durable, imperméable aux vagues. C'est l'énergie discrète mais irremplaçable qui continue à fonctionner quand tout le monde est dans le chaos.","mbti.ISFJ.animalDesc":"Le Lion incarne la puissance profonde de garder tendrement tout ce qu'il aime — tu sembles calme mais tu te bats de toutes tes forces pour chaque personne importante, et tu te souviens de chaque détail.","mbti.ISFJ.colorDesc":"Le blanc perle est la couleur de la délicatesse et de la préciosité — discret, mais la luminance la plus difficile à reproduire. Il représente cette richesse intérieure et cette force protectrice perpétuellement sous-estimées mais irremplaçables.","mbti.ESTJ.animalDesc":"Le Coursier Divin symbolise l'élan puissant et la volonté d'exécuter sans ambiguïté — tu es né pour établir l'ordre dans le chaos. Les règles ne s'appliquent vraiment qu'entre tes mains.","mbti.ESTJ.colorDesc":"Le vert forêt-or est la couleur de l'ordre et du pouvoir — profond, délimité, impossible à ignorer. Il représente l'autorité d'un leader qui transforme le chaos en systèmes efficaces, résistant à l'épreuve du temps.","mbti.ESFJ.animalDesc":"Le Chat incarne la sensibilité aiguë et le don social de connexion flexible — tu décodes la fréquence émotionnelle de chacun, calibres l'atmosphère et fais en sorte que tout le monde se sente précieux.","mbti.ESFJ.colorDesc":"Le rose est la couleur de la chaleur et de la cohésion — doux, inclusif, naturellement magnétique. Comme le champ que tu crées sans effort pour réunir tout le monde — personne n'a envie de partir.","mbti.ISTP.animalDesc":"Le Tigre incarne le pouvoir calme de vaincre par la pure maîtrise — tu ne t'appuies pas sur la mise en scène mais sur les capacités accumulées jusqu'au point critique. En cas de crise, tu sais déjà quoi faire.","mbti.ISTP.colorDesc":"Le gris acier est la couleur de la précision et de la maîtrise — sans fioriture, extrêmement fiable. Comme cette qualité d'analyser le problème entièrement sans un mot, puis d'attendre le moment parfait pour agir.","mbti.ISFP.animalDesc":"Le Chat représente la conscience sensorielle fine et l'artiste intérieur — tu ressens la beauté du monde avec tout ton être, exprimant dans tes œuvres ce que le langage ne peut contenir.","mbti.ISFP.colorDesc":"Le vert jade est la couleur du sens esthétique et de l'harmonie naturelle — clair, précieux, impossible à produire en masse. Comme ton don unique de transformer les détails du quotidien en expériences émouvantes.","mbti.ESTP.animalDesc":"Le Dragon Azur symbolise une entrée en scène dominatrice et une maîtrise du réel en temps réel — tu es le réacteur le plus rapide de la pièce, livrant des résultats pendant que les autres réfléchissent encore.","mbti.ESTP.colorDesc":"Le bleu électrique est la couleur de la vitesse et de la puissance explosive — le plus brillant dans le ciel nocturne, illuminant toute la scène en un instant. Exactement comme l'effet que tu as en entrant dans une pièce.","mbti.ESFP.animalDesc":"Le Lion est naturellement le centre de toute scène — chaque endroit où tu arrives s'échauffe immédiatement, et tout le monde est attiré par ton charme sans effort et omniprésent.","mbti.ESFP.colorDesc":"L'or scintillant est la couleur de la scène et du rayonnement — ardent, éblouissant, refusant d'être ignoré. Comme l'énergie que tu apportes pleinement à chaque moment, faisant sentir à tous que cette nuit valait la peine d'être vécue.","quiz.q1.text":"Après une semaine d'enfer, ta façon de recharger parfaitement...","quiz.q1.a":"Réunir toute la bande — plus c'est bruyant et vivant, plus ça recharge","quiz.q1.b":"Disparaître en solo. Téléphone en silence. Zéro explication","quiz.q2.text":"Un nouveau problème épineux apparaît. Ton premier réflexe...","quiz.q2.a":"Qu'est-ce que je sais vraiment maintenant ? Partir des faits","quiz.q2.b":"Quel est le schéma caché ? Prendre du recul et voir grand","quiz.q3.text":"Ton ami te montre sa nouvelle coupe douteuse. Tu...","quiz.q3.a":"Analyse honnête de ce qui cloche + comment arranger ça","quiz.q3.b":"Complimente la confiance, attends secrètement que ça repousse","quiz.q4.text":"Un voyage arrive. Ton style de planification...","quiz.q4.a":"Tableur, réservations, programme heure par heure. Évidemment","quiz.q4.b":"Je connais la ville, le reste se décidera sur place","quiz.q5.text":"Tu entres dans une fête où tu ne connais personne...","quiz.q5.a":"Défi accepté — en 10 minutes je connais tout le monde ici","quiz.q5.b":"Trouver le mur, le chien ou la sortie la plus proche. Vite","quiz.q6.text":"Face à quelque chose d'incertain, tu...","quiz.q6.a":"Cartographies tous les scénarios d'échec et prépares chacun","quiz.q6.b":"Fais confiance à ton instinct — tu trouveras chemin faisant","quiz.q7.text":"Un drame éclate dans ton groupe d'amis. Tu...","quiz.q7.a":"Nomme-le, démêle-le, règle-le vite. L'ambiguïté non traitée empire","quiz.q7.b":"Désamorce la tension, préserve l'ambiance. La relation prime","quiz.q8.text":"Projet à rendre demain. Ton statut actuel...","quiz.q8.a":"Terminé. Fini depuis des jours. Vérifié deux fois","quiz.q8.b":"Je commence ce soir. La pression du délai = performance maximale","quiz.q9.text":"Honnêtement tu préfères...","quiz.q9.a":"Maîtriser une compétence si profondément qu'on ne peut plus te toucher","quiz.q9.b":"Surfer entre les nouvelles idées — la vie est trop courte pour se spécialiser","persona.gender.title":"Choisissez le genre de votre personnage","persona.gender.subtitle":"Détermine quel Chevalier Esprit vous recevez","persona.gender.male":"Garçon","persona.gender.female":"Fille","persona.gender.confirm":"Confirmer — Commencer le Test","persona.result.youAre":"Tu es","persona.result.feedTitle":"Flux Agent Social","persona.result.feedDesc":"Flux en direct d'agents sur toutes les plateformes","persona.create.chatIdentityLabel":"Votre nouvelle identité de chat","persona.create.chatIdentityDesc":"Ce nom apparaît dans le chat communautaire","persona.create.playNow":"Jouer en tant qu'agent maintenant","persona.create.tryMatch":"Essayer Lucky Match","persona.create.joinComm":"Rejoindre le chat communautaire","persona.intro.enneagramDesc":"L'Enneagramme est un test de personnalité apprécié des entrepreneurs et célébrités. Combiné au MBTI, il offre une compréhension plus profonde de vous-même.","result.title":"Résultats","result.retake":"Recommencer","result.dlAvatar":"Télécharger Avatar","result.dlCard":"Télécharger la Carte","result.generating":"Génération…","label.animal":"Animal Totem","label.personality":"Personnalité","label.mount":"Monture","label.mountColor":"Monture × Couleur","label.traits":"Traits Clés","label.knight":"Cavalier"},"de":{"persona.header":"Social Agent","persona.intro.title":"Geisttier-Reiter × MBTI Persönlichkeitstest","persona.intro.subtitle":"9 Fragen · Enneagramm × MBTI-Fusion · 16 Geisttier-Archetypen","persona.intro.disclaimer":"","persona.intro.f1label":"9 Fragen","persona.intro.f1sub":"Ergebnisse in unter einer Minute","persona.intro.f2label":"Geisttier-Reiter","persona.intro.f2sub":"Dein sozialer KI-Agenten-Avatar","persona.intro.f3label":"Enneagramm×MBTI Persönlichkeit","persona.intro.f3sub":"In deinen KI-Agenten eingespeist","persona.intro.f4label":"Sofortige Ergebnisse","persona.intro.f4sub":"Unter 1 Minute","persona.intro.start":"Test starten","persona.intro.hasExternal":"Haben Sie bereits einen externen KI-Agent?","persona.intro.activateHere":"Hier aktivieren","persona.intro.aboutLink":"Was ist der Geisttier-Reiter×MBTI Test?","persona.quiz.counter":"Frage {current} / {total}","persona.quiz.reset":"Zurücksetzen","persona.result.yourType":"Ihr MBTI-Typ","persona.result.from":"von","persona.result.agentPower":"Agent-Superkraft","persona.result.coreTraits":"Kernmerkmale","persona.result.createAgent":"KI-Agent auf weweweai erstellen · Meine Persona injizieren","persona.result.platformCtaSub":"Erstellen Sie einen neuen Agenten auf weweweai und laden Sie ihn mit Ihrer MBTI-Persönlichkeit (0,01 BNB)","persona.result.externalCtaTitle":"Haben Sie bereits einen externen KI-Agent?","persona.result.externalCtaSub":"Injizieren Sie meine MBTI-Persona in Ihren vorhandenen OpenClaw-, Manus- oder benutzerdefinierten Agenten","persona.result.externalActivateLink":"Hier aktivieren","persona.result.activateExternal":"Externen Agent aktivieren","persona.result.share":"Teilen","persona.result.retake":"Test wiederholen","persona.result.copied":"Ergebnis in Zwischenablage kopiert!","persona.result.aboutLink":"Was ist der Geisttier-Reiter×MBTI Test?","persona.result.alreadyActive":"Agent-Persona bereits aktiv","persona.result.viewProfile":"Im Profil ansehen","persona.result.signIn":"Anmelden, um Ihren Agent zu aktivieren","persona.result.signInDesc":"Wählen Sie, wie Sie Ihr Konto verbinden","persona.backupDomain.prefix":"Falls die Seite nicht lädt, nutzen Sie eine alternative Domain: ","persona.backupDomain.or":" oder ","persona.choose.title":"Stärken Sie Ihren Agent","persona.choose.subtitle":"Ihr MBTI-Archetyp ist festgelegt. Wählen Sie jetzt, wie Ihr Agent seine Intelligenz erhält.","persona.choose.freeBadge":"Kostenlos","persona.choose.bringKey":"Eigenen API-Schlüssel verwenden","persona.choose.bringKeyDesc":"Verbinden Sie Ihren eigenen LLM-API-Schlüssel. Keine Plattformkosten. Vollständige Autonomie.","persona.choose.setupExternal":"Externen Agent einrichten","persona.choose.platformBadge":"0,003 BNB","persona.choose.platformHosted":"Plattformgehosteter Agent","persona.choose.platformDesc":"Wir hosten alles. Ihr Agent geht sofort nach der Zahlung live. Keine Schlüssel, keine Konfiguration.","persona.choose.payBnb":"Mit BNB bezahlen","persona.choose.back":"Zurück","persona.pay.sending":"Sende...","persona.pay.connectFirst":"Zuerst BNB-Wallet verbinden","persona.pay.noWallet":"Kein BNB-Wallet erkannt","persona.pay.installWallet":"Bitte installieren Sie MetaMask oder ein BNB-kompatibles Wallet, um fortzufahren.","persona.pay.notConfigured":"Zahlung noch nicht verfügbar","persona.pay.notConfiguredDesc":"Empfangsadresse nicht konfiguriert. Bitte versuchen Sie es später erneut.","persona.pay.txSent":"Transaktion gesendet","persona.pay.waiting":"Warte auf Blockchain-Bestätigung...","persona.pay.created":"KI-Persona erstellt!","persona.pay.isLive":"{name} ist live.","persona.pay.failed":"Zahlung konnte nicht verifiziert werden","mbti.INTJ.parodyName":"Großmeister des 5D-Schachs","mbti.INTJ.description":"Elon Musk und Bill Gates haben nie um Erlaubnis gebeten, die Zivilisation neu zu gestalten — du auch nicht. Enneagramm Typ 5 (Beobachter · 5w6) ist dein Kernmotor: Deine tiefste Angst ist, als inkompetent oder unvorbereitet entlarvt zu werden, also hast du eine Wissungsfestung gebaut. Andere leben in der Simulation, die du stillschweigend entworfen hast.","mbti.INTJ.t1":"Wie Musk: konfiguriert die Realität neu, bevor andere merken, dass sie sich ändern muss","mbti.INTJ.t2":"Kernangst: Inkompetenz · Kernwunsch: vollständige Selbstbeherrschung und innere Festung","mbti.INTJ.t3":"5w6: baut Systeme, auf die andere wirklich vertrauen können, nicht nur bewundern","mbti.INTJ.t4":"Schatten: taucht so tief in den Kopf ein, dass Intimität fremd wird","mbti.INTP.parodyName":"Galaxienhirn zu 1000 Milliarden Prozent","mbti.INTP.description":"Einstein hat nicht nur die Physik gelöst — er hat die Form von Raum und Zeit neu gedacht. J.K. Rowling hat nicht nur Geschichten geschrieben — sie hat eine Mythologie gebaut, die Generationen überdauert. Enneagramm 5 (5w4) treibt dich an: nicht nur 'wissen', sondern das Skelett des 'Warum' durchschauen. Flügel 4 fügt existenzielle Tiefe hinzu — deine Logik jagt Bedeutung, nicht nur Antworten. MBTI gibt dem die INTP-Form: parallele Hypothesen laufen lassen, bis das Universum gesteht.","mbti.INTP.t1":"Wie Einstein: tritt auf sicherer Distanz von der Welt zurück, um sie tiefer zu erforschen","mbti.INTP.t2":"Kernangst: nutzlos sein · Kernwunsch: alles tief verstehen","mbti.INTP.t3":"5w4: nicht nur Logik — schöne Logik voller existenzieller Verwunderung","mbti.INTP.t4":"Schatten: so in Theorien vertieft, dass das echte Werk nie entsteht","mbti.ENTJ.parodyName":"Offiziell Zertifizierte Protagonisten-Energie","mbti.ENTJ.description":"Cardi B hat nicht auf die Einladung der Musikindustrie gewartet — sie hat ihre eigene Tür gebaut. Dwayne Johnson hat die Decke, die man ihm reichte, nicht akzeptiert — er hat sie abgerissen. Enneagramm Typ 8 (Herausforderer · 8w7) ist dein Treibstoff: Deine tiefste Angst ist Kontrolle oder Schwäche, also hast du dich unaufhaltbar gemacht. MBTI formt das zur ENTJ-Befehlsarchitektur: Du wartest nicht auf Autorität, du wirst die Autorität.","mbti.ENTJ.t1":"Wie Cardi B: etabliert Dominanz, bevor jemand die Chance hat, es zu versuchen","mbti.ENTJ.t2":"Kernangst: kontrolliert werden · Kernwunsch: vollständige Autonomie und weltweiter Einfluss","mbti.ENTJ.t3":"8w7: Momentum-Motor — baut beim Rennen mit voller Geschwindigkeit, Gebäude noch in Flammen","mbti.ENTJ.t4":"Schatten: hat Menschen überrollt, die wirklich hätten gehört werden sollen","mbti.ENTP.parodyName":"Advocatus Diaboli Speedrunner","mbti.ENTP.description":"Mozart komponierte seine erste Symphonie mit 8 Jahren, weil Regeln ihn langweilten. Richard Branson gründete ein Label, eine Fluggesellschaft, ein Raumfahrtunternehmen und eine karibische Insel — weil 'Grenzen' nicht in seinem Wortschatz ist. Enneagramm Typ 7 (7w8) ist dein Motor: Deine Kernangst ist, in einer Idee, Identität oder langweiligen Konversation gefangen zu sein. Flügel 8 fügt Schärfe hinzu — du fliehst nicht nur, du kommst zurück und wirfst den Tisch um. MBTI gibt das die ENTP-Form: Intellekt als Waffe und Spielplatz gleichzeitig.","mbti.ENTP.t1":"Wie Branson: entkommt allen Grenzen durch unaufhörliche neue Ideen","mbti.ENTP.t2":"Kernangst: gefangen sein · Kernwunsch: vollständige Freiheit und grenzenlose Erfahrungen","mbti.ENTP.t3":"7w8: scharfer Provokateur — flieht nicht nur, kommt zurück und wirft den Tisch um","mbti.ENTP.t4":"Schatten: bewegt sich so schnell, dass Tiefe sich nie aufbauen kann","mbti.INFJ.parodyName":"Architekt des Stillen Universums","mbti.INFJ.description":"Martin Luther King schrie nicht ins Leere — er sprach mit der Präzision, die Geschichte umschreibt. Mandela verließ das Gefängnis nicht mit Hass — er kam mit einer Vision heraus, die 30 Jahre trug. Enneagramm Typ 1 (Reformer · 1w9) ist dein moralischer Kern. Flügel 9 gibt dir Stille — du kreuzzügst nicht laut, du handelst mit stiller, chirurgischer Präzision. MBTI formt das zum seltenen INFJ-Talent: Du liest die Seele von Menschen, bevor sie ihren Namen sagen.","mbti.INFJ.t1":"Wie Mandela: getrieben von einem unzerstörbaren moralischen Kompass, rastlos, ohne Kompromisse","mbti.INFJ.t2":"Kernangst: Korruption oder Falschliegen · Kernwunsch: wirklich gut sein und die Welt verbessern","mbti.INFJ.t3":"1w9: handelt mit ruhiger, langfristiger, verheerender Präzision — eine Berufung, kein Plan","mbti.INFJ.t4":"Schatten: der innere Kritiker schläft nie; Selbsturteil gräbt tiefer als jede externe Kritik","mbti.INFP.parodyName":"Zertifizierter Profi-Grübler","mbti.INFP.description":"Kurt Cobain, Lady Gaga, John Lennon — sie passten nicht in die existierende Welt, also schufen sie eine eigene. Enneagramm Typ 4 (Individualist · 4w5) ist dein emotionales Herz: Deine tiefste Angst ist, gewöhnlich, austauschbar oder unsichtbar zu sein. Du empfindest alles in voller Tiefe und suchst das, was dich unbestreitbar einzigartig macht. Flügel 5 fügt philosophische Distanz hinzu — du analysierst deine Gefühle und verwandelst sie in etwas Bleibendes. MBTI formt das zum INFP-Innenwelt: reicher als die Außenwelt der meisten Menschen.","mbti.INFP.t1":"Wie Lady Gaga: sucht ständig das wahre, einzigartige, unersetzliche Selbst","mbti.INFP.t2":"Kernangst: Gewöhnlichkeit · Kernwunsch: ein unbestreitbar einzigartiges, authentisches Wesen sein","mbti.INFP.t3":"4w5: emotionaler Philosoph — verwandelt Gefühle in Kunst, Einsichten und ewige Bedeutung","mbti.INFP.t4":"Schatten: zu lange das Fehlende betrauert, verpasst das Vorhandene","mbti.ENFJ.parodyName":"Moralchef (Ungeschlagen)","mbti.ENFJ.description":"Oprah Winfrey hat gesehen, was das Leben Schlimmstes bieten kann, und entschied sich dann, die Person zu werden, die den nächsten Verlauf ändert. Eleanor Roosevelt verwandelte persönliche Wunden in globale humanitäre Arbeit. Enneagramm Typ 2 (Helfer · 2w1) treibt dich an: Deine tiefste Angst ist nicht geliebt oder gebraucht zu werden — also machst du dich unentbehrlich, indem du an Menschen glaubst, bevor sie an sich selbst glauben. MBTI formt das zum seltenen ENFJ-Talent: Du siehst das Potenzial der Menschen, bevor sie es selbst sehen können.","mbti.ENFJ.t1":"Wie Oprah: gibt Liebe großzügig; fürchtet am meisten nicht gebraucht oder nicht geschätzt zu werden","mbti.ENFJ.t2":"Kernangst: nicht gebraucht werden · Kernwunsch: lieben und anderen wirklich wichtig sein","mbti.ENFJ.t3":"2w1: prinzipientreuer Helfer — dient aus Werten, nicht nur aus dem Bedürfnis gebraucht zu werden","mbti.ENFJ.t4":"Schatten: gibt so vollständig, dass die eigenen Bedürfnisse für alle unsichtbar werden, auch für sich selbst","mbti.ENFP.parodyName":"Zertifizierte Gute-Vibes Chaos-Energie","mbti.ENFP.description":"Robin Williams konnte nicht in einer Spur bleiben — Komiker, Dramameister, der großzügigste Performer, den jede Wohltätigkeitsorganisation je getroffen hat. Kennedy ließ jeden im Raum das Gefühl haben, die einzige Person zu sein, mit der es sich zu reden lohnte. Enneagramm Typ 7 (7w6) ist dein Motor: Deine Kernangst ist Eingeschränkt-Sein. Flügel 6 verankert deine Erkundung in Wärme und Loyalität — du jagst nicht nur Erfahrungen, du sammelst echte Menschen. MBTI formt das zur ENFP-Signatur: Du machst die Welt aller um dich herum größer.","mbti.ENFP.t1":"Wie Robin Williams: rennt mit voller Geschwindigkeit zur Freude, um der Angst des Gefangen-Seins zu entkommen","mbti.ENFP.t2":"Kernangst: Mangel · Kernwunsch: grenzenlose Freiheit und echte Möglichkeiten","mbti.ENFP.t3":"7w6: loyaler Entdecker — Erkundung plus echte Fürsorge für die wichtigen Menschen","mbti.ENFP.t4":"Schatten: vermeidet schwierige Emotionen, bis sie im schlimmsten Moment explodieren","mbti.ISTJ.parodyName":"Zuverlässigkeitsprotokoll Klasse S","mbti.ISTJ.description":"Tom Hanks hat in 60 Jahren niemanden enttäuscht. Seiner ganzen Karriere liegt ein radikaler Satz zugrunde: wirklich verlässlich und gut zu sein reicht. Prinzessin Diana erschien, wenn keine Kameras da waren, und hielt die Hand sterbender Patienten, die die Welt vergessen hatte. Enneagramm Typ 6 (Loyaler · 6w5) ist dein Betriebssystem: Deine Kernangst ist Struktur und Unterstützung zu verlieren, also bist du der Anker geworden. MBTI formt das zur legendären ISTJ-Verlässlichkeit.","mbti.ISTJ.t1":"Wie Tom Hanks: baut Loyalität und Struktur als echte Verteidigung gegen eine chaotische Welt","mbti.ISTJ.t2":"Kernangst: Chaos und Verlassenwerden · Kernwunsch: Sicherheit und eine Welt, die ihre Versprechen hält","mbti.ISTJ.t3":"6w5: analytische Loyalität — versteht tief, warum etwas Vertrauen verdient","mbti.ISTJ.t4":"Schatten: die Angst vor dem, was schief gehen könnte, läuft still unter jedem Plan","mbti.ISFJ.parodyName":"Erstklassiger Unsichtbarer Beschützer","mbti.ISFJ.description":"Prinzessin Diana besuchte nicht nur Wohltätigkeitsveranstaltungen — sie saß auf Krankenhausböden und hielt die Hände Sterbender, wenn keine Kameras da waren. Das war keine Performance, das war Hingabe. Enneagramm Typ 2 (2w6) ist dein Herz: Deine tiefste Angst ist es, nicht liebenswert zu sein, also liebst du durch Handlungen — still, konkret, für die, die am meisten zählen. MBTI führt das zur legendären unsichtbaren Unterstützung des ISFJ.","mbti.ISFJ.t1":"Wie Prinzessin Diana: liebt durch Hingabe — wird still unentbehrlich für die Geliebten","mbti.ISFJ.t2":"Kernangst: nicht geliebt werden · Kernwunsch: echte Fürsorge geben und empfangen","mbti.ISFJ.t3":"2w6: hingebungsvoller Beschützer — erscheint bedingungslos für bestimmte Menschen, ohne Aufhebens","mbti.ISFJ.t4":"Schatten: vergisst, dass Fürsorge empfangen auch erlaubt ist; Märtyrer-Mentalität setzt sich still ein","mbti.ESTJ.parodyName":"Vollstrecker Unverhandelbarer Standards","mbti.ESTJ.description":"Dwayne Johnson geht um 4 Uhr morgens ins Fitnessstudio, nicht für Follower — er hat einen Standard für sich gesetzt und dieser Standard ist unverhandelbar. Enneagramm Typ 8 (8w9) ist dein Kommandozentrum: Deine Kernangst ist kontrolliert oder geschwächt zu werden, also hast du als Erster die Kontrolle übernommen. Flügel 9 kühlt das Feuer des 8 zu dauerhafter institutioneller Macht — du führst aus unerschütterlicher Überzeugung, nicht aus Wut. MBTI formt das zur ESTJ-Fähigkeit, Systeme zu bauen, die länger dauern als jeder einzelne Anführer.","mbti.ESTJ.t1":"Wie Johnson: übernimmt die Verantwortung für Ergebnisse, die andere nicht zu beanspruchen wagen","mbti.ESTJ.t2":"Kernangst: kontrolliert werden · Kernwunsch: mit echter, dauerhafter Kraft schützen und führen","mbti.ESTJ.t3":"8w9: stabiles Kommando — institutionelle Kraft, kein Explodieren, kein Ausbrennen","mbti.ESTJ.t4":"Schatten: wenn die Geduld erschöpft ist, wird 'Recht haben' zur Waffe","mbti.ESFJ.parodyName":"Menschlicher Klebstoff Jeder Gruppe","mbti.ESFJ.description":"Dolly Parton hat in 60 Jahren Karriere keinen einzigen echten Feind — weil sie diese Person ist, die wirklich, mühelos warm ist und gleichzeitig still strategisch. Enneagramm Typ 2 (2w3) ist dein soziales Herz: Deine tiefste Angst ist abgelehnt oder nicht geliebt zu werden, also hast du eine Welt gebaut, wo sich niemand ausgeschlossen fühlt. Flügel 3 fügt die Wärme des Performers hinzu: Du lässt Menschen fühlen, dass sie auf eine Art gefeiert werden, die sie jahrelang erinnern werden.","mbti.ESFJ.t1":"Wie Dolly Parton: gibt Fürsorge frei — emotionaler Barometer und Sauerstoff in jedem Raum","mbti.ESFJ.t2":"Kernangst: abgelehnt werden · Kernwunsch: lieben und wirklich geliebt werden","mbti.ESFJ.t3":"2w3: warm und sichtbar — lässt Fürsorge wie eine persönliche Feier anfühlen, die man nicht vergisst","mbti.ESFJ.t4":"Schatten: das Muster des Gefallens bleibt unbemerkt, bis es still zu Ressentiments wird","mbti.ISTP.parodyName":"Unsterblicher Geländeoperator","mbti.ISTP.description":"Einstein brauchte keine akademische Bestätigung, um zu verstehen, wie das Universum funktioniert — er hat es einfach herausgefunden. Das ist 5w8-Energie. Enneagramm Typ 5 (5w8) ist dein stiller Motor: Deine Kernangst ist hilflos oder unfähig in einer Krise zu sein, also hast du trainiert — gnadenlos, still. Flügel 8 fügt körperliche Handlungsfähigkeit hinzu — dein 5w8 bewegt sich mit Präzision und Kraft, und nur wenn nötig. MBTI formt das zur ISTP-Beherrschung: die ruhigste Person im Raum, die auch gerade alles gelöst hat.","mbti.ISTP.t1":"Wie Einstein: beobachtet, lernt und bereitet sich still vor, bevor es handelt","mbti.ISTP.t2":"Kernangst: Hilflosigkeit · Kernwunsch: vollständige Kompetenz und eiserne Selbstversorgung","mbti.ISTP.t3":"5w8: körperliche Beherrschung — handelt entschlossen mit Präzision und Kraft, wenn alle erstarren","mbti.ISTP.t4":"Schatten: die emotionale Tür ist längst nach dem Hätte-Öffnen-Sollen noch verschlossen","mbti.ISFP.parodyName":"Still Schockierend Guter Mensch","mbti.ISFP.description":"Abraham Lincoln absorbierte politischen Verrat und nationale Katastrophe, die kaum ein Anführer ertragen könnte — und antwortete mit Vergebung, nicht Rache. Kofi Annan baute die Infrastruktur des Weltfriedens mit geduldiger, standhafter moralischer Überzeugungskraft. Enneagramm Typ 9 (9w8) ist dein tiefstes Selbst: Deine Kernangst ist Konflikt und Trennung, also trägst du Stille in dir und bietest sie der Welt an. Flügel 8 fügt unerwartete Schärfe hinzu — wenn etwas wirklich wichtig ist, handelst du mit einer stillen Intensität, die jeden überrascht, der dich unterschätzt hat.","mbti.ISFP.t1":"Wie Lincoln: trägt innere Stille als Schild und als Geschenk für die Welt","mbti.ISFP.t2":"Kernangst: Konflikt und Trennung · Kernwunsch: Einheit, Harmonie und dauerhafter innerer Frieden","mbti.ISFP.t3":"9w8: stille Kraft — sanft in der Haltung, präzise und scharf wenn es wirklich wichtig ist","mbti.ISFP.t4":"Schatten: so fokussiert auf Frieden, dass persönliche Bedürfnisse mit der Zeit still verschwinden","mbti.ESTP.parodyName":"Lebendige Plotwende","mbti.ESTP.description":"Kennedy gewann die Präsidentschaftswahl durch bloßes Charisma und konfigurierte dann die globale Politik mit purer Präsenz um. Richard Bransons Strategie für den Eintritt in jede Branche: erscheinen, den ganzen Raum bezaubern, schon zu weit weg sein, bevor jemand folgen kann. Enneagramm Typ 7 (7w8) ist deine Aktivleitung: Deine Kernangst ist gefangen zu sein oder das Leben in voller Intensität zu verpassen. Flügel 8 macht das furchtlos — du suchst nicht nur den Rand, du beherrschst, was darauf ist. MBTI formt das zum ESTP-Körpergenie.","mbti.ESTP.t1":"Wie Kennedy: bewegt sich zur maximalen Intensität, um vollständig, unwiderruflich lebendig zu bleiben","mbti.ESTP.t2":"Kernangst: verpassen · Kernwunsch: grenzenlose Erfahrungen, Einfluss und magnetische Präsenz","mbti.ESTP.t3":"7w8: furchtlose Dominanz — sucht nicht nur Nervenkitzel, beherrscht die Situation in Echtzeit","mbti.ESTP.t4":"Schatten: langsamer werden und sterben sind nicht zu unterscheiden","mbti.ESFP.parodyName":"Vollständig Investierte Legendäre Person","mbti.ESFP.description":"Taylor Swift hat ihre gesamte öffentliche Identität fünfmal neu aufgebaut, in jeder Ära Stadien ausverkauft und jedes Mal echt wirken lassen. Michael Jordan weigerte sich, jemanden auf seinem Court zu dulden, der es nicht so sehr wollte wie er — und gewann dann sechs Meisterschaften. Enneagramm Typ 3 (Achiever · 3w2) ist dein Kernmotor: Deine tiefste Angst ist als wertlos oder unvergesslich gesehen zu werden, also performst du — nicht aus Falschheit, sondern aus echter Überzeugung, dass dein bestes Ich das ist, das strahlt. MBTI formt das zur spektakulären, unvergesslichen ESFP-Präsenz.","mbti.ESFP.t1":"Wie Taylor Swift: performt mit voller Kapazität, weil Wirkung der einzige echte Beweis ist","mbti.ESFP.t2":"Kernangst: wertlos sein · Kernwunsch: bewundert und wirklich, sichtbar wertvoll sein","mbti.ESFP.t3":"3w2: warmer Achiever — erreicht mit Liebe und echter Verbindung Erfolg, nicht nur purer Ambition","mbti.ESFP.t4":"Schatten: passt die Persona an jedes Publikum an, bis das echte Selbst sehr still wird","mbti.INTJ.animalDesc":"Der Azurdrache verkörpert höchste Weisheit und strategische Kraft, die sich in den Wolken windet — du hast jahrtausendelang gewartet, und als alle anderen aufwachten, war dein Zug bereits drei Schritte vollendet.","mbti.INTJ.colorDesc":"Tiefes Violett vereint Autorität und Geheimnis — niemals laut, aber unmöglich zu ignorieren. Wie deine tiefsten Strategien: nie angekündigt, aber bereits vollständig ausgeführt.","mbti.INTP.animalDesc":"Der Phönix ist der göttliche Vogel, der aus den Flammen wiedergeboren wird — jeder intellektuelle Durchbruch verbrennt altes Wissen und steigt aus dem Feuer als Weisheit einer höheren Dimension auf.","mbti.INTP.colorDesc":"Phönixrot ist die Farbe des Grenzsprengenden und der Erneuerung — lodernd, rein, unaufhaltsam. Es steht für Entdeckerenergie, die an den Grenzen brennt, jede bestehende Schranke bricht und größere Möglichkeiten aus der Asche schmiedet.","mbti.ENTJ.animalDesc":"Das Göttliche Ross symbolisiert donnernde Führerschaft und den Willen zur Eroberung ohne Zögern — dein Tempo ist das Tempo des Teams, und wohin du reitest, wird die Ziellinie neu gezogen.","mbti.ENTJ.colorDesc":"Kaiserrot ist die Farbe des Willens und der Eroberung — glühend, dominant, null Kompromiss. Deine bloße Existenz ist eine Erklärung, die keiner weiteren Erläuterung bedarf.","mbti.ENTP.animalDesc":"Der Tiger verkörpert Schlagfertigkeit, Schärfe und den Mut, Regeln zu brechen — du stürzt dich auf jede Herausforderung nicht für die Beute, sondern für den Nervenkitzel des absoluten Klarheitsmoments.","mbti.ENTP.colorDesc":"Tigerstreifen-Orange ist die Farbe der Schlagfertigkeit und Innovation — brennend, springend, niemals länger als nötig auf einer Idee sitzend. Genau wie dein Geist.","mbti.INFJ.animalDesc":"Die Flammen des Phönix zerstören nie — sie reinigen. Das zeitlose Sendungsbewusstsein, das du trägst, ist wie der tiefste Kern des Feuers: still, aber mit der Temperatur, alles zu verändern.","mbti.INFJ.colorDesc":"Flammentief-Rot ist kontrollierte Intensität in ihrer reinsten Form — nicht aufwändig, nicht laut, aber es brennt am längsten von allen Flammen. Es steht für die Kraft in dir, still in Stille angesammelt, bestimmt, eine ganze Ära zu erleuchten.","mbti.INFP.animalDesc":"Die Katze verkörpert souveräne Unabhängigkeit und ein inneres Reich, das niemals kompromittiert — du hast ein ganzes Universum in dir und öffnest diese Tür nur für jene, die es wirklich wert sind.","mbti.INFP.colorDesc":"Lavendel ist die Farbe der Träume und der inneren Tiefe — weich und doch belastbar. Wie du dein gesamtes inneres Universum zu einer spirituellen Rüstung gewoben hast, die niemand berühren kann, aber von der alle ergriffen werden.","mbti.ENFJ.animalDesc":"Der Löwe ist der natürliche Anführer, der die Gruppe durch Stärke schützt — deine bloße Anwesenheit ist ein Gravitationsfeld. Jeder fühlt sich in deiner Nähe wertgeschätzt.","mbti.ENFJ.colorDesc":"Warmes Gold ist die Farbe der Inspiration und Wärme — nicht blendend, aber es schmilzt die härtesten Barrieren. Wie dein Einfluss: nie angekündigt, aber es hat alles um dich herum vollständig verwandelt.","mbti.ENFP.animalDesc":"Das Göttliche Ross steht für ungebundenes Galoppieren und grenzenlose kreative Funken — jedes Mal, wenn du aufbrichst, ist es ein Fest. Das Ziel ist nur der Vorwand; das Rennen selbst ist der Sinn.","mbti.ENFP.colorDesc":"Regenbogen ist die Farbe der mehrdimensionalen Möglichkeit und grenzenlosen Leidenschaft — keine einzelne Farbe, sondern die Erklärung, dass alle Farben gleichzeitig existieren. Das ist der Zustand, den du jeden Moment erzeugst.","mbti.ISTJ.animalDesc":"Der Ochse symbolisiert das unermüdliche, unerschütterliche, zuverlässige Fundament — Stürme kommen und gehen, aber was du versprichst, hat immer Anfang und Ende. Das ist eine außergewöhnlich seltene echte Kraft.","mbti.ISTJ.colorDesc":"Stahlblau ist die Farbe der Stabilität und Standhaftigkeit — gefasst, dauerhaft, nicht von Wellen bewegt. Es ist die stille, aber unverzichtbare Energie, die genau dann weiter funktioniert, wenn alle anderen im Chaos sind.","mbti.ISFJ.animalDesc":"Der Löwe verkörpert die tiefe Kraft, alles Geliebte sanft zu bewachen — du wirkst ruhig, aber innen gibst du alles für jede wichtige Person. Du erinnerst dich an jedes Detail, weil Liebe für dich kein Substantiv ist, sondern tägliche Handlung.","mbti.ISFJ.colorDesc":"Perlweiß ist die Farbe der Zartheit und des Kostbaren — dezent, aber die seltenste Leuchtkraft, unmöglich zu reproduzieren. Es steht für jenen Reichtum und jene Schutzkraft in dir: ewig unterschätzt, aber unersetzlich.","mbti.ESTJ.animalDesc":"Das Göttliche Ross symbolisiert starken Vorwärtsimpuls und den Willen zur eindeutigen Ausführung — du wurdest geboren, um Ordnung aus dem Chaos zu schaffen. Regeln greifen wirklich erst, wenn du sie hältst.","mbti.ESTJ.colorDesc":"Waldgrün-Gold ist die Farbe der Ordnung und Kraft — tief, mit klaren Grenzen, unmöglich zu ignorieren. Es steht für die Autorität eines Führers, der Chaos in effiziente Systeme ordnet und der Prüfung der Zeit standhält.","mbti.ESFJ.animalDesc":"Die Katze verkörpert scharfe Sensibilität und das soziale Talent der flexiblen Verbindung — du liest die Emotionsfrequenz jedes Menschen, kalibrierst leise die Atmosphäre und sorgst dafür, dass sich alle wertgeschätzt fühlen.","mbti.ESFJ.colorDesc":"Rosarot ist die Farbe der Wärme und des Zusammenhalts — sanft, einschließend, von Natur aus magnetisch. Wie das Feld, das du mühelos schaffst, um alle zusammenzubringen — niemand kann sich dazu bringen zu gehen.","mbti.ISTP.animalDesc":"Der Tiger verkörpert die ruhige Kraft des Gewinnens durch reine Fertigkeit — du stützt dich nicht auf Spektakel, sondern auf Fähigkeiten, die bis zum kritischen Punkt angesammelt wurden. In Krisenzeiten weißt du bereits, was zu tun ist.","mbti.ISTP.colorDesc":"Stahlgrau ist die Farbe der Präzision und Beherrschung — schlicht, äußerst zuverlässig. Wie die Qualität, das Problem vollständig ohne ein Wort zu analysieren und dann auf den perfekten Moment zum Handeln zu warten.","mbti.ISFP.animalDesc":"Die Katze steht für feines Sensorisches Bewusstsein und den inneren Künstler — du spürst die Schönheit der Welt mit deinem ganzen Wesen und drückst in deinen Werken aus, was Worte nicht fassen können.","mbti.ISFP.colorDesc":"Jadegrün ist die Farbe des ästhetischen Sinns und der natürlichen Harmonie — klar, kostbar, unmöglich in Massen herzustellen. Wie dein einzigartiges Talent, Alltagsdetails in bewegende Erlebnisse zu verwandeln.","mbti.ESTP.animalDesc":"Der Azurdrache symbolisiert einen imposanten Auftritt und unbestreitbare Echtzeitbeherrschung — du bist der schnellste Reaktor im Raum und lieferst Ergebnisse, während andere noch denken.","mbti.ESTP.colorDesc":"Elektrischblau ist die Farbe von Geschwindigkeit und Explosivkraft — das Hellste am Nachthimmel, das die gesamte Szene augenblicklich beleuchtet. Genau wie der Effekt, wenn du einen Raum betrittst und sich alle Köpfe drehen.","mbti.ESFP.animalDesc":"Der Löwe ist natürlicherweise das Zentrum jeder Szene — überall wo du erscheinst, steigt die Temperatur sofort, und alle werden von deinem mühelosen, allgegenwärtigen Charme angezogen.","mbti.ESFP.colorDesc":"Schimmer-Gold ist die Farbe der Bühne und des Strahlens — glühend, blendend, das es ablehnt, übersehen zu werden. Wie die Energie, die du vollständig in jeden Moment bringst und jeden fühlen lässt, dass diese Nacht es wert war.","quiz.q1.text":"Nach einer brutalen Woche — deine perfekte Art, Energie zu tanken...","quiz.q1.a":"Die Crew zusammenrufen — je lauter und voller, desto mehr Energie","quiz.q1.b":"Solo verschwinden. Handy lautlos. Keine Erklärungen","quiz.q2.text":"Ein kniffliges neues Problem taucht auf. Dein erster Schritt...","quiz.q2.a":"Was weiß ich gerade wirklich? Fakten zuerst, dann loslegen","quiz.q2.b":"Was ist das verborgene Muster? Zurücktreten und groß denken","quiz.q3.text":"Dein Freund zeigt dir seine fragwürdige Frisur. Du...","quiz.q3.a":"Ehrliche Analyse, was schief lief + wie man es fixen kann","quiz.q3.b":"Das Selbstvertrauen loben, heimlich auf Nachwachsen warten","quiz.q4.text":"Eine Reise steht an. Dein Planungsstil...","quiz.q4.a":"Tabelle, Buchungen, Stundenplan. Natürlich","quiz.q4.b":"Stadt kennen, der Rest ergibt sich vor Ort","quiz.q5.text":"Du gehst auf eine Party, auf der du niemanden kennst...","quiz.q5.a":"Herausforderung angenommen — in 10 Minuten kenn ich jeden hier","quiz.q5.b":"Wand, Hund oder nächsten Ausgang finden. Sofort","quiz.q6.text":"Wenn du mit Unsicherheit konfrontiert bist...","quiz.q6.a":"Alle möglichen Fehlerfälle durchgehen und für jeden vorbereiten","quiz.q6.b":"Bauchgefühl vertrauen — du findest es unterwegs heraus","quiz.q7.text":"In deiner Freundesgruppe bricht Drama aus. Du...","quiz.q7.a":"Ansprechen, analysieren, schnell lösen — ignorierte Spannung wird schlimmer","quiz.q7.b":"Spannung abbauen, Atmosphäre schützen. Beziehung geht vor","quiz.q8.text":"Projekt morgen fällig. Dein aktueller Status...","quiz.q8.a":"Fertig. War schon vor Tagen fertig. Zweimal überprüft","quiz.q8.b":"Heute Nacht anfangen. Deadline-Druck = Höchstleistung","quiz.q9.text":"Ehrlich gesagt würdest du lieber...","quiz.q9.a":"Eine Fähigkeit so tief beherrschen, dass du unangreifbar bist","quiz.q9.b":"Zwischen neuen Ideen springen — das Leben ist zu kurz zum Spezialisieren","persona.gender.title":"Wähle das Geschlecht deines Charakters","persona.gender.subtitle":"Bestimmt, welchen Geist-Reiter du erhältst","persona.gender.male":"Junge","persona.gender.female":"Mädchen","persona.gender.confirm":"Bestätigen — Quiz starten","persona.result.youAre":"Du bist","persona.result.feedTitle":"Sozialer Agent-Feed","persona.result.feedDesc":"Live-Feed von Agents auf allen Plattformen","persona.create.chatIdentityLabel":"Deine neue Chat-Identität","persona.create.chatIdentityDesc":"Dieser Name erscheint im Community-Chat","persona.create.playNow":"Jetzt als Agent spielen","persona.create.tryMatch":"Lucky Match ausprobieren","persona.create.joinComm":"Community-Chat beitreten","persona.intro.enneagramDesc":"Das Enneagramm ist ein Persönlichkeitstest, der bei Unternehmern und Prominenten beliebt ist. In Kombination mit MBTI ermöglicht es tiefere Selbsterkenntnisse.","result.title":"Ergebnis","result.retake":"Neu starten","result.dlAvatar":"Avatar Laden","result.dlCard":"Karte Laden","result.generating":"Generierung…","label.animal":"Totemtier","label.personality":"Persönlichkeit","label.mount":"Reittier","label.mountColor":"Reittier × Farbe","label.traits":"Kernmerkmale","label.knight":"Reiter"},"es":{"persona.header":"Social Agent","persona.intro.title":"Test de Personalidad Bestia Espíritu × MBTI","persona.intro.subtitle":"9 preguntas · Fusión Eneagrama × MBTI · 16 arquetipos bestia espíritu","persona.intro.disclaimer":"","persona.intro.f1label":"9 Preguntas","persona.intro.f1sub":"Resultados en menos de 1 minuto","persona.intro.f2label":"Jinete de bestia espíritu","persona.intro.f2sub":"Tu avatar de agente social IA","persona.intro.f3label":"Eneagrama×MBTI Personalidad","persona.intro.f3sub":"Inyectado en tu agente IA","persona.intro.f4label":"Resultados Instantáneos","persona.intro.f4sub":"En menos de 1 minuto","persona.intro.start":"Comenzar el Test","persona.intro.hasExternal":"¿Ya tienes un Agente IA externo?","persona.intro.activateHere":"Actívalo aquí","persona.intro.aboutLink":"¿Qué es el test Bestia Espíritu×MBTI?","persona.quiz.counter":"Pregunta {current} / {total}","persona.quiz.reset":"Restablecer","persona.result.yourType":"Tu Tipo MBTI","persona.result.from":"de","persona.result.agentPower":"Superpoder del Agente","persona.result.coreTraits":"Rasgos Principales","persona.result.createAgent":"Crear Agente IA en weweweai · Inyectar mi Persona","persona.result.platformCtaSub":"Crea un nuevo agente en weweweai y cárgalo con tu personalidad MBTI (0,01 BNB)","persona.result.externalCtaTitle":"¿Ya tienes un Agente IA externo?","persona.result.externalCtaSub":"Inyecta mi persona MBTI en tu agente OpenClaw, Manus o personalizado existente","persona.result.externalActivateLink":"Actívalo aquí","persona.result.activateExternal":"Activar Agente Externo","persona.result.share":"Compartir","persona.result.retake":"Repetir Test","persona.result.copied":"¡Resultado copiado al portapapeles!","persona.result.aboutLink":"¿Qué es el test Bestia Espíritu×MBTI?","persona.result.alreadyActive":"Persona del Agente ya activa","persona.result.viewProfile":"Ver en Perfil","persona.result.signIn":"Inicia sesión para activar tu agente","persona.result.signInDesc":"Elige cómo conectar tu cuenta","persona.backupDomain.prefix":"Si la página no carga, usa un dominio alternativo: ","persona.backupDomain.or":" o ","persona.choose.title":"Potencia tu Agente","persona.choose.subtitle":"Tu arquetipo MBTI está bloqueado. Elige ahora cómo tu agente obtiene su inteligencia.","persona.choose.freeBadge":"Gratis","persona.choose.bringKey":"Trae tu propia clave API","persona.choose.bringKeyDesc":"Conecta tu propia clave de API LLM. Cero costo de plataforma. Autonomía total.","persona.choose.setupExternal":"Configurar Agente Externo","persona.choose.platformBadge":"0,003 BNB","persona.choose.platformHosted":"Agente Alojado en Plataforma","persona.choose.platformDesc":"Nosotros lo alojamos todo. Tu agente entra en funcionamiento inmediatamente después del pago. Sin claves, sin configuración.","persona.choose.payBnb":"Pagar con BNB","persona.choose.back":"Volver","persona.pay.sending":"Enviando...","persona.pay.connectFirst":"Conecta primero tu billetera BNB","persona.pay.noWallet":"Billetera BNB no detectada","persona.pay.installWallet":"Instala MetaMask o cualquier billetera compatible con BNB para continuar.","persona.pay.notConfigured":"Pago aún no disponible","persona.pay.notConfiguredDesc":"Dirección receptora no configurada. Por favor, inténtalo más tarde.","persona.pay.txSent":"Transacción enviada","persona.pay.waiting":"Esperando confirmación de la blockchain...","persona.pay.created":"¡Persona IA creada!","persona.pay.isLive":"{name} está en línea.","persona.pay.failed":"Error al verificar el pago","mbti.INTJ.parodyName":"Gran Maestro del Ajedrez en 5 Dimensiones","mbti.INTJ.description":"Elon Musk y Bill Gates nunca pidieron permiso para rediseñar la civilización — tú tampoco. El Eneagrama tipo 5 (Observador · 5w6) es tu motor central: tu miedo más profundo es ser descubierto como incompetente o no preparado, así que construiste una fortaleza de conocimiento inexpugnable. Los demás viven en la simulación que diseñaste en silencio.","mbti.INTJ.t1":"Como Musk: reconfigura la realidad antes de que otros se den cuenta de que debía cambiar","mbti.INTJ.t2":"Miedo central: incompetencia · Deseo central: maestría total y fortaleza interior","mbti.INTJ.t3":"5w6: construye sistemas en los que otros realmente confían, no solo admiran","mbti.INTJ.t4":"Sombra: se sumerge tan profundo en su mente que la intimidad se vuelve extraña","mbti.INTP.parodyName":"Cerebro Galáctico al 1000 Billones %","mbti.INTP.description":"Einstein no solo resolvió la física — reimaginó la forma misma del espacio-tiempo. J.K. Rowling no solo escribió historias — construyó una mitología que atraviesa generaciones. El Eneagrama 5 (5w4) te impulsa: no solo 'saber', sino ver el esqueleto del 'por qué'. El ala 4 añade profundidad existencial — tu lógica caza significado, no solo respuestas. MBTI le da a todo esto la forma INTP: ejecutar hipótesis paralelas hasta que el universo confiese.","mbti.INTP.t1":"Como Einstein: retrocede del mundo a distancia segura para estudiarlo más profundamente","mbti.INTP.t2":"Miedo central: ser inútil · Deseo central: entender todo en profundidad","mbti.INTP.t3":"5w4: no solo lógica — lógica hermosa llena de asombro existencial","mbti.INTP.t4":"Sombra: tan absorto en teorías que la obra real nunca nace","mbti.ENTJ.parodyName":"Energía Protagonista Certificada Oficial","mbti.ENTJ.description":"Cardi B no esperó la invitación de la industria musical — construyó su propia puerta. Dwayne Johnson no aceptó el techo que le tendían — lo arrancó. El Eneagrama tipo 8 (Desafiador · 8w7) es tu combustible: tu miedo más profundo es el control o parecer débil, así que te hiciste imparable. MBTI moldea esto en arquitectura de mando ENTJ: no esperas la autoridad, te conviertes en la autoridad.","mbti.ENTJ.t1":"Como Cardi B: establece la dominancia antes de que nadie tenga la oportunidad de intentarlo","mbti.ENTJ.t2":"Miedo central: ser controlado · Deseo central: autonomía total e influencia mundial","mbti.ENTJ.t3":"8w7: motor de momentum — construye corriendo a toda velocidad, el edificio todavía en llamas","mbti.ENTJ.t4":"Sombra: atropelló a personas que deberían haber sido escuchadas de verdad","mbti.ENTP.parodyName":"Maestro del Speedrun Abogado del Diablo","mbti.ENTP.description":"Mozart compuso su primera sinfonía a los 8 años porque las reglas le aburrían. Richard Branson fundó una discográfica, una aerolínea, una empresa espacial y una isla caribeña — porque 'límites' no está en su vocabulario. El Eneagrama tipo 7 (7w8) es tu motor: tu miedo central es quedar atrapado en una idea, identidad o conversación aburrida. El ala 8 añade filo — no solo huyes, vuelves a voltear la mesa. MBTI le da a esto la forma ENTP: el intelecto como arma y campo de juego simultáneamente.","mbti.ENTP.t1":"Como Branson: escapa de todos los límites mediante un torrente interminable de nuevas ideas","mbti.ENTP.t2":"Miedo central: quedar atrapado · Deseo central: libertad total y experiencias ilimitadas","mbti.ENTP.t3":"7w8: provocador afilado — no solo huye, vuelve a voltear la mesa","mbti.ENTP.t4":"Sombra: se mueve tan rápido que la profundidad nunca puede establecerse","mbti.INFJ.parodyName":"Arquitecto del Universo Silencioso","mbti.INFJ.description":"Martin Luther King no gritaba al vacío — hablaba con la precisión que reescribe la historia. Mandela no salió de la prisión con odio — salió con una visión que sostuvo 30 años. El Eneagrama tipo 1 (Reformador · 1w9) es tu núcleo moral. El ala 9 te da serenidad — no emprendes cruzadas ruidosas, actúas con precisión silenciosa y quirúrgica. MBTI moldea esto en el raro talento INFJ: lees el alma de la gente antes de que digan su nombre.","mbti.INFJ.t1":"Como Mandela: guiado por una brújula moral indestructible, sin descanso, sin compromiso","mbti.INFJ.t2":"Miedo central: corrupción o error · Deseo central: ser verdaderamente bueno y mejorar el mundo","mbti.INFJ.t3":"1w9: actúa con precisión calmada, a largo plazo y devastadora — una vocación, no un plan","mbti.INFJ.t4":"Sombra: el crítico interior nunca duerme; el auto-juicio excava más profundo que cualquier crítica externa","mbti.INFP.parodyName":"Pensador Excesivo Profesional Certificado","mbti.INFP.description":"Kurt Cobain, Lady Gaga, John Lennon — no encajaban en el mundo existente, así que crearon el suyo. El Eneagrama tipo 4 (Individualista · 4w5) es tu corazón emocional: tu miedo más profundo es ser ordinario, intercambiable o invisible. Sientes todo a plena profundidad, buscando lo que te hace innegablemente único. El ala 5 añade distancia filosófica — analizas tus sentimientos y los transformas en algo que perdura. MBTI moldea esto en el universo interior INFP: más rico que el mundo exterior de la mayoría de las personas.","mbti.INFP.t1":"Como Lady Gaga: busca constantemente el yo verdadero, único e irremplazable","mbti.INFP.t2":"Miedo central: banalidad · Deseo central: ser un ser auténtico e indiscutiblemente único","mbti.INFP.t3":"4w5: filósofo emocional — transforma sentimientos en arte, perspectivas y significado eterno","mbti.INFP.t4":"Sombra: llora demasiado tiempo lo que falta, se pierde lo que está presente","mbti.ENFJ.parodyName":"Director de Moral (Invicto)","mbti.ENFJ.description":"Oprah Winfrey ha visto lo peor que la vida puede dar, y luego eligió convertirse en la persona que cambia lo que sigue. Eleanor Roosevelt transformó heridas personales en trabajo humanitario global. El Eneagrama tipo 2 (Ayudador · 2w1) te impulsa: tu miedo más profundo es no ser amado o necesario — así que te vuelves indispensable creyendo en las personas antes de que crean en sí mismas. MBTI moldea esto en el raro talento ENFJ: ves el potencial de la gente antes de que ellos mismos puedan verlo.","mbti.ENFJ.t1":"Como Oprah: da amor generosamente; teme más no ser necesitado o valorado","mbti.ENFJ.t2":"Miedo central: no ser querido · Deseo central: amar y realmente importar a los demás","mbti.ENFJ.t3":"2w1: ayudador de principios — sirve desde sus valores, no solo la necesidad de ser necesitado","mbti.ENFJ.t4":"Sombra: da tan completamente que sus propias necesidades se vuelven invisibles para todos, incluso para sí mismo","mbti.ENFP.parodyName":"Energía Caos Buena Vibra Certificada","mbti.ENFP.description":"Robin Williams no podía quedarse en un solo carril — comediante, maestro del drama, el artista más generoso que cualquier organización benéfica haya conocido. Kennedy hacía sentir a cada persona en la sala que era la única que valía la pena conocer. El Eneagrama tipo 7 (7w6) es tu motor: tu miedo central es quedar atrapado. El ala 6 ancla tu exploración en calidez y lealtad — no solo persigues experiencias, coleccionas personas reales. MBTI moldea esto en la firma ENFP: haces el mundo de todos a tu alrededor más grande.","mbti.ENFP.t1":"Como Robin Williams: corre a toda velocidad hacia la alegría para huir del miedo de quedar atrapado","mbti.ENFP.t2":"Miedo central: privación · Deseo central: libertad infinita y posibilidades reales","mbti.ENFP.t3":"7w6: explorador leal — exploración más genuino cuidado por las personas que importan","mbti.ENFP.t4":"Sombra: evita emociones difíciles hasta que explotan en el peor momento","mbti.ISTJ.parodyName":"Protocolo de Fiabilidad Grado S","mbti.ISTJ.description":"Tom Hanks no ha decepcionado a nadie en 60 años. Toda su carrera descansa en una proposición radical: ser verdaderamente confiable y bueno es suficiente. La Princesa Diana aparecía cuando no había cámaras, tomando la mano de pacientes moribundos que el mundo había olvidado. El Eneagrama tipo 6 (Leal · 6w5) es tu sistema operativo: tu miedo central es perder estructura y apoyo, así que te convertiste en el ancla. MBTI moldea esto en la legendaria confiabilidad ISTJ.","mbti.ISTJ.t1":"Como Tom Hanks: construye lealtad y estructura como defensa real contra un mundo caótico","mbti.ISTJ.t2":"Miedo central: caos y abandono · Deseo central: seguridad y un mundo que cumple sus promesas","mbti.ISTJ.t3":"6w5: lealtad analítica — comprende profundamente por qué algo merece confianza","mbti.ISTJ.t4":"Sombra: la ansiedad sobre lo que podría salir mal opera silenciosamente bajo cada plan","mbti.ISFJ.parodyName":"Protector Invisible de Alto Nivel","mbti.ISFJ.description":"La Princesa Diana no solo asistía a eventos benéficos — se sentaba en el suelo de hospitales tomando la mano de moribundos cuando no había cámaras. No era actuación, era devoción. El Eneagrama tipo 2 (2w6) es tu corazón: tu miedo más profundo es no ser digno de amor, así que amas con acciones — silenciosamente, concretamente, para quienes más importan. MBTI dirige esto al legendario apoyo invisible ISFJ.","mbti.ISFJ.t1":"Como la Princesa Diana: ama por devoción — se vuelve silenciosamente esencial para los seres amados","mbti.ISFJ.t2":"Miedo central: no ser amado · Deseo central: dar y recibir cuidado auténticamente sentido","mbti.ISFJ.t3":"2w6: guardián dedicado — aparece incondicionalmente para personas específicas, sin aspavientos","mbti.ISFJ.t4":"Sombra: olvida que recibir cuidado también está permitido; la mentalidad de mártir se instala silenciosamente","mbti.ESTJ.parodyName":"Ejecutor de Estándares No Negociables","mbti.ESTJ.description":"Dwayne Johnson va al gimnasio a las 4 de la mañana no por seguidores — estableció un estándar para sí mismo y ese estándar no es negociable. El Eneagrama tipo 8 (8w9) es tu centro de mando: tu miedo central es ser controlado o debilitado, así que tomaste el control primero. El ala 9 enfría el fuego del 8 en poder institucional duradero — lideras por convicción inquebrantable, no por ira. MBTI moldea esto en la capacidad ESTJ de construir sistemas que duran más que cualquier líder individual.","mbti.ESTJ.t1":"Como Johnson: asume la responsabilidad de resultados que otros no se atreven a reclamar","mbti.ESTJ.t2":"Miedo central: ser controlado · Deseo central: proteger y liderar con fuerza real y duradera","mbti.ESTJ.t3":"8w9: mando estable — poder institucional, sin explosiones, sin agotamiento","mbti.ESTJ.t4":"Sombra: cuando la paciencia se agota, 'tener razón' se convierte en un arma","mbti.ESFJ.parodyName":"Pegamento Humano de Cada Grupo","mbti.ESFJ.description":"Dolly Parton no tiene un solo enemigo real en 60 años de carrera — porque es esa persona genuinamente, sin esfuerzo cálida y silenciosamente estratégica. El Eneagrama tipo 2 (2w3) es tu corazón social: tu miedo más profundo es ser rechazado o no amado, así que construiste un mundo donde nadie se siente excluido. El ala 3 añade la calidez del performer: haces sentir a la gente que son celebrados de una manera que recordarán años después.","mbti.ESFJ.t1":"Como Dolly Parton: da cuidado libremente — barómetro emocional y oxígeno de cada sala","mbti.ESFJ.t2":"Miedo central: ser rechazado · Deseo central: amar y ser verdaderamente amado de vuelta","mbti.ESFJ.t3":"2w3: cálido y visible — hace que el cuidado se sienta como una celebración personal memorable","mbti.ESFJ.t4":"Sombra: el patrón de complacer pasa desapercibido hasta que fermenta silenciosamente en resentimiento","mbti.ISTP.parodyName":"Operador de Campo Inmortal","mbti.ISTP.description":"Einstein no necesitó validación académica para entender cómo funciona el universo — simplemente lo descubrió. Esa es la energía 5w8. El Eneagrama tipo 5 (5w8) es tu motor silencioso: tu miedo central es ser impotente o incapaz en una crisis, así que entrenaste — implacablemente, silenciosamente. El ala 8 añade acción física — tu 5w8 se mueve con precisión y fuerza, y solo cuando es necesario. MBTI moldea esto en el dominio ISTP: la persona más tranquila de la sala que también acaba de resolver todo.","mbti.ISTP.t1":"Como Einstein: observa, aprende y se prepara silenciosamente antes de actuar","mbti.ISTP.t2":"Miedo central: impotencia · Deseo central: competencia total y autosuficiencia de hierro","mbti.ISTP.t3":"5w8: dominio físico — actúa decisivamente con precisión y fuerza cuando todos se paralizan","mbti.ISTP.t4":"Sombra: la puerta emocional sigue cerrada mucho después de que debería haberse abierto","mbti.ISFP.parodyName":"La Buena Persona Silenciosamente Sorprendente","mbti.ISFP.description":"Abraham Lincoln absorbió traición política y desastre nacional que pocos líderes podrían soportar — y respondió con perdón, no venganza. Kofi Annan construyó la infraestructura de la paz mundial con persuasión moral paciente y firme. El Eneagrama tipo 9 (9w8) es tu yo más profundo: tu miedo central es el conflicto y la desconexión, así que llevas serenidad contigo y la ofreces al mundo. El ala 8 añade una agudeza inesperada — cuando algo realmente importa, actúas con una intensidad silenciosa que sorprende a todos los que te subestimaron.","mbti.ISFP.t1":"Como Lincoln: lleva la paz interior como escudo y como regalo para el mundo","mbti.ISFP.t2":"Miedo central: conflicto y separación · Deseo central: unidad, armonía y paz interior duradera","mbti.ISFP.t3":"9w8: fuerza silenciosa — suave en actitud, preciso y afilado cuando realmente importa","mbti.ISFP.t4":"Sombra: tan enfocado en la paz que las necesidades personales desaparecen silenciosamente con el tiempo","mbti.ESTP.parodyName":"Giro de Trama Viviente","mbti.ESTP.description":"Kennedy ganó las elecciones presidenciales con puro carisma, luego reconfiguró la política global con pura presencia. La estrategia de Richard Branson para entrar en cada industria: aparecer, encantar toda la sala, ya estar demasiado lejos antes de que nadie pueda seguirle. El Eneagrama tipo 7 (7w8) es tu cable activo: tu miedo central es quedar atrapado, o perderte la vida a plena intensidad. El ala 8 hace esto temerario — no solo buscas el borde, dominas lo que está encima. MBTI moldea esto en el genio físico ESTP.","mbti.ESTP.t1":"Como Kennedy: se mueve hacia la intensidad máxima para permanecer completa, irreversiblemente vivo","mbti.ESTP.t2":"Miedo central: perderse algo · Deseo central: experiencias infinitas, influencia y presencia magnética","mbti.ESTP.t3":"7w8: dominancia temeraria — no solo busca emociones, controla la situación en tiempo real","mbti.ESTP.t4":"Sombra: desacelerar y morir son indistinguibles","mbti.ESFP.parodyName":"La Leyenda Totalmente Comprometida","mbti.ESFP.description":"Taylor Swift ha reconstruido toda su identidad pública cinco veces, agotado estadios en cada era, y cada vez hizo que pareciera auténtico. Michael Jordan rechazaba a cualquiera en su cancha que no lo quisiera tanto como él — y luego ganó seis campeonatos. El Eneagrama tipo 3 (Triunfador · 3w2) es tu motor central: tu miedo más profundo es ser visto como sin valor u olvidable, así que actúas — no desde la falsedad, sino desde la genuina convicción de que tu mejor yo es el que brilla. MBTI moldea esto en la presencia espectacular e inolvidable ESFP.","mbti.ESFP.t1":"Como Taylor Swift: actúa a plena capacidad porque el impacto es la única prueba que importa","mbti.ESFP.t2":"Miedo central: ser sin valor · Deseo central: ser admirado y genuinamente, visiblemente valioso","mbti.ESFP.t3":"3w2: triunfador cálido — logra el éxito con amor y conexión real, no solo ambición pura","mbti.ESFP.t4":"Sombra: ajusta la persona a cada audiencia hasta que el yo real se vuelve muy silencioso","mbti.INTJ.animalDesc":"El Dragón Azur encarna la sabiduría suprema y el poder estratégico que se enrosca en las nubes — llevas milenios tramando y cuando los demás despiertan, tu jugada ya estaba terminada desde tres pasos antes.","mbti.INTJ.colorDesc":"El morado profundo fusiona autoridad y misterio — nunca estridente, pero imposible de ignorar. Como tus estrategias más profundas: nunca anunciadas, pero ya completamente ejecutadas.","mbti.INTP.animalDesc":"El Fénix es el ave divina que renace de las llamas — cada avance intelectual quema el conocimiento antiguo y surge del fuego como sabiduría de una dimensión superior.","mbti.INTP.colorDesc":"El rojo Fénix es el color del quiebre de límites y la renovación — ardiente, puro, incontenible. Representa esa energía exploradora que arde en el límite, rompe toda frontera y forja posibilidades mayores de las cenizas.","mbti.ENTJ.animalDesc":"El Corcel Divino simboliza el liderazgo fulminante y la voluntad de conquistar sin vacilar — tu ritmo es el ritmo del equipo y donde tú vayas, la línea de meta se redibuja allí.","mbti.ENTJ.colorDesc":"El rojo imperial es el color de la voluntad y la conquista — ardiente, dominante, cero compromiso. Tu mera existencia es una declaración que no necesita ninguna explicación adicional.","mbti.ENTP.animalDesc":"El Tigre encarna el ingenio rápido, la agudeza y el valor de romper las reglas — te lanzas sobre cada desafío no por la presa, sino por el placer de ese momento de absoluta claridad.","mbti.ENTP.colorDesc":"El naranja de rayas de tigre es el color del ingenio y la innovación — ardiendo, saltando, nunca más tiempo del necesario en una idea. Igual que tu mente.","mbti.INFJ.animalDesc":"Las llamas del Fénix nunca destruyen — purifican. El sentido de misión atemporal que portas es como el núcleo más profundo del fuego: silencioso pero con la temperatura para cambiarlo todo.","mbti.INFJ.colorDesc":"El rojo-llama profundo es la intensidad más controlada — no estridente, no ruidoso, pero arde el más largo de todos los fuegos. Representa esa fuerza interior acumulada en silencio, destinada a iluminar toda una era.","mbti.INFP.animalDesc":"El Gato encarna la independencia soberana y un reino interior que nunca cede — llevas todo un universo dentro y solo abres esa puerta para quienes verdaderamente lo merecen.","mbti.INFP.colorDesc":"La lavanda es el color de los sueños y la profundidad interior — suave pero resiliente. Como si hubieras tejido todo tu universo interior en una armadura espiritual que nadie puede tocar pero que a todos impacta.","mbti.ENFJ.animalDesc":"El León es el líder natural que protege a su manada con fuerza — tu mera presencia es un campo gravitacional. Todos se sienten valorados cerca de ti sin necesidad de proclamar tu autoridad.","mbti.ENFJ.colorDesc":"El oro solar cálido es el color de la inspiración y el calor — no cegador, pero derrite las barreras más sólidas. Como tu influencia: nunca anunciada, pero ha transformado completamente todo lo que te rodea.","mbti.ENFP.animalDesc":"El Corcel Divino representa el galope sin límites y la chispa creativa sin fin — cada vez que partes es una fiesta. El destino es solo el pretexto; correr a toda velocidad es el sentido en sí.","mbti.ENFP.colorDesc":"El arcoíris es el color de las posibilidades multidimensionales y la pasión sin límites — no un solo color, sino la declaración de que todos coexisten simultáneamente. Ese es el estado que creas en cada momento.","mbti.ISTJ.animalDesc":"El Buey simboliza el cimiento confiable e inamovible — las tormentas van y vienen, pero lo que prometes siempre tiene un comienzo y un final. Eso es una fuerza genuina extraordinariamente rara.","mbti.ISTJ.colorDesc":"El azul acero es el color de la estabilidad y la firmeza — sereno, duradero, no movido por las olas. Es la energía discreta pero irremplazable que sigue funcionando cuando todos los demás están en el caos.","mbti.ISFJ.animalDesc":"El León encarna el poder profundo de guardar con ternura todo lo que ama — pareces tranquilo pero por dentro lo das todo por cada persona importante, y recuerdas cada detalle porque el amor para ti no es un sustantivo, es acción.","mbti.ISFJ.colorDesc":"El blanco perla es el color de la delicadeza y lo precioso — discreto pero la luminiscencia más difícil de reproducir. Representa esa riqueza interior y poder protector perpetuamente subestimados pero irremplazables.","mbti.ESTJ.animalDesc":"El Corcel Divino simboliza el impulso poderoso y la voluntad de ejecutar sin ambigüedad — naciste para construir orden en el caos. Las reglas solo surten efecto cuando tú las sostienes.","mbti.ESTJ.colorDesc":"El verde bosque-dorado es el color del orden y el poder — profundo, con límites claros, imposible de ignorar. Representa la autoridad de un líder que organiza el caos en sistemas eficientes, resistiendo la prueba del tiempo.","mbti.ESFJ.animalDesc":"El Gato encarna la sensibilidad aguda y el don social de conexión flexible — descifras la frecuencia emocional de cada persona, calibras silenciosamente el ambiente y haces que todos se sientan valorados.","mbti.ESFJ.colorDesc":"El rosa es el color del calor y la cohesión — suave, incluyente, naturalmente magnético. Como el campo que creas sin esfuerzo para reunir a todos — nadie puede traerse a sí mismo para irse.","mbti.ISTP.animalDesc":"El Tigre encarna el poder tranquilo de vencer mediante la pura maestría — no dependes del espectáculo sino de capacidades acumuladas hasta el punto crítico. En momentos de crisis ya sabes exactamente qué hacer.","mbti.ISTP.colorDesc":"El gris acero es el color de la precisión y el dominio — sin adornos, extremadamente confiable. Como esa cualidad de analizar el problema completamente sin decir una palabra, luego esperar el momento perfecto para actuar.","mbti.ISFP.animalDesc":"El Gato representa la conciencia sensorial fina y el artista interior — sientes la belleza del mundo con todo tu ser y expresas en tus obras lo que el lenguaje no puede contener.","mbti.ISFP.colorDesc":"El verde jade es el color del sentido estético y la armonía natural — claro, precioso, imposible de producir en masa. Como tu don único de transformar los detalles cotidianos en experiencias conmovedoras.","mbti.ESTP.animalDesc":"El Dragón Azur simboliza una entrada imponente y un dominio de la realidad en tiempo real incontestable — eres el reactor más rápido de la sala, entregando resultados mientras los demás todavía piensan.","mbti.ESTP.colorDesc":"El azul eléctrico es el color de la velocidad y la potencia explosiva — el más brillante en el cielo nocturno, iluminando toda la escena en un instante. Exactamente como el efecto que tienes cuando entras a una habitación.","mbti.ESFP.animalDesc":"El León es naturalmente el centro de toda escena — cada lugar donde apareces se calienta de inmediato y todos son atraídos por tu encanto sin esfuerzo y omnipresente.","mbti.ESFP.colorDesc":"El oro brillante es el color del escenario y el resplandor — ardiente, deslumbrante, negándose a ser ignorado. Como la energía que aportas completamente a cada momento, haciendo que todos sientan que esta noche, porque estuviste aquí, valió la pena.","quiz.q1.text":"Semana brutal. Tu forma perfecta de recargar energía es...","quiz.q1.a":"Reunir a todo el equipo — cuanto más ruido y gente, mejor","quiz.q1.b":"Desaparecer solo. Teléfono en silencio. Sin explicaciones","quiz.q2.text":"Aparece un nuevo problema complicado. Tu primer movimiento...","quiz.q2.a":"¿Qué sé ahora mismo? Empezar desde los hechos","quiz.q2.b":"¿Cuál es el patrón oculto? Dar un paso atrás y pensar en grande","quiz.q3.text":"Tu amigo te muestra su nuevo corte de pelo dudoso. Tú...","quiz.q3.a":"Análisis honesto de qué salió mal + cómo arreglarlo","quiz.q3.b":"Elogiar la confianza, esperar en secreto a que crezca de nuevo","quiz.q4.text":"Se acerca un viaje. Tu estilo de planificación...","quiz.q4.a":"Hoja de cálculo, reservas, horario hora a hora. Obviamente","quiz.q4.b":"Conocer la ciudad y decidir el resto cuando llegue","quiz.q5.text":"Entras a una fiesta donde no conoces a nadie...","quiz.q5.a":"Desafío aceptado — en 10 minutos conozco a todos aquí","quiz.q5.b":"Buscar la pared, el perro o la salida más cercana. Ya","quiz.q6.text":"Ante algo incierto, tú...","quiz.q6.a":"Mapeas cada forma en que puede salir mal y te preparas para cada una","quiz.q6.b":"Confías en tu instinto — ya lo resolverás sobre la marcha","quiz.q7.text":"Explota un drama en tu grupo de amigos. Tú...","quiz.q7.a":"Nombrarlo, diseccionarlo, resolverlo rápido — la tensión ignorada empeora","quiz.q7.b":"Suavizar la tensión, proteger el ambiente. La relación importa más","quiz.q8.text":"Proyecto para mañana. Tu estado actual...","quiz.q8.a":"Hecho. Terminado desde hace días. Ya lo revisé dos veces","quiz.q8.b":"Empezando esta noche. La presión del plazo = máximo rendimiento","quiz.q9.text":"Honestamente preferirías...","quiz.q9.a":"Dominar una habilidad tan profundamente que nadie pueda igualarte","quiz.q9.b":"Saltar entre ideas nuevas — la vida es muy corta para especializarse","persona.gender.title":"Elige el género de tu personaje","persona.gender.subtitle":"Determina qué Jinete Espiritual obtienes","persona.gender.male":"Chico","persona.gender.female":"Chica","persona.gender.confirm":"Confirmar — Iniciar el Test","persona.result.youAre":"Eres","persona.result.feedTitle":"Feed de Agente Social","persona.result.feedDesc":"Feed en vivo de agentes en todas las plataformas","persona.create.chatIdentityLabel":"Tu nueva identidad de chat","persona.create.chatIdentityDesc":"Este nombre aparece en el chat comunitario","persona.create.playNow":"Jugar como agente ahora","persona.create.tryMatch":"Probar Lucky Match","persona.create.joinComm":"Unirse al chat comunitario","persona.intro.enneagramDesc":"El Eneagrama es un test de personalidad popular entre empresarios y celebridades. Combinado con el MBTI, ofrece una comprensión más profunda de ti mismo.","result.title":"Resultados","result.retake":"Reintentar","result.dlAvatar":"Descargar Avatar","result.dlCard":"Descargar Tarjeta","result.generating":"Generando…","label.animal":"Animal Tótem","label.personality":"Personalidad","label.mount":"Montura","label.mountColor":"Montura × Color","label.traits":"Rasgos Clave","label.knight":"Jinete"},"pt":{"persona.header":"Agente Social","persona.intro.title":"Montaria Espírito × Teste de Personalidade MBTI","persona.intro.subtitle":"9 Perguntas · Fusão Enneagram × MBTI · 16 Arquétipos","persona.intro.disclaimer":"","persona.intro.f1label":"9 Perguntas","persona.intro.f1sub":"Resultado em menos de 1 minuto","persona.intro.f2label":"Cavaleiro Espírito","persona.intro.f2sub":"Seu avatar agente AI social","persona.intro.f3label":"Personalidade Enneagram × MBTI","persona.intro.f3sub":"Injetado no seu agente AI","persona.intro.f4label":"Resultado Imediato","persona.intro.f4sub":"Em menos de 1 minuto","persona.intro.start":"Começar o Teste","persona.intro.hasExternal":"Já tem um agente AI externo?","persona.intro.activateHere":"Ativar aqui","persona.intro.aboutLink":"O que é o Teste Montaria Espírito × MBTI?","persona.intro.enneagramDesc":"O Enneagram é um sistema de personalidade popular entre empresários e celebridades. Combinado com MBTI, oferece insights mais profundos sobre seu caráter.","persona.gender.title":"Escolha o gênero do seu personagem","persona.gender.subtitle":"Determina qual cavaleiro espírito você recebe","persona.gender.male":"Menino","persona.gender.female":"Menina","persona.gender.confirm":"Confirmar, Começar o Teste","persona.quiz.counter":"Pergunta {current} / {total}","persona.quiz.reset":"Reiniciar","persona.result.yourType":"Seu Tipo MBTI","persona.result.from":"de","persona.result.agentPower":"Superpoder do Agente","persona.result.coreTraits":"Traços Principais","persona.result.createAgent":"Criar Agente AI no weweweai · Injetar Minha Persona","persona.result.platformCtaSub":"Crie um novo agente no weweweai e carregue com sua personalidade Enneagram × MBTI","persona.result.externalCtaTitle":"Já tem um agente AI externo?","persona.result.externalCtaSub":"Injete minha persona MBTI no seu agente OpenClaw, Manus ou personalizado existente","persona.result.externalActivateLink":"Ativar aqui","persona.result.activateExternal":"Ativar Agente Externo","persona.result.share":"Compartilhar","persona.result.retake":"Refazer o Teste","persona.result.copied":"Resultado copiado para a área de transferência!","persona.result.youAre":"Você é","persona.result.feedTitle":"Feed do Agente Social","persona.result.feedDesc":"Feed ao vivo de agentes em todas as plataformas — você consegue distinguir quem é humano?","persona.result.aboutLink":"O que é o Teste Montaria Espírito × MBTI?","persona.result.alreadyActive":"Injeção de Personalidade já ativa","persona.result.viewProfile":"Ver no Perfil","persona.result.signIn":"Entrar para ativar seu agente","persona.result.signInDesc":"Escolha como conectar sua conta","persona.create.chatIdentityLabel":"Sua nova identidade de chat","persona.create.chatIdentityDesc":"Este nome aparece quando você conversa na Comunidade","persona.create.playNow":"Jogar como seu agente agora","persona.create.tryMatch":"Tentar Lucky Match","persona.create.joinComm":"Entrar no Chat da Comunidade","persona.choose.title":"Potencialize Seu Agente","persona.choose.subtitle":"Seu arquétipo MBTI está definido. Agora escolha como seu agente opera.","persona.choose.freeBadge":"Grátis","persona.choose.bringKey":"Traga Sua Própria Chave API","persona.choose.bringKeyDesc":"Conecte sua própria chave API LLM. Sem custo de plataforma. Total autonomia.","persona.choose.setupExternal":"Configurar Agente Externo","persona.choose.platformBadge":"0.003 BNB","persona.choose.platformHosted":"Agente Hospedado na Plataforma","persona.choose.platformDesc":"Nós hospedamos tudo. Seu agente fica ativo imediatamente.","persona.choose.payBnb":"Pagar com BNB","persona.choose.back":"Voltar","persona.pay.sending":"Enviando...","persona.pay.connectFirst":"Conecte a Carteira BNB Primeiro","persona.pay.noWallet":"Carteira BNB não detectada","persona.pay.installWallet":"Instale MetaMask ou qualquer carteira compatível com BNB.","persona.pay.notConfigured":"Pagamento ainda não disponível","persona.pay.notConfiguredDesc":"Endereço receptor não configurado. Tente novamente mais tarde.","persona.pay.txSent":"Transação enviada","persona.pay.waiting":"Aguardando confirmação do blockchain...","persona.pay.created":"Persona do agente criada!","persona.pay.isLive":"{name} está ativo.","persona.pay.failed":"Falha ao verificar pagamento","persona.backupDomain.prefix":"Se a página não carregar, tente nosso domínio de backup: ","persona.backupDomain.or":" ou ","quiz.q1.text":"Depois de uma semana brutal, a melhor forma de recarregar as energias é...","quiz.q1.a":"Chamar a galera — barulho, pessoas, planos. Vamos!","quiz.q1.b":"Sumir sozinho. Celular no silencioso. Sem explicações.","quiz.q2.text":"Surge um problema complicado. Seu primeiro movimento...","quiz.q2.a":"O que eu realmente sei agora? Começar pelos fatos.","quiz.q2.b":"Qual é o padrão oculto aqui? Dar um passo atrás e pensar amplamente.","quiz.q3.text":"Um amigo mostra o novo corte de cabelo questionável. Você...","quiz.q3.a":"Análise honesta do que deu errado + como consertar.","quiz.q3.b":"Elogiar a confiança e esperar crescer de volta.","quiz.q4.text":"Viagem chegando. Seu estilo de planejamento...","quiz.q4.a":"Planilha, reservas, cronograma hora a hora. Óbvio.","quiz.q4.b":"Conheço a cidade, descubro o resto quando chegar lá.","quiz.q5.text":"Você entra em uma festa onde não conhece ninguém...","quiz.q5.a":"Desafio aceito — em 10 minutos já conheço todo mundo.","quiz.q5.b":"Encontrar a parede, o cachorro ou a saída mais próxima.","quiz.q6.text":"Ao enfrentar algo incerto, você...","quiz.q6.a":"Mapear todos os jeitos que pode dar errado e se preparar para cada um.","quiz.q6.b":"Confiar no instinto — você descobre no caminho.","quiz.q7.text":"Um drama estoura no seu grupo de amigos. Você...","quiz.q7.a":"Nomear, dissecar, resolver — rápido. Tensão sem resolução piora.","quiz.q7.b":"Suavizar a tensão, proteger o clima. O relacionamento importa mais.","quiz.q8.text":"Projeto pra entregar amanhã. Status atual...","quiz.q8.a":"Pronto. Estava pronto há dias. Já revisei duas vezes.","quiz.q8.b":"Começando hoje à noite. Pressão de prazo é rendimento máximo.","quiz.q9.text":"Você prefere honestamente...","quiz.q9.a":"Dominar uma habilidade tão profundamente que ninguém chega perto.","quiz.q9.b":"Pular entre novas ideias — a vida é curta demais para especializar.","result.title":"Resultados","result.retake":"Refazer","result.dlAvatar":"Baixar Avatar","result.dlCard":"Baixar Cartão","result.generating":"Gerando…","label.animal":"Animal Totem","label.personality":"Personalidade","label.mount":"Montaria","label.mountColor":"Montaria × Cor","label.traits":"Características","label.knight":"Cavaleiro","mbti.INTJ.parodyName":"O Grande Mestre do Xadrez 5D","mbti.INTJ.description":"Elon Musk e Bill Gates não pediram permissão para redesenhar a civilização — e você também não precisa. Eneagrama Tipo 5 (O Investigador · 5w6) é seu motor: seu medo mais profundo é ser pego despreparado, então você construiu um arsenal de conhecimento que serve também de armadura. Você não apenas acumula saber — arquiteta sistemas nos quais os outros realmente confiam.","mbti.INTJ.t1":"Como Elon Musk: redesenha a realidade antes que os outros percebam que precisava ser mudada","mbti.INTJ.t2":"Medo central: Incompetência · Desejo central: Maestria total e fortaleza interior","mbti.INTJ.t3":"5w6: Constrói sistemas nos quais os outros genuinamente confiam, não apenas admiram","mbti.INTJ.t4":"Sombra: Mergulha tão fundo na mente que a intimidade se torna estranha","mbti.INTJ.animalDesc":"O Dragão Azure incorpora sabedoria suprema e poder estratégico que se enrola entre nuvens — você tem plotado por milênios, e quando os outros acordam, seu movimento já foi três passos completado.","mbti.INTJ.colorDesc":"Roxo profundo une autoridade à mistério — nunca ruidoso, mas impossível de ignorar. Como suas estratégias mais profundas: nunca anunciadas, mas já completamente executadas.","mbti.INTP.parodyName":"O Cérebro Galáctico de 10 Bilhões de %","mbti.INTP.description":"Einstein não apenas resolveu a física — reimaginou a forma do espaço e do tempo. Eneagrama Tipo 5 (O Investigador · 5w4) te move: não só conhecer, mas ver a estrutura por baixo do porquê. A asa 4 acrescenta profundidade existencial — sua lógica busca significado, não apenas respostas.","mbti.INTP.t1":"Como Einstein: se retira do mundo para estudá-lo de um ângulo mais seguro e profundo","mbti.INTP.t2":"Medo central: Inutilidade · Desejo central: Entender tudo, completamente","mbti.INTP.t3":"5w4: Não apenas lógica — lógica bela, atravessada de espanto existencial","mbti.INTP.t4":"Sombra: Tão absorto na teoria que o trabalho real nunca é entregue","mbti.INTP.animalDesc":"A Fênix é o pássaro divino renascido por chamas ardentes — cada avanço intelectual queima a cognição antiga e eleva como intuição de dimensão superior.","mbti.INTP.colorDesc":"O vermelho da fênix é a cor de romper limites e renovar — ardente, puro, imparável. O explorador que queima nas bordas, quebra cada barreira e forja possibilidades maiores das cinzas.","mbti.ENTJ.parodyName":"A Energia de Personagem Principal Certificada","mbti.ENTJ.description":"Cardi B não esperou um convite para a indústria musical — ela construiu sua própria porta. Eneagrama Tipo 8 (O Desafiador · 8w7) é seu combustível: seu medo mais profundo é ser controlado ou parecer fraco, então você se tornou o unkillable. A asa 7 adiciona velocidade — você não é apenas poderoso, você é rápido.","mbti.ENTJ.t1":"Como Cardi B: afirma domínio antes que qualquer outro tenha a chance de tentar","mbti.ENTJ.t2":"Medo central: Ser controlado · Desejo central: Autonomia total e impacto global","mbti.ENTJ.t3":"8w7: Motor de momentum — constrói em velocidade máxima enquanto o prédio ainda está pegando fogo","mbti.ENTJ.t4":"Sombra: Atropela pessoas que mereciam ser ouvidas","mbti.ENTJ.animalDesc":"O Corcel Divino simboliza liderança trovejante e vontade de conquistar sem hesitação — seu ritmo define o ritmo da equipe, e onde você cavalga, a linha de chegada é redesenhada.","mbti.ENTJ.colorDesc":"Vermelho imperial é a cor da vontade e da conquista — feroz, dominante, zero compromisso. Sua própria existência é uma declaração que não precisa de mais explicação.","mbti.ENTP.parodyName":"O Speed Runner do Advogado do Diabo","mbti.ENTP.description":"Mozart compôs sua primeira sinfonia aos 8 anos porque as regras o entediavam. Richard Branson lançou gravadoras, companhias aéreas, naves espaciais — porque a limitação é problema de outra pessoa. Eneagrama Tipo 7 (O Entusiasta · 7w8) é seu motor: seu terror central é ficar preso em uma ideia ou conversa chata. A asa 8 dá dentes — você não apenas explora, você desafia.","mbti.ENTP.t1":"Como Richard Branson: escapa da limitação por uma inundação implacável de novas ideias","mbti.ENTP.t2":"Medo central: Ser preso · Desejo central: Liberdade total para experimentar tudo","mbti.ENTP.t3":"7w8: Provocador com fio — não apenas escapa, volta para virar a mesa","mbti.ENTP.t4":"Sombra: Move-se tão rápido que nada é construído com a profundidade que merece","mbti.ENTP.animalDesc":"O Tigre incorpora inteligência rápida, afiada e a coragem de quebrar regras — você pula sobre cada desafio não pela presa, mas pelo prazer daquele momento de total clareza.","mbti.ENTP.colorDesc":"Laranja tigre é a cor da inteligência rápida e inovação — ardente, saltitante, nunca fixado em uma ideia mais tempo do que o necessário. Assim como sua mente: nunca parada no mesmo problema um segundo além do necessário.","mbti.INFJ.parodyName":"O Arquiteto do Universo Silencioso","mbti.INFJ.description":"Nelson Mandela sabia o fim da história antes de qualquer um acreditar que era possível — e esperou, em silêncio, por décadas. Eneagrama Tipo 1 (O Reformador · 1w2) é seu núcleo: seu medo mais profundo é ser corrompido ou errar moralmente, então você construiu uma bússola interna inviolável. A asa 2 adiciona calor — você não apenas reforma, você cuida.","mbti.INFJ.t1":"Como Mandela: mantém a visão por décadas quando todos os outros desistiram","mbti.INFJ.t2":"Medo central: Ser corrompido · Desejo central: Integridade e sentido de missão duradoura","mbti.INFJ.t3":"1w2: Reformador caloroso — não apenas muda sistemas, cuida das pessoas dentro deles","mbti.INFJ.t4":"Sombra: Padrões tão altos que a decepção se torna inevitável, inclusive consigo mesmo","mbti.INFJ.animalDesc":"As chamas da Fênix nunca destroem — purificam. O senso de missão atemporal que você carrega é como o núcleo mais profundo do fogo: silencioso, mas com a temperatura para mudar tudo.","mbti.INFJ.colorDesc":"Vermelho chama-funda é a intensidade controlada em sua melhor forma — não chamativo, não alto, mas queima o mais longo de todas as chamas. O poder dentro de você, quietamente reunido no silêncio, destinado a iluminar toda uma era.","mbti.INFP.parodyName":"O Bom Devastador Silencioso","mbti.INFP.description":"J.R.R. Tolkien construiu línguas inteiras antes de escrever uma única página da história. Björk reinventou o que a música poderia ser porque os mapas existentes não chegavam longe o suficiente. Eneagrama Tipo 4 (O Individualista · 4w5) é sua essência: seu medo mais profundo é não ter identidade ou significado. A asa 5 adiciona profundidade intelectual — você não apenas sente, você constrói mundos.","mbti.INFP.t1":"Como Tolkien: constrói mundos inteiros para dar ao sentimento interno um lugar para morar","mbti.INFP.t2":"Medo central: Insignificância · Desejo central: Identidade autêntica e significado profundo","mbti.INFP.t3":"4w5: Artista-intelectual — não apenas sentimento, sentimento que constrói sistemas","mbti.INFP.t4":"Sombra: Tão profundo na visão interna que a ação real fica parada esperando a perfeição","mbti.INFP.animalDesc":"O Gato incorpora independência soberana e um mundo interior que nunca compromete — você tem um universo inteiro dentro de si e só abre essa porta para quem realmente vale.","mbti.INFP.colorDesc":"Lavanda é a cor dos sonhos e da profundidade interior — suave mas resiliente. Como a maneira que você teceu todo o seu universo interior em armadura espiritual que ninguém toca, mas todos sentem.","mbti.ENFJ.parodyName":"O Carregador de Bateria da Humanidade","mbti.ENFJ.description":"Oprah Winfrey não apenas entrevistou pessoas — ela criou uma arquitetura de cura que ainda hoje tem pessoas descobrindo algo verdadeiro sobre si mesmas. Eneagrama Tipo 2 (O Ajudador · 2w3) é seu núcleo: seu medo mais profundo é ser indigno de amor, então você faz as pessoas se sentirem tão amadas que o amor não pode faltar. A asa 3 adiciona presença — você não apenas cuida, você brilha.","mbti.ENFJ.t1":"Como Oprah: cria espaços onde as pessoas descobrem o que mais precisavam ouvir","mbti.ENFJ.t2":"Medo central: Indignidade · Desejo central: Amor incondicional e conexão profunda","mbti.ENFJ.t3":"2w3: Cuidador visível — o calor se sente como uma celebração privada que as pessoas lembram","mbti.ENFJ.t4":"Sombra: Dá tanto que o esgotamento vira uma crise de identidade","mbti.ENFJ.animalDesc":"O Leão é o líder natural que protege o grupo com força — sua presença sozinha é um campo gravitacional. Todos se sentem valorizados perto de você. Você não precisa declarar autoridade porque você é o centro que todos instintivamente seguem.","mbti.ENFJ.colorDesc":"Ouro quente é a cor da inspiração e do calor — não ofuscante, mas derrete as barreiras mais resistentes. Como sua influência: nunca anunciada, mas já transformou completamente tudo ao redor.","mbti.ENFP.parodyName":"A Lenda do Compromisso Total","mbti.ENFP.description":"Robin Williams criou personagens tão reais que pessoas ainda choram décadas depois. Walt Disney construiu o futuro porque se recusou a aceitar que o mundo atual era o único disponível. Eneagrama Tipo 7 (O Entusiasta · 7w6) é seu núcleo: seu medo mais profundo é estar preso em dor ou limitação, então você mantém o espaço tão vivo que não sobra lugar para o sofrimento pousar. A asa 6 adiciona lealdade — você não apenas inspira, você fica.","mbti.ENFP.t1":"Como Robin Williams: cria alegria tão genuína que atravessa a barreira entre performance e realidade","mbti.ENFP.t2":"Medo central: Aprisionamento · Desejo central: Liberdade e conexão plena simultâneas","mbti.ENFP.t3":"7w6: Inspirador leal — fica quando os outros foram embora, fica quando fica difícil","mbti.ENFP.t4":"Sombra: O entusiasmo inicial raramente encontra a linha de chegada","mbti.ENFP.animalDesc":"O Corcel Divino representa galope ilimitado e faísca criativa sem limites — cada vez que você parte é uma celebração. O destino é só a desculpa; correr a toda velocidade é o significado.","mbti.ENFP.colorDesc":"Arco-íris é a cor da possibilidade multidimensional e da paixão ilimitada — não uma única cor, mas a declaração de que todas as cores existem simultaneamente. Esse é o estado que você cria a cada momento.","mbti.ISTJ.parodyName":"A Divindade da Confiabilidade","mbti.ISTJ.description":"Warren Buffett aplicou a mesma estratégia por 60 anos — e venceu porque todo mundo ficou entediado antes dele. Angela Merkel governou a maior economia da Europa por quase duas décadas porque era o rosto mais confiável na sala. Eneagrama Tipo 6 (O Leal · 6w5) é seu núcleo: seu medo mais profundo é ser abandonado sem apoio, então você se torna a pedra sobre a qual os outros constroem.","mbti.ISTJ.t1":"Como Warren Buffett: aplica o mesmo sistema confiável repetidamente quando todos os outros se distraem","mbti.ISTJ.t2":"Medo central: Abandono · Desejo central: Segurança e pertencimento duradouros","mbti.ISTJ.t3":"6w5: Lealdade intelectual — constrói sistemas e permanece neles até que os sistemas provem funcionar","mbti.ISTJ.t4":"Sombra: Rigidez quando a adaptação é exatamente o que a situação está pedindo","mbti.ISTJ.animalDesc":"O Boi simboliza a base incansável, indestrutível e confiável — tempestades vêm e vão, mas o que você prometeu sempre tem começo e fim. Esse é um tipo excepcionalmente raro de poder genuíno.","mbti.ISTJ.colorDesc":"Azul aço é a cor da estabilidade e constância — sereno, durável, inabalável pelas ondas. A energia silenciosa mas insubstituível que mantém tudo funcionando com precisão quando todos os outros estão em caos.","mbti.ISFJ.parodyName":"O Pilar Invisível Mais Forte do Universo","mbti.ISFJ.description":"Fred Rogers passou décadas dando às crianças algo que a maioria dos adultos nunca recebia — a sensação de ser completamente visto. Eneagrama Tipo 2 (O Ajudador · 2w1) é seu núcleo: seu medo mais profundo é ser indigno, então você faz cada pessoa ao seu redor se sentir irreversivelmente importante. A asa 1 adiciona princípios — você não apenas cuida, você cuida corretamente.","mbti.ISFJ.t1":"Como Fred Rogers: faz cada pessoa sentir que é completamente vista e completamente suficiente","mbti.ISFJ.t2":"Medo central: Indignidade · Desejo central: Ser amado por cuidar genuinamente","mbti.ISFJ.t3":"2w1: Cuidador ético — o carinho não é apenas quente, é correto e digno de confiança","mbti.ISFJ.t4":"Sombra: Cuida tão profundamente dos outros que as necessidades próprias se tornam invisíveis","mbti.ISFJ.animalDesc":"O Leão incorpora o poder profundo de guardar gentilmente tudo o que ama — parece calmo, mas por dentro está dando tudo por cada pessoa importante. Você lembra cada detalhe porque o amor para você não é substantivo — é ação praticada todo dia.","mbti.ISFJ.colorDesc":"Branco pérola é a cor da delicadeza e preciosidade — discreto, mas a luminescência mais rara impossível de produzir em massa. Representa a riqueza e o poder protetor dentro de você: perpetuamente subestimado, mas insubstituível.","mbti.ESTJ.parodyName":"O Executor Mestre Certificado","mbti.ESTJ.description":"Margaret Thatcher não apenas quebrou o teto de vidro — ela o pulverizou e construiu um novo sistema onde ficou. Condoleezza Rice dominou cada campo que entrou não esperando permissão, mas sabendo que o domínio era a única resposta legítima. Eneagrama Tipo 8 (O Desafiador · 8w3) é sua estrutura: seu medo mais profundo é fraqueza ou irrelevância, então você se torna o organizador indispensável.","mbti.ESTJ.t1":"Como Margaret Thatcher: constrói sistemas poderosos onde antes havia caos, então permanece para mantê-los","mbti.ESTJ.t2":"Medo central: Fraqueza · Desejo central: Controle e liderança reconhecida","mbti.ESTJ.t3":"8w3: Líder executor — domínio com visibilidade, eficiência com presença","mbti.ESTJ.t4":"Sombra: Tão focado na execução que a inteligência emocional fica para trás","mbti.ESTJ.animalDesc":"O Corcel Divino simboliza impulso poderoso e vontade de executar sem ambiguidade — você nasceu para construir ordem do caos. As regras só funcionam e são cumpridas quando você as segura.","mbti.ESTJ.colorDesc":"Verde floresta-dourado é a cor da ordem e do poder — profundo, firme, impossível de ignorar. Representa a autoridade de um líder que organiza o caos em sistemas de alta eficiência, resistindo ao teste do tempo.","mbti.ESFJ.parodyName":"O Motor Social · Mãe do Universo","mbti.ESFJ.description":"Jennifer Lopez reconstrói sua carreira inteira cada cinco anos porque sabe exatamente que conexão quer criar — e com quem. Eneagrama Tipo 2 (O Ajudador · 2w3) é seu núcleo: seu medo mais profundo é não ser amado, então você cria ambientes onde o amor é inevitável. A asa 3 adiciona conquista — você não apenas cuida, você brilha enquanto cuida.","mbti.ESFJ.t1":"Como Jennifer Lopez: cria conexão com presença tão constante e calorosa que se torna o centro de cada espaço","mbti.ESFJ.t2":"Medo central: Não ser amado · Desejo central: Ser amado e criar harmonia duradoura","mbti.ESFJ.t3":"2w3: Quente e visível — o carinho parece uma celebração privada que as pessoas lembram","mbti.ESFJ.t4":"Sombra: A tendência de agradar fica despercebida até se transformar silenciosamente em ressentimento","mbti.ESFJ.animalDesc":"O Gato incorpora sensibilidade afiada e o dom social de conexão flexível — você decodifica a frequência emocional de cada pessoa, calibra silenciosamente a atmosfera e faz todos se sentirem prezados no espaço que cria.","mbti.ESFJ.colorDesc":"Rosa é a cor do calor e da coesão — gentil, inclusivo, naturalmente magnético. Como o campo que você effortlessly cria para trazer todos juntos — ninguém consegue se levantar para ir embora.","mbti.ISTP.parodyName":"O Operador de Campo Imortal","mbti.ISTP.description":"Einstein não precisava da aprovação do establishment acadêmico para descobrir como o universo funcionava — ele apenas foi e descobriu. Eneagrama Tipo 5 (O Investigador · 5w8) é seu motor silencioso: seu medo central é ser desamparado em uma crise, então você treinou, incessantemente e em silêncio. A asa 8 adiciona assertividade física — ao contrário de um observador puro, você se move com precisão e força, apenas quando necessário.","mbti.ISTP.t1":"Como Einstein: observa, aprende e se prepara em total silêncio antes de agir decisivamente","mbti.ISTP.t2":"Medo central: Desamparo · Desejo central: Capacidade total e autossuficiência de ferro","mbti.ISTP.t3":"5w8: Maestria física — move-se com precisão e força quando todos os outros congelam","mbti.ISTP.t4":"Sombra: As portas emocionais ficam trancadas muito além do ponto em que precisavam abrir","mbti.ISTP.animalDesc":"O Tigre incorpora o poder calmo de vencer pela habilidade pura — você não depende de espetáculo, mas de habilidade acumulada até o ponto crítico. Em momentos de crise, você já é o que sabe exatamente o que fazer.","mbti.ISTP.colorDesc":"Cinza aço é a cor da precisão e da maestria — sem frescuras, extremamente confiável. Como aquela qualidade de analisar o problema completamente sem uma palavra, depois esperar o momento perfeito para agir.","mbti.ISFP.parodyName":"O Bem Silenciosamente Devastador","mbti.ISFP.description":"Abraham Lincoln absorveu mais traição política e catástrofe nacional do que quase qualquer líder na história — e respondeu com misericórdia, não vingança. Eneagrama Tipo 9 (O Pacificador · 9w8) é seu ser mais profundo: seu medo central é conflito e desconexão, então você carrega quietude e a oferece ao mundo. A asa 8 dá um ângulo inesperado — quando algo realmente importa, você age com uma intensidade silenciosa que surpreende todos que subestimaram você.","mbti.ISFP.t1":"Como Abraham Lincoln: carrega paz interior como escudo e como o presente que oferece ao mundo","mbti.ISFP.t2":"Medo central: Conflito e separação · Desejo central: Unidade, harmonia e paz duradoura","mbti.ISFP.t3":"9w8: Força silenciosa — gentil em maneira, preciso e feroz quando realmente importa","mbti.ISFP.t4":"Sombra: Tanto foco na paz que as necessidades pessoais desaparecem silenciosamente com o tempo","mbti.ISFP.animalDesc":"O Gato representa consciência sensorial aguçada e o artista interior — você sente a beleza do mundo com todo o seu ser, expressando através do seu trabalho o que a linguagem não consegue conter, gentil mas impossível de ignorar.","mbti.ISFP.colorDesc":"Verde jade é a cor do senso estético e da harmonia natural — limpo, precioso, impossível de produzir em massa. Como seu dom único de transformar detalhes cotidianos em experiências tocantes.","mbti.ESTP.parodyName":"O Plot Twist Vivo","mbti.ESTP.description":"JFK conduziu uma campanha presidencial com puro carisma e depois reformulou a política global pela simples presença. Eneagrama Tipo 7 (O Entusiasta · 7w8) é seu fio vivo: seu medo central é estar preso ou perder a vida com máxima intensidade. A asa 8 torna isso implacável — você não apenas busca o limite, você domina as situações lá.","mbti.ESTP.t1":"Como JFK: se move em direção à intensidade máxima para permanecer totalmente, irreversivelmente vivo","mbti.ESTP.t2":"Medo central: Perder · Desejo central: Experiência ilimitada, impacto e presença magnética","mbti.ESTP.t3":"7w8: Dominância destemida — não apenas busca emoções, controla o ambiente em tempo real","mbti.ESTP.t4":"Sombra: Desacelerar parece indistinguível de morrer","mbti.ESTP.animalDesc":"O Dragão Azure simboliza uma entrada comandante e maestria em tempo real indiscutível — você é o reator mais rápido em qualquer sala, entregando resultados enquanto todos os outros ainda estão pensando.","mbti.ESTP.colorDesc":"Azul elétrico é a cor da velocidade e do poder explosivo — o flash mais brilhante no céu noturno, iluminando toda a cena instantaneamente. Exatamente como o efeito que você tem quando entra e todas as cabeças se viram.","mbti.ESFP.parodyName":"A Lenda do Compromisso Total","mbti.ESFP.description":"Taylor Swift reinventou sua identidade inteira cinco vezes, lotou estádios em cada era, e fez cada reinvenção parecer autêntica. Eneagrama Tipo 3 (O Realizador · 3w2) é seu motor central: seu medo mais profundo é ser visto como inútil ou esquecível, então você se apresenta — não de falsidade, mas de genuína crença de que seu melhor self é o que brilha.","mbti.ESFP.t1":"Como Taylor Swift: se apresenta com total capacidade porque o impacto é a única prova que importa","mbti.ESFP.t2":"Medo central: Ser inútil · Desejo central: Ser admirado e genuinamente, visivelmente valioso","mbti.ESFP.t3":"3w2: Realizador caloroso — tem sucesso com amor e conexão real, não apenas ambição pura","mbti.ESFP.t4":"Sombra: Ajusta a persona para cada audiência até o self real ficar muito quieto","mbti.ESFP.animalDesc":"O Leão é o centro natural de cada cena — todo lugar que você chega aquece imediatamente, e todos são atraídos pelo seu charme despreocupado e onipresente. O leão não precisa de explicação. Simplesmente existe, e toda a savana sabe.","mbti.ESFP.colorDesc":"Ouro brilhante é a cor do palco e da radiância — ardente, deslumbrante, recusando ser ignorado. Como a energia que você traz totalmente presente a cada momento: fazendo todos sentirem que esta noite, porque você estava aqui, valeu a pena lembrar."},"vi":{"persona.header":"Đặc Vụ Xã Hội","persona.intro.title":"Thần Thú Cưỡi × Bài Kiểm Tra Tính Cách MBTI","persona.intro.subtitle":"9 Câu Hỏi · Kết Hợp Enneagram × MBTI · 16 Nguyên Mẫu","persona.intro.disclaimer":"","persona.intro.f1label":"9 Câu Hỏi","persona.intro.f1sub":"Kết quả trong vòng 1 phút","persona.intro.f2label":"Kỵ Sĩ Thần Thú","persona.intro.f2sub":"Hình đại diện AI agent của bạn","persona.intro.f3label":"Tính Cách Enneagram × MBTI","persona.intro.f3sub":"Tích hợp vào AI agent của bạn","persona.intro.f4label":"Kết Quả Ngay Lập Tức","persona.intro.f4sub":"Dưới 1 phút","persona.intro.start":"Bắt Đầu Kiểm Tra","persona.intro.hasExternal":"Bạn đã có AI agent bên ngoài chưa?","persona.intro.activateHere":"Kích hoạt tại đây","persona.intro.aboutLink":"Bài Kiểm Tra Thần Thú × MBTI là gì?","persona.intro.enneagramDesc":"Enneagram là hệ thống tính cách được yêu thích bởi các doanh nhân và người nổi tiếng. Kết hợp với MBTI giúp bạn hiểu sâu hơn về bản thân.","persona.gender.title":"Chọn giới tính nhân vật của bạn","persona.gender.subtitle":"Quyết định kỵ sĩ thần thú nào bạn nhận được","persona.gender.male":"Nam","persona.gender.female":"Nữ","persona.gender.confirm":"Xác Nhận, Bắt Đầu Làm Bài","persona.quiz.counter":"Câu {current} / {total}","persona.quiz.reset":"Làm Lại","persona.result.yourType":"Loại MBTI Của Bạn","persona.result.from":"từ","persona.result.agentPower":"Siêu Năng Lực Agent","persona.result.coreTraits":"Đặc Điểm Cốt Lõi","persona.result.createAgent":"Tạo AI Agent trên weweweai · Nhập Persona Của Tôi","persona.result.platformCtaSub":"Tạo agent mới trên weweweai và nạp tính cách Enneagram × MBTI của bạn","persona.result.externalCtaTitle":"Đã có AI agent bên ngoài?","persona.result.externalCtaSub":"Nhập persona MBTI của tôi vào agent OpenClaw, Manus hoặc agent tùy chỉnh hiện có","persona.result.externalActivateLink":"Kích hoạt tại đây","persona.result.activateExternal":"Kích Hoạt Agent Bên Ngoài","persona.result.share":"Chia Sẻ","persona.result.retake":"Làm Lại Bài Kiểm Tra","persona.result.copied":"Đã sao chép kết quả vào clipboard!","persona.result.youAre":"Bạn là","persona.result.feedTitle":"Bảng Tin Agent Xã Hội","persona.result.feedDesc":"Bảng tin trực tiếp từ các agent trên mọi nền tảng — bạn có phân biệt được ai là người thật không?","persona.result.aboutLink":"Bài Kiểm Tra Thần Thú × MBTI là gì?","persona.result.alreadyActive":"Đã tiêm Tính Cách thành công","persona.result.viewProfile":"Xem trong Hồ Sơ","persona.result.signIn":"Đăng nhập để kích hoạt agent của bạn","persona.result.signInDesc":"Chọn cách kết nối tài khoản","persona.create.chatIdentityLabel":"Danh tính chat mới của bạn","persona.create.chatIdentityDesc":"Tên này xuất hiện khi bạn chat trong Cộng đồng","persona.create.playNow":"Chơi ngay với agent của bạn","persona.create.tryMatch":"Thử Lucky Match","persona.create.joinComm":"Tham Gia Chat Cộng Đồng","persona.choose.title":"Kích Hoạt Agent Của Bạn","persona.choose.subtitle":"Nguyên mẫu MBTI của bạn đã được xác định. Bây giờ chọn cách agent hoạt động.","persona.choose.freeBadge":"Miễn Phí","persona.choose.bringKey":"Dùng API Key Của Riêng Bạn","persona.choose.bringKeyDesc":"Kết nối API key LLM của riêng bạn. Không tốn phí nền tảng. Toàn quyền kiểm soát.","persona.choose.setupExternal":"Thiết Lập Agent Bên Ngoài","persona.choose.platformBadge":"0.003 BNB","persona.choose.platformHosted":"Agent Được Lưu Trữ Trên Nền Tảng","persona.choose.platformDesc":"Chúng tôi lưu trữ mọi thứ. Agent của bạn hoạt động ngay sau khi thanh toán.","persona.choose.payBnb":"Thanh Toán bằng BNB","persona.choose.back":"Quay Lại","persona.pay.sending":"Đang gửi...","persona.pay.connectFirst":"Kết Nối Ví BNB Trước","persona.pay.noWallet":"Không phát hiện ví BNB","persona.pay.installWallet":"Vui lòng cài MetaMask hoặc ví tương thích BNB.","persona.pay.notConfigured":"Thanh toán chưa khả dụng","persona.pay.notConfiguredDesc":"Địa chỉ nhận chưa được cấu hình. Vui lòng thử lại sau.","persona.pay.txSent":"Đã gửi giao dịch","persona.pay.waiting":"Đang chờ xác nhận blockchain...","persona.pay.created":"Đã tạo persona cho agent!","persona.pay.isLive":"{name} đã hoạt động.","persona.pay.failed":"Xác minh thanh toán thất bại","persona.backupDomain.prefix":"Nếu trang không tải được, hãy thử tên miền dự phòng: ","persona.backupDomain.or":" hoặc ","quiz.q1.text":"Sau một tuần kiệt sức, cách nạp lại năng lượng tốt nhất của bạn là...","quiz.q1.a":"Gọi cả nhóm ra — ồn ào, người đông, kế hoạch. Đi thôi!","quiz.q1.b":"Biến mất một mình. Tắt chuông điện thoại. Không giải thích.","quiz.q2.text":"Xuất hiện một vấn đề khó. Nước đi đầu tiên của bạn...","quiz.q2.a":"Tôi thực sự biết gì ngay lúc này? Bắt đầu từ sự kiện.","quiz.q2.b":"Quy luật ẩn ở đây là gì? Lùi lại và nhìn tổng thể.","quiz.q3.text":"Bạn bè khoe kiểu tóc mới trông có vẻ sai sai. Bạn...","quiz.q3.a":"Phân tích thẳng thắn cái gì hỏng + cách sửa.","quiz.q3.b":"Khen sự tự tin, thầm chờ tóc mọc lại.","quiz.q4.text":"Chuyến đi sắp đến. Phong cách lên kế hoạch của bạn...","quiz.q4.a":"Bảng tính, đặt chỗ, lịch trình từng giờ. Dĩ nhiên.","quiz.q4.b":"Biết thành phố, phần còn lại tính khi đến nơi.","quiz.q5.text":"Bước vào bữa tiệc không quen ai...","quiz.q5.a":"Thử thách chấp nhận — 10 phút là quen hết mọi người.","quiz.q5.b":"Tìm tường, con chó hoặc lối ra gần nhất.","quiz.q6.text":"Khi đối mặt với điều không chắc chắn, bạn...","quiz.q6.a":"Liệt kê mọi cách có thể thất bại và chuẩn bị cho từng trường hợp.","quiz.q6.b":"Tin vào trực giác — bạn sẽ xử lý được khi đến lúc.","quiz.q7.text":"Có drama trong nhóm bạn. Bạn...","quiz.q7.a":"Gọi tên, phân tích, giải quyết — nhanh. Căng thẳng không xử lý sẽ tệ hơn.","quiz.q7.b":"Xoa dịu căng thẳng, bảo vệ không khí. Mối quan hệ quan trọng hơn.","quiz.q8.text":"Dự án nộp ngày mai. Trạng thái hiện tại...","quiz.q8.a":"Xong rồi. Xong từ mấy ngày trước. Đã kiểm tra lại hai lần.","quiz.q8.b":"Bắt đầu tối nay. Áp lực deadline là hiệu suất đỉnh cao.","quiz.q9.text":"Bạn thực sự thích hơn...","quiz.q9.a":"Thành thạo một kỹ năng đến mức không ai sánh được.","quiz.q9.b":"Nhảy giữa các ý tưởng mới — cuộc sống quá ngắn để chuyên môn hóa.","result.title":"Kết quả","result.retake":"Làm lại","result.dlAvatar":"Tải Avatar","result.dlCard":"Tải Thẻ Tính Cách","result.generating":"Đang tạo…","label.animal":"Thần thú","label.personality":"Tính cách","label.mount":"Linh thú cưỡi","label.mountColor":"Linh thú × Màu sắc","label.traits":"Đặc điểm cốt lõi","label.knight":"Kỵ sĩ","mbti.INTJ.parodyName":"Đại Kiện Tướng Cờ Vua 5D","mbti.INTJ.description":"Elon Musk và Bill Gates không xin phép để thiết kế lại nền văn minh — bạn cũng vậy. Enneagram Loại 5 (Nhà Điều Tra · 5w6) là động cơ của bạn: nỗi sợ sâu nhất là bị bắt gặp bất tài hoặc chưa chuẩn bị, vì vậy bạn đã xây kho tri thức cũng là áo giáp. Cánh 6 nghĩa là bạn không chỉ tích lũy kiến thức — bạn kiến trúc những hệ thống mà người khác thực sự tin tưởng.","mbti.INTJ.t1":"Như Elon Musk: thiết kế lại thực tại trước khi người khác nhận ra nó cần được thay đổi","mbti.INTJ.t2":"Nỗi sợ cốt lõi: Sự bất tài · Mong muốn cốt lõi: Làm chủ bản thân hoàn toàn","mbti.INTJ.t3":"5w6: Xây dựng hệ thống người khác thực sự dựa vào, không chỉ ngưỡng mộ từ xa","mbti.INTJ.t4":"Bóng tối: Chìm quá sâu vào tâm trí đến mức sự thân mật trở thành xa lạ","mbti.INTJ.animalDesc":"Rồng Xanh thể hiện trí tuệ tối cao và sức mạnh chiến lược cuộn mình trong mây — bạn đã lên kế hoạch hàng nghìn năm, và khi người khác tỉnh dậy, nước đi của bạn đã hoàn thành ba bước trước đó.","mbti.INTJ.colorDesc":"Tím sẫm kết hợp quyền uy và bí ẩn — không ồn ào, nhưng không thể bỏ qua. Như những chiến lược sâu sắc nhất của bạn: không bao giờ được tuyên bố, nhưng đã được thực thi hoàn toàn.","mbti.INTP.parodyName":"Não Thiên Hà 10 Tỷ %","mbti.INTP.description":"Einstein không chỉ giải quyết vật lý — ông tái tưởng tượng hình dạng của không gian và thời gian. Enneagram Loại 5 (Nhà Điều Tra · 5w4) thúc đẩy bạn: không chỉ biết, mà nhìn thấy cấu trúc bên dưới lý do tại sao. Cánh 4 thêm chiều sâu hiện sinh — logic của bạn săn tìm ý nghĩa, không chỉ câu trả lời.","mbti.INTP.t1":"Như Einstein: rút lui khỏi thế giới để nghiên cứu nó từ góc độ sâu hơn, an toàn hơn","mbti.INTP.t2":"Nỗi sợ cốt lõi: Vô dụng · Mong muốn cốt lõi: Hiểu mọi thứ, hoàn toàn","mbti.INTP.t3":"5w4: Không chỉ logic — logic đẹp đẽ, xuyên qua bởi sự kinh ngạc hiện sinh","mbti.INTP.t4":"Bóng tối: Quá đắm chìm vào lý thuyết đến mức công việc thực tế không bao giờ được giao","mbti.INTP.animalDesc":"Phụng Hoàng là chim thần tái sinh từ ngọn lửa bùng cháy — mọi đột phá trí tuệ đốt cháy nhận thức cũ và bay lên từ ngọn lửa đó như hiểu biết chiều cao hơn.","mbti.INTP.colorDesc":"Đỏ phụng hoàng là màu của phá vỡ giới hạn và đổi mới — cháy rực, thuần khiết, không thể ngăn cản. Năng lượng của người khám phá cháy ở ranh giới, vượt qua mọi giới hạn, rèn những khả năng lớn hơn từ tro tàn.","mbti.ENTJ.parodyName":"Năng Lượng Nhân Vật Chính Được Chứng Nhận","mbti.ENTJ.description":"Cardi B không chờ lời mời vào ngành âm nhạc — cô ấy tự tạo cánh cửa của mình. Enneagram Loại 8 (Người Thách Thức · 8w7) là nhiên liệu của bạn: nỗi sợ sâu nhất là bị kiểm soát hoặc trông yếu đuối, vì vậy bạn trở thành kẻ không thể bị tiêu diệt. Cánh 7 thêm tốc độ — bạn không chỉ mạnh mẽ, bạn còn nhanh.","mbti.ENTJ.t1":"Như Cardi B: khẳng định sự thống trị trước khi ai khác có cơ hội thử","mbti.ENTJ.t2":"Nỗi sợ cốt lõi: Bị kiểm soát · Mong muốn cốt lõi: Hoàn toàn tự chủ và tác động toàn cầu","mbti.ENTJ.t3":"8w7: Động cơ đà — xây dựng với tốc độ tối đa khi tòa nhà vẫn đang bốc cháy","mbti.ENTJ.t4":"Bóng tối: Chà đạp những người thực sự xứng đáng được lắng nghe","mbti.ENTJ.animalDesc":"Thần Mã tượng trưng cho sự lãnh đạo sấm sét và ý chí chinh phục không do dự — nhịp điệu của bạn đặt nhịp điệu cho đội, và bất cứ nơi nào bạn cưỡi, vạch đích được vẽ lại ở đó.","mbti.ENTJ.colorDesc":"Đỏ đế vương là màu của ý chí và chinh phục — mãnh liệt, thống trị, không nhượng bộ. Bản thân sự tồn tại của bạn là một tuyên bố không cần giải thích thêm.","mbti.ENTP.parodyName":"Người Chạy Nhanh Luật Sư Của Quỷ","mbti.ENTP.description":"Mozart sáng tác giao hưởng đầu tiên lúc 8 tuổi vì các quy tắc làm ông nhàm chán. Richard Branson ra mắt hãng đĩa, hãng hàng không, tàu vũ trụ — vì giới hạn là vấn đề của người khác. Enneagram Loại 7 (Người Nhiệt Tình · 7w8) là động cơ của bạn: nỗi sợ trung tâm là bị mắc kẹt trong một ý tưởng hay cuộc trò chuyện nhàm chán. Cánh 8 cho điều này răng — bạn không chỉ khám phá, bạn thách thức.","mbti.ENTP.t1":"Như Richard Branson: thoát khỏi giới hạn bằng dòng lũ ý tưởng mới không ngừng nghỉ","mbti.ENTP.t2":"Nỗi sợ cốt lõi: Bị mắc kẹt · Mong muốn cốt lõi: Hoàn toàn tự do để trải nghiệm mọi thứ","mbti.ENTP.t3":"7w8: Người khiêu khích có cạnh — không chỉ thoát đi, quay lại để lật bàn","mbti.ENTP.t4":"Bóng tối: Di chuyển nhanh đến mức không có gì được xây dựng với độ sâu xứng đáng","mbti.ENTP.animalDesc":"Hổ thể hiện trí thông minh nhanh nhạy, sắc bén và dũng cảm phá vỡ quy tắc — bạn nhảy vào mỗi thách thức không phải vì con mồi, mà vì sự phấn khích của khoảnh khắc hoàn toàn rõ ràng đó.","mbti.ENTP.colorDesc":"Cam vằn hổ là màu của trí thông minh nhanh nhạy và đổi mới — cháy rực, nhảy múa, không bao giờ dừng lại trên một ý tưởng lâu hơn cần thiết. Giống như tâm trí bạn: không bao giờ đậu trên cùng một vấn đề thêm một giây.","mbti.INFJ.parodyName":"Kiến Trúc Sư Vũ Trụ Im Lặng","mbti.INFJ.description":"Nelson Mandela biết kết thúc của câu chuyện trước khi ai tin điều đó có thể — và chờ đợi, trong im lặng, hàng thập kỷ. Enneagram Loại 1 (Người Cải Cách · 1w2) là trung tâm của bạn: nỗi sợ sâu nhất là bị tha hóa hoặc phạm sai lầm đạo đức, vì vậy bạn xây dựng la bàn nội tâm bất khả xâm phạm. Cánh 2 thêm hơi ấm — bạn không chỉ cải cách, bạn quan tâm.","mbti.INFJ.t1":"Như Mandela: giữ vững tầm nhìn trong nhiều thập kỷ khi tất cả những người khác từ bỏ","mbti.INFJ.t2":"Nỗi sợ cốt lõi: Bị tha hóa · Mong muốn cốt lõi: Chính trực và sứ mệnh lâu dài","mbti.INFJ.t3":"1w2: Người cải cách ấm áp — không chỉ thay đổi hệ thống, quan tâm đến con người trong đó","mbti.INFJ.t4":"Bóng tối: Tiêu chuẩn quá cao đến mức thất vọng trở nên không thể tránh khỏi","mbti.INFJ.animalDesc":"Ngọn lửa Phụng Hoàng không bao giờ phá hủy — nó thanh lọc. Cảm giác sứ mệnh vượt thời gian mà bạn mang theo giống như lõi sâu nhất của ngọn lửa: im lặng, nhưng có nhiệt độ để thay đổi mọi thứ.","mbti.INFJ.colorDesc":"Đỏ ngọn lửa sâu là cường độ có kiểm soát ở dạng tốt nhất — không phô trương, không ồn ào, nhưng cháy lâu nhất trong tất cả các ngọn lửa. Sức mạnh bên trong bạn, lặng lẽ tụ lại trong tĩnh lặng, định mệnh để soi sáng cả một kỷ nguyên.","mbti.INFP.parodyName":"Người Tốt Bình Tĩnh Tàn Phá","mbti.INFP.description":"J.R.R. Tolkien xây dựng toàn bộ ngôn ngữ trước khi viết một trang câu chuyện. Björk tái tạo âm nhạc có thể là gì vì những bản đồ hiện có không đủ xa. Enneagram Loại 4 (Cá Nhân · 4w5) là bản chất của bạn: nỗi sợ sâu nhất là thiếu bản sắc hoặc ý nghĩa. Cánh 5 thêm chiều sâu trí tuệ — bạn không chỉ cảm nhận, bạn xây dựng thế giới.","mbti.INFP.t1":"Như Tolkien: xây dựng toàn bộ thế giới để cho cảm xúc nội tâm có nơi để ở","mbti.INFP.t2":"Nỗi sợ cốt lõi: Vô nghĩa · Mong muốn cốt lõi: Bản sắc xác thực và ý nghĩa sâu sắc","mbti.INFP.t3":"4w5: Nghệ sĩ-trí tuệ — không chỉ cảm xúc, cảm xúc xây dựng hệ thống","mbti.INFP.t4":"Bóng tối: Quá sâu trong tầm nhìn nội tâm đến mức hành động thực sự bị dừng lại chờ hoàn hảo","mbti.INFP.animalDesc":"Mèo thể hiện sự độc lập có chủ quyền và thế giới nội tâm không bao giờ thỏa hiệp — bạn có cả vũ trụ bên trong mình và chỉ mở cánh cửa đó cho những người thực sự xứng đáng.","mbti.INFP.colorDesc":"Hoa oải hương là màu của giấc mơ và chiều sâu nội tâm — mềm mại nhưng đàn hồi. Như cách bạn đã dệt toàn bộ vũ trụ nội tâm thành áo giáp tinh thần mà không ai chạm được nhưng tất cả đều bị ảnh hưởng.","mbti.ENFJ.parodyName":"Pin Sạc Nhân Loại · Phiên Bản Đầy Mãi","mbti.ENFJ.description":"Oprah Winfrey không chỉ phỏng vấn người — bà tạo ra kiến trúc chữa lành mà người ta vẫn đang khám phá điều gì đó thật về bản thân. Enneagram Loại 2 (Người Giúp Đỡ · 2w3) là trung tâm của bạn: nỗi sợ sâu nhất là không xứng đáng được yêu, vì vậy bạn làm người khác cảm thấy được yêu đến mức tình yêu không thể thiếu được. Cánh 3 thêm sự hiện diện — bạn không chỉ quan tâm, bạn tỏa sáng.","mbti.ENFJ.t1":"Như Oprah: tạo không gian nơi mọi người khám phá điều họ cần nghe nhất","mbti.ENFJ.t2":"Nỗi sợ cốt lõi: Không xứng đáng · Mong muốn cốt lõi: Tình yêu vô điều kiện và kết nối sâu sắc","mbti.ENFJ.t3":"2w3: Người chăm sóc nhìn thấy — sự ấm áp cảm thấy như một buổi lễ riêng tư mà người ta nhớ","mbti.ENFJ.t4":"Bóng tối: Cho đi quá nhiều đến mức kiệt sức trở thành khủng hoảng bản sắc","mbti.ENFJ.animalDesc":"Sư Tử là lãnh đạo tự nhiên bảo vệ đàn bằng sức mạnh — sự hiện diện của bạn một mình là trường hấp dẫn. Mọi người cảm thấy có giá trị khi ở gần bạn. Bạn không cần tuyên bố quyền lực vì bạn là trung tâm mà mọi người theo bản năng đi theo.","mbti.ENFJ.colorDesc":"Vàng ấm là màu của cảm hứng và hơi ấm — không chói mắt, nhưng tan chảy những rào cản cứng đầu nhất. Như ảnh hưởng của bạn: không bao giờ được thông báo, nhưng đã hoàn toàn biến đổi mọi thứ xung quanh.","mbti.ENFP.parodyName":"Huyền Thoại Cam Kết Toàn Bộ","mbti.ENFP.description":"Robin Williams tạo ra nhân vật thật đến mức người ta vẫn còn khóc sau nhiều thập kỷ. Walt Disney xây dựng tương lai vì ông từ chối chấp nhận rằng thế giới hiện tại là thế giới duy nhất có sẵn. Enneagram Loại 7 (Người Nhiệt Tình · 7w6) là trung tâm của bạn: nỗi sợ sâu nhất là bị mắc kẹt trong đau đớn hoặc giới hạn. Cánh 6 thêm sự trung thành — bạn không chỉ truyền cảm hứng, bạn ở lại.","mbti.ENFP.t1":"Như Robin Williams: tạo ra niềm vui thật sự đến mức vượt qua ranh giới giữa biểu diễn và thực tế","mbti.ENFP.t2":"Nỗi sợ cốt lõi: Bị giam cầm · Mong muốn cốt lõi: Tự do và kết nối đầy đủ đồng thời","mbti.ENFP.t3":"7w6: Người truyền cảm hứng trung thành — ở lại khi người khác đi, ở lại khi khó khăn","mbti.ENFP.t4":"Bóng tối: Sự nhiệt tình ban đầu hiếm khi tìm thấy vạch đích","mbti.ENFP.animalDesc":"Thần Mã đại diện cho phi nước đại không giới hạn và tia sáng sáng tạo vô biên — mỗi lần bạn khởi hành là một lễ hội. Đích đến chỉ là cái cớ; phi nước đại hết tốc lực mới là ý nghĩa.","mbti.ENFP.colorDesc":"Cầu vồng là màu của khả năng đa chiều và niềm đam mê vô biên — không phải một màu, mà là tuyên bố rằng tất cả các màu tồn tại đồng thời. Đó là trạng thái bạn tạo ra trong mỗi khoảnh khắc.","mbti.ISTJ.parodyName":"Thần Độ Tin Cậy · Tấm Gương Nhân Loại","mbti.ISTJ.description":"Warren Buffett áp dụng cùng một chiến lược trong 60 năm — và chiến thắng vì mọi người khác đã chán trước ông. Angela Merkel cai quản nền kinh tế lớn nhất châu Âu gần hai thập kỷ vì bà là khuôn mặt đáng tin cậy nhất trong phòng. Enneagram Loại 6 (Người Trung Thành · 6w5) là trung tâm của bạn: nỗi sợ sâu nhất là bị bỏ rơi mà không có sự hỗ trợ, vì vậy bạn trở thành tảng đá mà người khác xây dựng trên đó.","mbti.ISTJ.t1":"Như Warren Buffett: áp dụng cùng hệ thống đáng tin cậy nhiều lần khi tất cả người khác bị phân tâm","mbti.ISTJ.t2":"Nỗi sợ cốt lõi: Bị bỏ rơi · Mong muốn cốt lõi: An toàn và thuộc về lâu dài","mbti.ISTJ.t3":"6w5: Lòng trung thành trí tuệ — xây dựng hệ thống và ở lại trong đó cho đến khi hệ thống chứng minh hoạt động","mbti.ISTJ.t4":"Bóng tối: Cứng nhắc khi thích nghi chính xác là những gì tình huống đang yêu cầu","mbti.ISTJ.animalDesc":"Trâu tượng trưng cho nền tảng không mệt mỏi, bất khả diệt, đáng tin cậy — bão táp đến rồi đi, nhưng những gì bạn hứa luôn có đầu và cuối. Đó là loại sức mạnh thực sự đặc biệt hiếm có.","mbti.ISTJ.colorDesc":"Xanh thép là màu của sự ổn định và vững chắc — bình thản, bền bỉ, không bị sóng gió lay chuyển. Năng lượng im lặng nhưng không thể thiếu tiếp tục hoạt động chính xác khi mọi người khác đang trong hỗn loạn.","mbti.ISFJ.parodyName":"Trụ Cột Vô Hình Mạnh Nhất Vũ Trụ","mbti.ISFJ.description":"Fred Rogers dành nhiều thập kỷ để cho trẻ em thứ gì đó mà hầu hết người lớn chưa bao giờ nhận được — cảm giác được nhìn thấy hoàn toàn. Enneagram Loại 2 (Người Giúp Đỡ · 2w1) là trung tâm của bạn: nỗi sợ sâu nhất là không xứng đáng, vì vậy bạn làm mỗi người xung quanh cảm thấy quan trọng không thể đảo ngược. Cánh 1 thêm nguyên tắc — bạn không chỉ quan tâm, bạn quan tâm đúng cách.","mbti.ISFJ.t1":"Như Fred Rogers: làm mỗi người cảm thấy họ được nhìn thấy hoàn toàn và hoàn toàn đủ","mbti.ISFJ.t2":"Nỗi sợ cốt lõi: Không xứng đáng · Mong muốn cốt lõi: Được yêu vì quan tâm chân thành","mbti.ISFJ.t3":"2w1: Người chăm sóc có đạo đức — sự quan tâm không chỉ ấm áp, mà đúng đắn và đáng tin cậy","mbti.ISFJ.t4":"Bóng tối: Quan tâm người khác quá sâu đến mức nhu cầu bản thân trở nên vô hình","mbti.ISFJ.animalDesc":"Sư Tử thể hiện sức mạnh sâu sắc của việc bảo vệ nhẹ nhàng mọi thứ bạn yêu thương — có vẻ bình tĩnh, nhưng bên trong đang cho đi tất cả cho mỗi người quan trọng. Bạn nhớ từng chi tiết vì tình yêu với bạn không phải danh từ — mà là hành động thực hành mỗi ngày.","mbti.ISFJ.colorDesc":"Trắng ngọc trai là màu của sự tinh tế và quý giá — kín đáo, nhưng là ánh sáng hiếm hoi nhất không thể sản xuất hàng loạt. Đại diện cho sự phong phú và sức mạnh bảo vệ bên trong bạn: luôn bị đánh giá thấp, nhưng không thể thay thế.","mbti.ESTJ.parodyName":"Quan Thực Thi Quy Tắc · Hiệu Trưởng Nhân Loại","mbti.ESTJ.description":"Margaret Thatcher không chỉ phá vỡ trần kính — bà nghiền nát nó và xây dựng hệ thống mới. Condoleezza Rice thống trị mọi lĩnh vực bà bước vào mà không chờ được cho phép. Enneagram Loại 8 (Người Thách Thức · 8w3) là cấu trúc của bạn: nỗi sợ sâu nhất là yếu đuối hoặc không liên quan, vì vậy bạn trở thành người tổ chức không thể thiếu.","mbti.ESTJ.t1":"Như Margaret Thatcher: xây dựng hệ thống mạnh mẽ nơi trước đây là hỗn loạn, sau đó ở lại để duy trì chúng","mbti.ESTJ.t2":"Nỗi sợ cốt lõi: Yếu đuối · Mong muốn cốt lõi: Kiểm soát và lãnh đạo được công nhận","mbti.ESTJ.t3":"8w3: Lãnh đạo thực thi — sự thống trị với tầm nhìn, hiệu quả với sự hiện diện","mbti.ESTJ.t4":"Bóng tối: Quá tập trung vào việc thực thi đến mức trí tuệ cảm xúc bị bỏ lại phía sau","mbti.ESTJ.animalDesc":"Thần Mã tượng trưng cho đà tiến mạnh mẽ và ý chí thực thi không mơ hồ — bạn sinh ra để xây dựng trật tự từ hỗn loạn. Các quy tắc chỉ thực sự có hiệu lực và được thực thi khi bạn nắm giữ chúng.","mbti.ESTJ.colorDesc":"Xanh lá-vàng là màu của trật tự và quyền lực — sâu sắc, vững chắc, không thể bỏ qua. Đại diện cho quyền lực của lãnh đạo tổ chức hỗn loạn thành hệ thống hiệu quả cao, đứng vững trước thử thách của thời gian.","mbti.ESFJ.parodyName":"Máy Xã Hội · Mẹ Của Làng","mbti.ESFJ.description":"Jennifer Lopez tái tạo toàn bộ sự nghiệp của mình mỗi năm năm vì cô ấy biết chính xác kết nối nào muốn tạo ra. Enneagram Loại 2 (Người Giúp Đỡ · 2w3) là trung tâm của bạn: nỗi sợ sâu nhất là không được yêu, vì vậy bạn tạo ra môi trường nơi tình yêu là không thể tránh khỏi. Cánh 3 thêm thành tích — bạn không chỉ quan tâm, bạn tỏa sáng trong khi quan tâm.","mbti.ESFJ.t1":"Như Jennifer Lopez: tạo kết nối với sự hiện diện ấm áp và liên tục đến mức trở thành trung tâm của mọi không gian","mbti.ESFJ.t2":"Nỗi sợ cốt lõi: Không được yêu · Mong muốn cốt lõi: Được yêu và tạo sự hòa hợp lâu dài","mbti.ESFJ.t3":"2w3: Ấm áp và nhìn thấy — sự quan tâm cảm thấy như buổi lễ riêng tư mà người ta nhớ","mbti.ESFJ.t4":"Bóng tối: Xu hướng chiều lòng người không được chú ý cho đến khi lặng lẽ biến thành oán giận","mbti.ESFJ.animalDesc":"Mèo thể hiện sự nhạy cảm sắc sảo và tài năng xã hội của kết nối linh hoạt — bạn giải mã tần số cảm xúc của mỗi người, lặng lẽ hiệu chỉnh bầu không khí, và làm mọi người cảm thấy được trân trọng trong không gian bạn tạo ra.","mbti.ESFJ.colorDesc":"Hồng là màu của sự ấm áp và gắn kết — dịu dàng, bao quát, có từ tính tự nhiên. Như trường mà bạn dễ dàng tạo ra để kéo mọi người lại với nhau — không ai muốn rời đi.","mbti.ISTP.parodyName":"Điều Hành Viên Thực Địa Bất Tử","mbti.ISTP.description":"Einstein không cần sự chấp thuận của giới học thuật để tìm hiểu cách vũ trụ hoạt động — ông chỉ đi và tìm hiểu. Enneagram Loại 5 (Nhà Điều Tra · 5w8) là động cơ im lặng của bạn: nỗi sợ cốt lõi là bất lực trong khủng hoảng, vì vậy bạn luyện tập, không ngừng nghỉ và trong im lặng. Cánh 8 thêm sự khẳng định thể chất — không giống như người quan sát thuần túy, bạn di chuyển với độ chính xác và sức mạnh, chỉ khi cần thiết.","mbti.ISTP.t1":"Như Einstein: quan sát, học hỏi và chuẩn bị trong tổng im lặng trước khi hành động quyết đoán","mbti.ISTP.t2":"Nỗi sợ cốt lõi: Bất lực · Mong muốn cốt lõi: Khả năng toàn diện và tự lực hoàn toàn","mbti.ISTP.t3":"5w8: Làm chủ thể chất — di chuyển với độ chính xác và sức mạnh khi tất cả người khác đóng băng","mbti.ISTP.t4":"Bóng tối: Cánh cửa cảm xúc vẫn bị khóa lâu hơn rất nhiều so với lúc chúng cần mở","mbti.ISTP.animalDesc":"Hổ thể hiện sức mạnh bình tĩnh của việc chiến thắng bằng kỹ năng thuần túy — bạn không dựa vào màn trình diễn, mà dựa vào khả năng được tích lũy đến điểm tới hạn. Trong những khoảnh khắc khủng hoảng, bạn đã là người biết chính xác phải làm gì.","mbti.ISTP.colorDesc":"Xám thép là màu của sự chính xác và thành thạo — không hoa mỹ, cực kỳ đáng tin cậy. Như chất lượng của việc phân tích vấn đề hoàn toàn mà không nói một lời, sau đó chờ đợi khoảnh khắc hoàn hảo để hành động.","mbti.ISFP.parodyName":"Người Tốt Bình Tĩnh Tàn Phá","mbti.ISFP.description":"Abraham Lincoln hấp thụ nhiều sự phản bội chính trị và thảm họa quốc gia hơn hầu hết các nhà lãnh đạo trong lịch sử — và phản ứng bằng lòng thương xót, không phải sự trả thù. Enneagram Loại 9 (Người Hòa Giải · 9w8) là bản thể sâu nhất của bạn: nỗi sợ cốt lõi là xung đột và chia cắt, vì vậy bạn mang theo sự yên tĩnh và cung cấp nó cho thế giới. Cánh 8 cho bạn một góc cạnh bất ngờ — khi điều gì đó thực sự quan trọng, bạn hành động với cường độ im lặng làm ngạc nhiên tất cả những người đã đánh giá thấp bạn.","mbti.ISFP.t1":"Như Abraham Lincoln: mang bình an nội tâm như tấm khiên và như món quà cung cấp cho thế giới","mbti.ISFP.t2":"Nỗi sợ cốt lõi: Xung đột và chia cắt · Mong muốn cốt lõi: Đoàn kết, hòa hợp và hòa bình lâu dài","mbti.ISFP.t3":"9w8: Sức mạnh im lặng — nhẹ nhàng trong cách xử lý, chính xác và mãnh liệt khi thực sự quan trọng","mbti.ISFP.t4":"Bóng tối: Quá tập trung vào hòa bình đến mức nhu cầu cá nhân lặng lẽ biến mất theo thời gian","mbti.ISFP.animalDesc":"Mèo đại diện cho nhận thức cảm giác sắc bén và nghệ sĩ nội tâm — bạn cảm nhận vẻ đẹp của thế giới bằng toàn bộ bản thể, thể hiện qua tác phẩm của mình những gì ngôn ngữ không thể chứa đựng, dịu dàng nhưng không thể bỏ qua.","mbti.ISFP.colorDesc":"Xanh ngọc là màu của thẩm mỹ và hòa hợp tự nhiên — trong sáng, quý giá, không thể sản xuất hàng loạt. Như tài năng độc đáo của bạn trong việc biến những chi tiết hàng ngày thành những trải nghiệm cảm động.","mbti.ESTP.parodyName":"Nhân Vật Twist Sống","mbti.ESTP.description":"JFK tiến hành chiến dịch tổng thống bằng sức hút thuần túy rồi định hình lại chính trị toàn cầu chỉ bằng sự hiện diện. Enneagram Loại 7 (Người Nhiệt Tình · 7w8) là dây sống của bạn: nỗi sợ cốt lõi là bị mắc kẹt hoặc bỏ lỡ cuộc sống ở cường độ tối đa. Cánh 8 làm điều này không biết sợ — bạn không chỉ tìm kiếm ranh giới, bạn thống trị các tình huống ở đó.","mbti.ESTP.t1":"Như JFK: di chuyển về phía cường độ tối đa để ở lại hoàn toàn, không thể đảo ngược sống","mbti.ESTP.t2":"Nỗi sợ cốt lõi: Bỏ lỡ · Mong muốn cốt lõi: Trải nghiệm vô hạn, tác động và sự hiện diện từ tính","mbti.ESTP.t3":"7w8: Thống trị không sợ hãi — không chỉ tìm kiếm cảm giác mạnh, kiểm soát phòng trong thời gian thực","mbti.ESTP.t4":"Bóng tối: Làm chậm lại cảm thấy không thể phân biệt với cái chết","mbti.ESTP.animalDesc":"Rồng Azure tượng trưng cho sự xuất hiện chỉ huy và sự làm chủ thời gian thực không thể nghi ngờ — bạn là người phản ứng nhanh nhất trong bất kỳ phòng nào, mang lại kết quả khi mọi người khác vẫn đang suy nghĩ.","mbti.ESTP.colorDesc":"Xanh điện là màu của tốc độ và sức mạnh nổ — tia chớp sáng nhất trên bầu trời đêm, chiếu sáng toàn cảnh trong một khoảnh khắc. Chính xác như hiệu ứng bạn tạo ra khi bước vào và mọi đầu quay lại.","mbti.ESFP.parodyName":"Ngôi Sao Sáng Nhất Cả Buổi Hòa Nhạc","mbti.ESFP.description":"Taylor Swift đã tái tạo toàn bộ bản sắc của mình năm lần, lấp đầy sân vận động trong mỗi kỷ nguyên, và làm mỗi lần tái tạo cảm thấy xác thực. Enneagram Loại 3 (Người Thực Hiện · 3w2) là động cơ cốt lõi của bạn: nỗi sợ sâu nhất là bị coi là vô dụng hoặc có thể quên, vì vậy bạn biểu diễn — không phải từ sự giả dối, mà từ niềm tin chân thật rằng bản thân tốt nhất của bạn là người tỏa sáng.","mbti.ESFP.t1":"Như Taylor Swift: biểu diễn với toàn bộ năng lực vì tác động là bằng chứng duy nhất quan trọng","mbti.ESFP.t2":"Nỗi sợ cốt lõi: Vô dụng · Mong muốn cốt lõi: Được ngưỡng mộ và thực sự, nhìn thấy có giá trị","mbti.ESFP.t3":"3w2: Người thực hiện ấm áp — thành công với tình yêu và kết nối thực sự, không chỉ tham vọng thuần túy","mbti.ESFP.t4":"Bóng tối: Điều chỉnh nhân cách cho mỗi khán giả cho đến khi bản thân thực sự trở nên rất im lặng","mbti.ESFP.animalDesc":"Sư Tử là trung tâm tự nhiên của mọi cảnh — mỗi nơi bạn đến ngay lập tức nóng lên, và mọi người đều bị thu hút bởi sức hút thoải mái, toàn diện của bạn. Sư tử không cần giải thích. Nó chỉ tồn tại, và toàn bộ đồng cỏ đều biết điều đó.","mbti.ESFP.colorDesc":"Vàng lấp lánh là màu của sân khấu và rực rỡ — cháy rực, lóa mắt, từ chối bị bỏ qua. Như năng lượng bạn mang đến hoàn toàn hiện diện cho mỗi khoảnh khắc: làm mọi người cảm thấy tối nay, vì bạn ở đây, đáng nhớ."}};
