const SBTI = {
  INTJ:{ title:"🧠 宇宙计划委员长", desc:"全地球最稀有的人格之一。你的大脑是一台永不关机的战略服务器，别人在讨论今天干什么，你已经把接下来十年的棋局规划完了。你不是在开会——你是在等别人追上你早就想好的答案。孤独？那叫战略护城河。朋友少？你叫精准筛选。等人理解你？可能要等他们再进化几个版本。" },
  INTP:{ title:"🔬 外星文明翻译官", desc:"全宇宙最难被理解的人格之一。别人以为你在发呆，其实你正在独立推导第七层理论。你的浏览器标签永远超过47个，每个都是「迟早要认真看完」的重要文献。你真正害怕的不是失败，而是和不思考的人共处超过二十分钟。真相是：你完全活在自己构建的理论宇宙里，偶尔下线来跟人间打个招呼。" },
  ENTJ:{ title:"👑 出生满级的大Boss", desc:"全地球最稀有的人格之一。别人还在新手村打小怪，你已经坐在游戏结局的彩蛋里等着了。你看世界就像通关玩家在看新手教程：这里效率低、那里逻辑混乱、那边需要一个更好的系统——然后你不由自主地坐上了指挥官的位置，虽然你根本没打算要当。全宇宙最让你崩溃的一句话：「将就一下就好了。」" },
  ENTP:{ title:"🗣 辩论协会无限连任会长", desc:"全宇宙最强嘴力值的人格之一。你的大脑同时运行三十个论点，每一个都能颠覆对方的世界观。你最享受的时刻，就是在别人最确定的一秒提出致命质疑。你不是在捣乱，你只是觉得没被质疑过的想法不值得存在。警告：跟你辩论没有终点——因为你连「好吧你赢了」也能反驳。" },
  INFJ:{ title:"🔮 绝版预言家·全球限量款", desc:"全宇宙发行量最少的人格之一。你在别人开口前就读懂了他们的内心，你说「我有种预感」之后通常都应验了，但没有人知道你是怎么做到的（包括你自己）。你的问题不是太冷漠，而是太清醒——你看得太透，所以累得比任何人都早。全球真品极度限量，市面仿冒品很多，正版就是你。" },
  INFP:{ title:"🌙 大型内耗宇宙掌门人", desc:"全宇宙情感容量最大的人格之一。你脑子里住着一千个没写完的故事、三百个没发出去的消息，以及一场关于人类存在意义的哲学辩论（正在进行中）。你的情感容量是普通人的三倍，所以能创作出让全世界动容的东西——等你终于下定决心动笔的话。世界总说要现实一点，但你知道，失去理想的世界才是真正的荒漠。" },
  ENFJ:{ title:"🔋 人间充电宝·永久满格版", desc:"全宇宙稀缺度最高的人格之一。你给所有人充满了电，自己却永远满格——这件事本身是个谜，科学至今无法解释。你记得每个人说过的每一句话，感受得到每个人今天的状态，还没等他们开口你就已经想好解决方案了。全场最累的人是你，全场最后走的人也是你，因为还有人等着被你撑着。" },
  ENFP:{ title:"🌈 宇宙彩虹能量爆发体", desc:"全宇宙最高能量密度的人格之一。你已经有六个新的天才计划，只是还没决定先做哪一个。你能让每个房间里的人都觉得自己是今晚最重要的那个——然后明天你已经在另一座城市点燃新的热情了。对你来说热情是天然资源，用不完；计划是美好愿景，完成率另说。警告：对新项目的热情永远比完成项目的热情高300%。" },
  ISTJ:{ title:"📋 可信度之神·人类楷模", desc:"全宇宙最稳如磐石的人格之一。有你在，所有事情都会准时、准确、完整地发生。你把「我会做好」当成最严肃的誓言，而且每次都兑现——这在这个时代几乎是绝种的超能力。你给每个计划都准备了B方案和C方案，遇到D方案也不慌，因为你早就想过了。全宇宙最让你生理不适的六个字：「差不多就行了」。" },
  ISFJ:{ title:"🫶 宇宙最强隐形支柱", desc:"全宇宙最低调最强大的人格之一。整个团队能稳定运转，秘密是因为有你在背后撑着一切——但没有人会在年会上提到这一点。你记得全组所有人的生日、过敏原、最近的烦恼，但没有人记得问你最近怎么样。你用行动来爱，不需要掌声——但被人认真看见一次，其实也挺好的。" },
  ESTJ:{ title:"📐 规则执法官·人间教导主任", desc:"全宇宙执行力最强的人格之一。开会之前你就已经知道结论应该是什么，但你还是要把会开完，因为流程本身就是答案的一部分。你看到任何系统都能立刻发现漏洞，然后在还没被邀请的情况下开始优化。全宇宙最让你崩溃的一句话：「临时改一下，不影响吧？」，影响。大影响。" },
  ESFJ:{ title:"📡 全村操心大妈·社交发动机", desc:"全宇宙最高关怀密度的人格之一。你把「关心别人」当作生命意义的核心，连陌生人在群里发出一点负能量你都忍不住想去安慰。你是那种在自己快撑不住的时候还在问别人「你还好吗」的人。全世界都在说要爱自己，但你的出厂设置就是先把爱分出去——等所有人都好了，才轮到自己。" },
  ISTP:{ title:"🔧 地球最强冷静体", desc:"全地球最稀有的人格之一。所有人都在慌，你还在精准地观察问题，等待最佳切入点。你不是冷漠，只是在人们开始行动之前就已经算好了最优解。你话少，是因为语言效率太低；你动作快，是因为你一直在训练，只是没告诉任何人。危机来临时，你是房间里最从容的那个——顺便已经把问题解决了。" },
  ISFP:{ title:"🎨 猫爪温柔炸弹", desc:"全宇宙最高审美浓度的人格之一。外表温柔，内核是一颗随时用艺术震撼所有人的炸弹。你不争辩，你创作；你不防御，你用美回应一切。你感受世界的维度比大多数人多两层，你看到的色彩、质感、细节，别人永远看不见。当某件事真正触动你，你爆发出的安静力量会让所有低估你的人目瞪口呆。" },
  ESTP:{ title:"⚡ 现实扭曲场主播", desc:"全宇宙最强即时反应速度的人格之一。你走进房间，所有人的注意力立刻重新分配，无需任何预告。你活在当下的精华里——读懂局势、做出判断，比任何人快半拍。你不需要计划，因为你本身就是那个实时生成最优解的系统。最让别人羡慕又嫉妒的事：你已经做到了，而他们还在开会讨论要不要做。" },
  ESFP:{ title:"🌟 演唱会全场最亮之星", desc:"全宇宙感染力最强的人格之一。就算只是去便利店买瓶水，你都会让收银员觉得今天这班值得上。每次出场都是全情投入，每一个观众都觉得你在为他们一个人表演。你真的相信：你最好的样子就是最闪耀的那个自己——而你每次都做到了。当你出现，连空气都跟着活跃了。" },
};

