const SBTI_EN = {
  INTJ:{title:'🧠 The Grand Architect',desc:'One of the rarest minds on Earth. While others debate today\'s agenda, you\'ve already mapped out the next decade. You don\'t attend meetings to learn — you attend to wait for everyone else to catch up. Strategic moat. Precision curation. They need a few more upgrades before they can understand you.'},
  INTP:{title:'🔬 Translator of Alien Thought',desc:'One of the hardest personalities to truly understand. When you appear to be daydreaming, you\'re independently deriving the seventh-layer theory. Your browser always has 47+ tabs — each one "critically important reading, eventually." Your deepest fear: spending 20 minutes with someone who doesn\'t think.'},
  ENTJ:{title:'👑 Born at Max Level',desc:'One of the rarest personalities on Earth. While others grind in the beginner zone, you\'re already watching the end-credits easter egg. You see the world like a veteran player watching a tutorial — inefficiency here, chaos there — and somehow end up in command, though you never planned to be.'},
  ENTP:{title:'🗣 Debate Club Perpetual President',desc:'One of the universe\'s strongest arguers. Your mind runs 30 simultaneous counterarguments, each capable of dismantling someone\'s worldview. You deliver a lethal objection at precisely the second someone feels most certain. You\'re not causing trouble — you just believe unquestioned ideas don\'t deserve to exist.'},
  INFJ:{title:'🔮 Rare Edition Prophet',desc:'The least common personality in the universe. You read people\'s hearts before they speak; your predictions reliably come true — nobody knows how, including you. Your problem isn\'t coldness, it\'s clarity — you see too deeply, so you exhaust yourself earlier than anyone. Authentic edition. Extremely limited.'},
  INFP:{title:'🌙 Grand Master of the Inner Universe',desc:'One of the universe\'s largest emotional containers. Your mind holds a thousand unfinished stories, 300 unsent messages, and an ongoing philosophical debate on the meaning of existence. Your emotional capacity is triple the average — which is why you can create things that move the whole world, once you finally decide to start.'},
  ENFJ:{title:'🔋 Human Power Bank — Always Full',desc:'One of the universe\'s scarcest personalities. You charge everyone else to full and remain perpetually full yourself — science cannot explain it. You remember every word everyone has ever said, sense each person\'s mood before they speak, and have solutions ready before they ask. Last to leave, because someone always needs to be held up.'},
  ENFP:{title:'🌈 Cosmic Rainbow Energy Burst',desc:'One of the universe\'s highest-energy personalities. You already have six new genius projects — you just haven\'t decided which to start. You make everyone in every room feel like the most important person of the evening, then you\'re in another city igniting new passion tomorrow. Enthusiasm is renewable; completion rates are a separate discussion.'},
  ISTJ:{title:'📋 God of Reliability',desc:'One of the universe\'s most rock-solid personalities. With you around, everything happens on time, accurately, and completely. "I\'ll get it done" is your most solemn oath — and you always deliver. Every plan has a Plan B and C; if Plan D appears you\'re already ahead of it. Six most painful words: "Close enough is fine."'},
  ISFJ:{title:'🫶 Universe\'s Invisible Pillar',desc:'One of the universe\'s quietest yet most powerful personalities. The whole team runs smoothly because you\'re holding everything up from behind — but nobody mentions it at the year-end meeting. You remember everyone\'s birthdays, allergies, and worries, yet nobody thinks to ask how you\'re doing. Loved through action, no applause needed.'},
  ESTJ:{title:'📐 Rule Enforcer · The Director',desc:'One of the universe\'s strongest executors. Before the meeting starts you already know what the conclusion should be, but you sit through it anyway — process is part of the answer. You spot every loophole in any system and begin optimizing before being invited. Most infuriating sentence: "Just tweak it, no big deal." Wrong. Very big deal.'},
  ESFJ:{title:'📡 Village\'s Chief Worrier · Social Engine',desc:'One of the universe\'s highest-care-density personalities. You treat caring for others as the core of life\'s meaning — you can\'t stop yourself from comforting even strangers posting something negative in a chat. You\'re still asking "Are you okay?" when you\'re barely holding on yourself. The factory setting ships love out first.'},
  ISTP:{title:'🔧 Earth\'s Coolest Head',desc:'One of Earth\'s rarest personalities. While everyone panics, you\'re precisely observing and waiting for the optimal intervention point. Not cold — you\'ve calculated the best solution before others begin acting. Few words, because language is inefficient; fast hands, because you\'ve been quietly training all along. Crisis arrives, you\'ve already solved it.'},
  ISFP:{title:'🎨 Gentle Bomb with Cat\'s Paws',desc:'One of the universe\'s highest-aesthetic personalities. Soft exterior, explosive core — a bomb ready to shock everyone with art at any moment. You don\'t argue; you create. You don\'t defend; you respond with beauty. You perceive the world in two more dimensions than most — colors, textures, details nobody else can see.'},
  ESTP:{title:'⚡ Reality Distortion Field Broadcaster',desc:'One of the universe\'s fastest real-time reactors. You walk into a room and everyone\'s attention instantly redistributes — no announcement needed. You live in the premium present: reading the situation, deciding, half a beat ahead of anyone. You don\'t need a plan — you ARE the system generating optimal solutions in real time.'},
  ESFP:{title:'🌟 Brightest Star at Every Concert',desc:'One of the universe\'s most contagious personalities. Even a trip to the convenience store makes the cashier feel the shift was worth it. Every entrance is full-commitment performance; every audience member feels you\'re performing just for them. You believe your best self is your most radiant self — and you deliver every single time.'},
};

// ── Language-aware getters (zh_CN/zh_TW → Chinese constants; all others → English) ─
function isZhLang(){ return lang==='zh_CN'||lang==='zh_TW'; }
function getAnimalName(type){ return isZhLang()?(MBTI_ANIMAL[type]||''):(MBTI_ANIMAL_EN[type]||MBTI_ANIMAL[type]||''); }
function getColorData(type) { return isZhLang()?(MBTI_COLOR[type]||{name:'',hex:'#666'}):(MBTI_COLOR_EN[type]||MBTI_COLOR[type]||{name:'',hex:'#666'}); }
function getEnneagram(type) { return isZhLang()?(ENNEAGRAM[type]||''):(ENNEAGRAM_EN[type]||ENNEAGRAM[type]||''); }
function getSbti(type)      { return isZhLang()?(SBTI[type]||{title:'',desc:''}):(SBTI_EN[type]||SBTI[type]||{title:'',desc:''}); }

function getAvatarUrl(type, gender) {
  // Real AI-generated images from weweweai.com (96 unique images, AI-generated via Google Imagen)
  const slot = (gender === 'male') ? 1 : 2;
  return 'https://weweweai.com/avatars/' + type.toLowerCase() + '-' + slot + '.png?v3';
}
function getFallbackAvatarUrl(type, gender) {
  const g = gender === 'male' ? 'adventurer-neutral' : 'adventurer';
  return 'https://api.dicebear.com/7.x/' + g + '/svg?seed=' + type.toLowerCase() + '&size=256';
}

// Questions (dims: EI SN TF JP × 9 questions)
const QDIMS = ['EI','SN','TF','JP','EI','SN','TF','JP','SN'];

// ── State ────────────────────────────────────────────────────────────────────
let lang = 'en';
let gender = null;
let current = 0;
let answers = {};
const STORAGE_KEY = 'mbti_result_v8';

// ── i18n ─────────────────────────────────────────────────────────────────────
function t(key) {
  return (I18N[lang] && I18N[lang][key]) || (I18N['en'] && I18N['en'][key]) || '';
}

// ── Screen switching ──────────────────────────────────────────────────────────
function showScreen(id) {
  document.querySelectorAll('.screen').forEach(s => s.classList.remove('active'));
  document.getElementById('screen-' + id).classList.add('active');
}

function goIntro() { showScreen('intro'); updateIntroText(); }
function goGender() { showScreen('gender'); updateGenderText(); }

function openSite() { window.open('https://weweweai.com', '_blank'); }

function updateResultText() {
  setText('result-screen-label', t('result.title') || 'Results');
  const retakeTop = document.getElementById('btn-retake-top');
  if (retakeTop) retakeTop.textContent = t('result.retake') || 'Retake';
  const dlAvatar = document.getElementById('btn-dl-avatar');
  if (dlAvatar) dlAvatar.textContent = t('result.dlAvatar') || 'Download Avatar';
  const dlCard = document.getElementById('btn-dl-card');
  if (dlCard) dlCard.textContent = t('result.dlCard') || 'Download Personality Card';
}

// ── Language ─────────────────────────────────────────────────────────────────
function changeLang(v) {
  lang = v;
  document.querySelectorAll('.lang-select').forEach(s => s.value = v);
  const active = document.querySelector('.screen.active');
  if (active) {
    const id = active.id.replace('screen-', '');
    if (id === 'intro') updateIntroText();
    else if (id === 'gender') updateGenderText();
    else if (id === 'quiz') updateQuizText();
    else if (id === 'result') {
      updateResultText();
      try {
        const _s = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
        if (_s.mbtiType) renderResult(_s.mbtiType, getAvatarUrl(_s.mbtiType, _s.gender||'female'));
      } catch(_e) {}
    }
  }
  try { localStorage.setItem('mbti_lang', v); } catch(e){}
  try { chrome.storage.local.set({ mbti_lang: v }); } catch(e){}
}

function updateIntroText() {
  setText('intro-title', t('persona.intro.title'));
  setText('intro-sub', t('persona.intro.subtitle'));
  setText('f1label', t('persona.intro.f1label'));
  setText('f1sub', t('persona.intro.f1sub'));
  setText('f2label', t('persona.intro.f2label'));
  setText('f2sub', t('persona.intro.f2sub'));
  setText('f3label', t('persona.intro.f3label'));
  setText('f3sub', t('persona.intro.f3sub'));
  setText('f4label', t('persona.intro.f4label'));
  setText('f4sub', t('persona.intro.f4sub'));
  setText('btn-start', t('persona.intro.start'));
  setText('ennea-desc', t('persona.intro.enneagramDesc') || 'The Enneagram is a personality system beloved by entrepreneurs and celebrities worldwide. Combined with MBTI it delivers deeper self-insight.');
}

function updateGenderText() {
  setText('gender-title', t('persona.gender.title'));
  setText('gender-sub', t('persona.gender.subtitle'));
  setText('gender-male', t('persona.gender.male'));
  setText('gender-female', t('persona.gender.female'));
  setText('btn-confirm-gender', t('persona.gender.confirm'));
}

function setText(id, text) {
  const el = document.getElementById(id);
  if (el) el.textContent = text;
}

// ── Gender selection ──────────────────────────────────────────────────────────
function selectGender(g) {
  gender = g;
  document.getElementById('card-male').classList.toggle('selected', g === 'male');
  document.getElementById('card-female').classList.toggle('selected', g === 'female');
  const btn = document.getElementById('btn-confirm-gender');
  btn.style.opacity = '1';
  btn.style.pointerEvents = 'auto';
}

function startQuiz() {
  if (!gender) return;
  current = 0;
  answers = {};
  showScreen('quiz');
  updateQuizText();
}

// ── Quiz logic ────────────────────────────────────────────────────────────────
const SCORE_MAP = {1:3, 2:2, 3:1, 4:-1, 5:-2, 6:-3};

function updateQuizText() {
  const total = 9;
  const qNum = current + 1;
  const counterTpl = t('persona.quiz.counter') || 'Q{current} / {total}';
  setText('q-counter', counterTpl.replace('{current}', qNum).replace('{total}', total));
  setText('btn-reset', t('persona.quiz.reset'));
  
  const qKey = 'quiz.q' + qNum;
  setText('q-text', t(qKey + '.text'));
  setText('q-a-label', t(qKey + '.a'));
  setText('q-b-label', t(qKey + '.b'));
  
  const fill = (current / total * 100);
  document.getElementById('progress-fill').style.width = fill + '%';
}

function answer(score) {
  const qNum = current + 1;
  answers[qNum] = score;
  if (current + 1 < 9) {
    current++;
    updateQuizText();
  } else {
    computeAndShow();
  }
}

function computeAndShow() {
  const QDIMS_MAP = {1:'EI',2:'SN',3:'TF',4:'JP',5:'EI',6:'SN',7:'TF',8:'JP',9:'SN'};
  const scores = {EI:0,SN:0,TF:0,JP:0};
  for (let i = 1; i <= 9; i++) {
    const ans = answers[i];
    if (ans !== undefined) {
      scores[QDIMS_MAP[i]] += SCORE_MAP[ans];
    }
  }
  const ansVals = Object.values(answers);
  const tieHash = ansVals.reduce((h,v,i) => ((h*31 + v*(i+3))|0), 0x9e3779b9);
  const pick = (score, bit, pos, neg) => score > 0 ? pos : score < 0 ? neg : (tieHash >> bit) & 1 ? pos : neg;
  const type = pick(scores.EI,0,'E','I') + pick(scores.SN,2,'S','N') + pick(scores.TF,4,'T','F') + pick(scores.JP,6,'J','P');
  
  const variantIndex = (ansVals.reduce((s,v)=>s+v,0)) % 3;
  const avatarUrl = getAvatarUrl(type, gender);
  
  try {
    localStorage.setItem(STORAGE_KEY, JSON.stringify({answers, mbtiType: type, gender, avatarUrl, createdAt: Date.now()}));
  } catch(e) {}
  // Also save to chrome.storage.local so eye-overlay content script can read it across all tabs
  try {
    chrome.storage.local.set({ weweweai_mbti_result: { mbtiType: type, gender, ts: Date.now() } });
  } catch(e) {}
  
  renderResult(type, avatarUrl);
}

function renderResult(type, avatarUrl) {
  // Try to load from storage if not passed
  if (!type) {
    try {
      const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
      if (saved.mbtiType) {
        type = saved.mbtiType;
        gender = saved.gender || 'female';
        answers = saved.answers || {};
        avatarUrl = saved.avatarUrl || getAvatarUrl(type, gender);
      }
    } catch(e) {}
  }
  if (!type) return;
  
  const color  = getColorData(type);
  const animal = getAnimalName(type);
  const character = MBTI_CHARACTERS[type] || '';
  const enneagram = getEnneagram(type);
  const sbti  = getSbti(type);
  const parodyName = t('mbti.' + type + '.parodyName') || type;
  const description = t('mbti.' + type + '.description') || '';
  const animalDesc = t('mbti.' + type + '.animalDesc') || '';
  const colorDesc = t('mbti.' + type + '.colorDesc') || '';
  const traits = [t('mbti.'+type+'.t1'),t('mbti.'+type+'.t2'),t('mbti.'+type+'.t3'),t('mbti.'+type+'.t4')].filter(Boolean);
  
  // Compute hue from hex
  const hex = color.hex.replace('#','');
  const r = parseInt(hex.slice(0,2),16)/255, g = parseInt(hex.slice(2,4),16)/255, b = parseInt(hex.slice(4,6),16)/255;
  const mx = Math.max(r,g,b), mn = Math.min(r,g,b);
  let hue = 0;
  if (mx !== mn) {
    switch(mx) {
      case r: hue = ((g-b)/(mx-mn)+(g<b?6:0))/6; break;
      case g: hue = ((b-r)/(mx-mn)+2)/6; break;
      case b: hue = ((r-g)/(mx-mn)+4)/6; break;
    }
  }
  const hd = Math.round(hue*360);
  const avatarBg = 'linear-gradient(150deg,hsl('+hd+',85%,80%) 0%,hsl('+hd+',72%,62%) 100%)';
  
  const card = document.getElementById('result-card');
  const accentLight = 'hsl('+hd+',90%,75%)';
  const accentMid   = 'hsl('+hd+',70%,60%)';
  const lAnimal      = t('label.animal')      || 'Totem';
  const lPersonality = t('label.personality') || 'Personality';
  const lMount       = t('label.mount')       || 'Mount';
  const lMountColor  = t('label.mountColor')  || 'Mount × Color';
  const lTraits      = t('label.traits')      || 'Core Traits';
  const lKnight      = t('label.knight')      || 'Rider';
  const traitsHTML   = traits.length > 0
    ? '<div class="result-section-label">'+lTraits+'</div>'
      + '<div class="result-desc">'
      + traits.map(tr => '<div class="trait-row"><div class="trait-dot" style="background:'+accentMid+'"></div><div class="trait-text">'+tr+'</div></div>').join('')
      + '</div>'
    : '';

  card.innerHTML = `
    <div class="avatar-header" style="background:${avatarBg}">
      <img class="avatar-img" id="avatar-img-${type}" src="${avatarUrl}" alt="${type}">
      <div class="type-badge">${type}</div>
    </div>
    <div class="result-body">
      <div class="result-name" style="color:${accentLight}">${parodyName}</div>
      <div class="result-char">${character}</div>
      <div class="tags-row">
        <span class="tag-animal">${lAnimal}：${animal}</span>
        <span class="tag-ennea">${enneagram}</span>
        <span class="tag-type">${color.name}</span>
      </div>

      <div class="result-section-label">${lPersonality}</div>
      <div class="result-desc">
        <div>${description}</div>
      </div>

      <div class="result-section-label">${lMount}</div>
      <div class="sbti-block">
        <div class="sbti-title" style="color:${accentMid}">${sbti.title}</div>
        <div class="sbti-desc">${sbti.desc}</div>
      </div>

      <div class="result-section-label">${lMountColor}</div>
      <div class="detail-blocks">
        <div class="detail-item">
          <div class="box-label">${lMount}</div>
          <div class="box-val">${animal} ${lKnight}</div>
          <div class="box-sub">${animalDesc}</div>
        </div>
        <div class="detail-item">
          <div class="box-label">${color.name}</div>
          <div class="box-val" style="display:flex;align-items:center;gap:6px">
            <span style="display:inline-block;width:12px;height:12px;border-radius:50%;background:${color.hex};flex-shrink:0"></span>${color.name}
          </div>
          <div class="box-sub">${colorDesc}</div>
        </div>
      </div>

      ${traitsHTML}
    </div>
  `;

  // Bind image error handler WITHOUT inline onerror (MV3 CSP compliance)
  const imgEl = document.getElementById('avatar-img-' + type);
  if (imgEl) {
    imgEl.addEventListener('error', () => {
      const fb = getFallbackAvatarUrl(type, gender || 'female');
      if (imgEl.src !== fb) imgEl.src = fb;
    });
  }

  showScreen('result');
}

function resetQuiz() {
  current = 0;
  answers = {};
  gender = null;
  try { localStorage.removeItem(STORAGE_KEY); } catch(e) {}
  document.getElementById('card-male').classList.remove('selected');
  document.getElementById('card-female').classList.remove('selected');
  const btn = document.getElementById('btn-confirm-gender');
  btn.style.opacity = '0.4';
  btn.style.pointerEvents = 'none';
  showScreen('intro');
  updateIntroText();
}

// ── Helper: compute MBTI hue from hex ────────────────────────────────────────
function mbtiHue(type) {
  const hex = ((MBTI_COLOR[type] || {}).hex || '#6c95ff').replace('#','');
  const r=parseInt(hex.slice(0,2),16)/255, gv=parseInt(hex.slice(2,4),16)/255, b=parseInt(hex.slice(4,6),16)/255;
  const mx=Math.max(r,gv,b), mn=Math.min(r,gv,b);
  let h=0;
  if(mx!==mn){switch(mx){case r:h=((gv-b)/(mx-mn)+(gv<b?6:0))/6;break;case gv:h=((b-r)/(mx-mn)+2)/6;break;default:h=((r-gv)/(mx-mn)+4)/6;}}
  return Math.round(h*360);
}

// ── Helper: wrap text for canvas ─────────────────────────────────────────────
function canvasWrap(ctx, text, maxW) {
  const chars = [...text]; let lines=[], cur='';
  for (const ch of chars) {
    if (ctx.measureText(cur+ch).width > maxW) { lines.push(cur); cur=ch; }
    else cur+=ch;
  }
  if (cur) lines.push(cur);
  return lines;
}

// ── Download 1: just the anime avatar image ───────────────────────────────────
async function downloadAvatar() {
  const btn = document.getElementById('btn-dl-avatar');
  const gen = t('result.generating') || 'Generating…';
  const lbl = t('result.dlAvatar')   || 'Download Avatar';
  if (btn) { btn.textContent = gen; btn.disabled = true; }
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    const type = saved.mbtiType || '';
    const g    = saved.gender   || 'female';
    const src  = getAvatarUrl(type, g);
    const resp = await fetch(src);
    const blob = await resp.blob();
    const a = document.createElement('a');
    a.href = URL.createObjectURL(blob);
    a.download = 'weweweai-avatar-' + type + '.png';
    a.click();
    URL.revokeObjectURL(a.href);
  } catch(e) { alert('Download failed'); }
  finally { if (btn) { btn.textContent = lbl; btn.disabled = false; } }
}

// ── Download 2: full personality card canvas ──────────────────────────────────
async function downloadPersonality() {
  const btn = document.getElementById('btn-dl-card');
  const gen = t('result.generating') || 'Generating…';
  const lbl = t('result.dlCard')     || 'Download Card';
  if (btn) { btn.textContent = gen; btn.disabled = true; }
  try {
    // ── Step 1: fetch avatar → local blob URL so html2canvas can render it ──
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    const type  = saved.mbtiType || '';
    const g     = saved.gender   || 'female';
    const imgEl = document.getElementById('avatar-img-' + type);
    let blobUrl = null;
    if (imgEl) {
      try {
        const resp = await fetch(imgEl.src || getAvatarUrl(type, g));
        const blob = await resp.blob();
        blobUrl = URL.createObjectURL(blob);
        imgEl.src = blobUrl;           // swap to same-origin blob URL
        // wait for image to re-paint
        await new Promise(res => {
          if (imgEl.complete) res();
          else { imgEl.onload = res; imgEl.onerror = res; }
        });
      } catch(fe) {}
    }

    // ── Step 2: add temporary watermark at bottom of card ───────────────────
    const card = document.getElementById('result-card');
    const wm = document.createElement('div');
    wm.id = 'dl-watermark';
    wm.style.cssText = 'text-align:center;padding:10px 0 14px;font-size:12px;color:#888;font-family:-apple-system,sans-serif';
    wm.textContent = 'weweweai.com';
    card.appendChild(wm);

    // ── Step 3: temporarily switch card to light theme for clean download ────
    // Override CSS custom properties on the card element so html2canvas sees
    // light colours; these are restored immediately after capture.
    const lightVars = {
      '--s1': '#ffffff', '--s2': '#f4f4f8',
      '--b0': 'rgba(0,0,0,0.06)', '--b1': 'rgba(0,0,0,0.10)', '--b2': 'rgba(0,0,0,0.18)',
      '--t1': '#111118', '--t2': '#44445a', '--t3': '#888898',
    };
    Object.entries(lightVars).forEach(([k,v]) => card.style.setProperty(k, v));
    // Also override .result-body and nested sections in case they inherit separately
    const allSubs = card.querySelectorAll('*');
    allSubs.forEach(el => {
      el.style.setProperty('--s1', '#ffffff');
      el.style.setProperty('--s2', '#f4f4f8');
      el.style.setProperty('--b1', 'rgba(0,0,0,0.10)');
      el.style.setProperty('--b2', 'rgba(0,0,0,0.18)');
      el.style.setProperty('--t1', '#111118');
      el.style.setProperty('--t2', '#44445a');
      el.style.setProperty('--t3', '#888898');
    });
    // Wait one frame so styles apply before capture
    await new Promise(r => requestAnimationFrame(r));

    // ── Step 4: html2canvas capture full card ────────────────────────────────
    const canvas = await html2canvas(card, {
      useCORS: false,
      allowTaint: true,
      backgroundColor: '#ffffff',
      scale: 2,
      logging: false,
      width:  card.scrollWidth,
      height: card.scrollHeight,
      windowWidth:  card.scrollWidth,
      windowHeight: card.scrollHeight,
    });

    // ── Step 5: restore dark theme & clean up temporaries ────────────────────
    Object.keys(lightVars).forEach(k => card.style.removeProperty(k));
    allSubs.forEach(el => {
      ['--s1','--s2','--b1','--b2','--t1','--t2','--t3'].forEach(k => el.style.removeProperty(k));
    });
    card.removeChild(wm);
    if (blobUrl) {
      URL.revokeObjectURL(blobUrl);
    }

    // ── Step 5: download ────────────────────────────────────────────────────
    canvas.toBlob(outBlob => {
      const a = document.createElement('a');
      a.href = URL.createObjectURL(outBlob);
      a.download = 'weweweai-' + (type || 'mbti') + '-personality.png';
      a.click();
      URL.revokeObjectURL(a.href);
    }, 'image/png');
  } catch(e) {
    console.error(e);
    alert('Download failed');
  }
  finally { if (btn) { btn.textContent = lbl; btn.disabled = false; } }
}

// ── Init + Event listeners (MV3 compliant) ───────────────────────────────
document.addEventListener('DOMContentLoaded', () => {
  // Restore lang and sync to chrome.storage.local so content scripts can read it
  try {
    const savedLang = localStorage.getItem('mbti_lang');
    if (savedLang && I18N[savedLang]) {
      lang = savedLang;
      document.querySelectorAll('.lang-select').forEach(s => s.value = lang);
    }
    // Always push current lang to chrome.storage.local (content scripts can't read localStorage)
    chrome.storage.local.set({ mbti_lang: lang });
  } catch(e) {}

  updateIntroText();

  // Check for saved result — show it immediately
  try {
    const saved = JSON.parse(localStorage.getItem(STORAGE_KEY) || '{}');
    if (saved.mbtiType && saved.answers && Object.keys(saved.answers).length === 9) {
      answers = saved.answers;
      gender = saved.gender || 'female';
      renderResult(saved.mbtiType, saved.avatarUrl || getAvatarUrl(saved.mbtiType, gender));
      // Still bind events below so retake works
    }
  } catch(e) {}

  // Language selects
  document.querySelectorAll('.lang-select').forEach(s => {
    s.addEventListener('change', () => changeLang(s.value));
  });

  // Intro screen
  const btnStart = document.getElementById('btn-start');
  if (btnStart) btnStart.addEventListener('click', goGender);
  const btnOpenSite = document.getElementById('btn-open-site');
  if (btnOpenSite) btnOpenSite.addEventListener('click', openSite);

  // Gender screen
  const btnBackIntro = document.getElementById('btn-back-intro');
  if (btnBackIntro) btnBackIntro.addEventListener('click', goIntro);
  const cardMale = document.getElementById('card-male');
  if (cardMale) cardMale.addEventListener('click', () => selectGender('male'));
  const cardFemale = document.getElementById('card-female');
  if (cardFemale) cardFemale.addEventListener('click', () => selectGender('female'));
  const btnConfirmGender = document.getElementById('btn-confirm-gender');
  if (btnConfirmGender) btnConfirmGender.addEventListener('click', startQuiz);

  // Quiz screen
  const btnBackGender = document.getElementById('btn-back-gender');
  if (btnBackGender) btnBackGender.addEventListener('click', goGender);
  const btnReset = document.getElementById('btn-reset');
  if (btnReset) btnReset.addEventListener('click', resetQuiz);

  // Answer buttons (data-score)
  document.querySelectorAll('.ans-btn[data-score]').forEach(btn => {
    btn.addEventListener('click', () => answer(parseInt(btn.dataset.score)));
  });

  // Result screen
  const btnRetakeTop = document.getElementById('btn-retake-top');
  if (btnRetakeTop) btnRetakeTop.addEventListener('click', resetQuiz);
  const btnDlAvatar = document.getElementById('btn-dl-avatar');
  if (btnDlAvatar) btnDlAvatar.addEventListener('click', downloadAvatar);
  const btnDlCard = document.getElementById('btn-dl-card');
  if (btnDlCard) btnDlCard.addEventListener('click', downloadPersonality);
  const btnVisitSite = document.getElementById('btn-visit-site');
  if (btnVisitSite) btnVisitSite.addEventListener('click', openSite);

  updateResultText();
});
